window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20220628-5","meetingId":"r04-cm06","date":"2022年6月28日","dateIso":"2022-06-28","committee":"総務委員会","time":"午前１０時００分～午前１１時４９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"歳入のところでちょっと教えていただきたいのですが、１１ページの区分のところで、新型コロナウイルス感染症対応地方創生臨時交付金と、とうきょうママパパ応援事業補助金と、生活応援事業補助金と３種類書かれているのですけれども、この内訳のところを後のほうで見ると、全部都支出金となっていますし、歳入のところでも都補助金になっているのですけれども。","respondent":"黒田財政課長","answer":"令和４年度の新型コロナウイルス感染症対応地方創生臨時交付金につきましては、現在国のほうで交付の条件の内示額ということで、７億１,６５０万円ほど内示をいただいておりますが、この後、例年ですと年度途中に追加の交付等の決定もありますので、これで総額ではありませんが。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"分かりました。それからあと、総務費のところで、１３ページのウクライナ避難民支援経費ということなのですけれども、これの具体的なご説明がなかったので、２１８万４,０００円ということなのですが、これをどういうふうに使っていくのかということを伺いたいと思います。それで、品川区に避難民が今実際にどれぐらい来られているのか、そのことも教えていただきたいと思います。","respondent":"古巻総務課長","answer":"人数的なところで言うと、あまりたくさんいらっしゃるというような見込みではないので、一応 ２０人分ということで予算を取らせていただきましたので。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ウクライナから避難されてきた方が本当に慣れないところですごく大変な思いをされているというのがネットでもかなりいろいろな事例みたいな形で出されていたりするのですけれども、例えば原発事故で福島から品川区に避難してきた方には区民住宅を提供したりとか、さまざまな支援があったと思うのですけれども、そういう点では区民住宅を提供するとか、それから、今。","respondent":"古巻総務課長","answer":"住宅に関しては、住むところがない方、要は都内に身寄りがない方に関しては、東京都のほうが都営住宅の提供などもしていますので、そういったところへつなげたりとか、さまざまな形で支援をさせていただいているという状況です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"総務委員会はこういう補正予算の総合審査ということなので、なぜ補正予算になったのかというところなのですけれども、建設委員会の資料を見ると、区内を通過する新線が令和３年１月に国土交通省から事業許可がされて、２０２９年開業を目指しているということでされているので、去年の１月に既に事業許可がされているわけですから、もしもこういう予算を組むとしても。","respondent":"黒田財政課長","answer":"その感じでいきますと、開業の予定を令和１１年というふうにしておりますので、調査・設計でありますとか工事の期間にそれぞれ３年程度ずつかかるということからしますと、もし区内に新駅を設置するということであれば、ＪＲの事業の調査・設計のところに。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、長期基本計画の中で新駅の設置に向けた要望を行っているので、これも検討するということであるのですけれども、そこのところは五反田、大崎、大井町のさらなる活性化を図るために働きかけるとともに新駅を設置していくと書かれているのです。この新駅設置がなぜ五反田、大崎、大井町の活性化につながるのか、その点についても伺いたいと思います。","respondent":"黒田財政課長","answer":"なぜ五反田、大崎、大井町の活性化につながるのかというところにつきましては、いわゆる今回事業許可を取っておりますのは東山手ルートになりますが、ＪＲのほうで大きな３つの計画を立てておりまして、西山手ルート、東山手ルート、臨海部ルートということで。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"新駅を造る場所というのは、大崎、大井町とか、八潮の東京貨物ターミナルのあたりではないところの可能性というのも探るということなのでしょうか。そうすると、どういうところに駅を造れる可能性を考えられているのか。","respondent":"鈴木（真）委員長、黒田財政課長","answer":"ちょっとごめんなさい。都市計画課として出している中で、企画部としてどこまで答えられるか。そこの仕切りがあると思うので、答えられる範囲で。予算の中で検討するのは、今３つのルートが計画されていて、どこに駅が、可能性があるかというところを土地利用の状況等を把握して検討するというところを予算で掲げておりますので。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません、今のに続けて確認したいのですが、所管を超えたら指摘をしていただきたいと思うのですけれども、先ほど検討するのに委託ということで、関連事業者ということでした。これは品川区が選ぶという理解でよろしいでしょうか。","respondent":"黒田財政課長","answer":"品川区が委託契約を行いますので、品川区が委託事業者を選ぶです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"それで、もう一つは、このルート、臨海部ルートというのを資料で見ているのですけれども、これは決まってしまっているのですか。このルートは、固定で、その上で検討するということの経費なのか。この中身が何をするのかよく分からないのですよ。この検討というのが。ここに品川区の住民がいないのに、何もお金をかけて検討する必要はないではないですか。何のために検討するのですか。いかがでしょうか。","respondent":"鈴木（真）委員長、黒田財政課長","answer":"先ほども言ったように建設委員会との兼ね合いがありますので、その辺を踏まえてお答えください。何のために検討するのかですが、先ほど申し上げたとおり、長期基本計画の中で、いわゆる羽田空港から東京の表玄関、都心のほうに輸送ルートとして鉄道が敷かれるということであれば。","voiceIndex":20,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"それからちょっと確認です。ウクライナ避難民支援なのですけれども、先ほど２０人程度ということでした。それから、歳入のところなのですけれども、財政調整基金のほうから出していますが、これは足りない分ということですかね。大体、都補助金が１０分の１０で来ているのだけれども、歳出のところの金額と、ちょっと足りないから財政調整基金から繰り入れるのですよという理解でよろしいでしょうか。","respondent":"古巻総務課長、黒田財政課長","answer":"ウクライナ避難民支援の関係で、人数につきましては見込みで２０人ということで、東京都からもいろいろ情報をいただいていますけれども、最大でそれぐらいかなという予測で予算を作らせていただいています。一般財源につきましては、例えばウクライナ避難民支援でありますとか、選挙の公費負担につきましては、一般財源で行うべき事業ということで計上させていただいているものです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"都と交渉して、例えば１００人ぐらいになるなどという見込みが出てきた場合には、それなりの交渉をして、補正予算がかかるのかなというふうに思っているのですが、これからの柔軟性といいますかね、ということは東京都とそういう交渉をしているのかということと、それから選挙費のほうで、何でここに補正予算がかかっているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-010"},{"speaker":"吉田委員","kind":"確認","question":"相談のところです。基本、大分何か国語も入っていると、一度何語かと伺ったのですけれども、ウクライナ語というのはどうでしたか。ウクライナ語が入っていたかどうかの確認と、もしそういうことであれば、ものすごくお金がかかるということならばまた別なのですけれども、一言語、こういう状況ですからウクライナ語を増やすというようなことのお考えはないのか、お尋ねしたいと思います。","respondent":"古巻総務課長","answer":"これについては区役所で何台か持っていますので、今総務課のほうに借りていまして、場合によっては対応をということですが、大体英語ができる方というのも多いですし、日本人の支援者が一緒にいらっしゃっているというケースもあるので。","voiceIndex":29,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"前にタブレットのことを伺ったときも大体３か国語で間に合うというふうに伺ったことがあるので、英語とか、品川区においては韓国語と中国語で大体対応できると伺っていたのですけれども、事態が事態ですので、行った先に母語が用意されていたということになると、それだけでもすごくほっとするところがあるのではないかなと思います。この考え方は変わっていませんよね、というのを一つ伺いたいと思います。","respondent":"黒田財政課長","answer":"予算の考え方につきましては、今ご指摘がありましたとおり、当初予算のほうで１年間の事業の歳入歳出の計画を立てまして、予算の組立てをしておりますので、そこで議決をいただきまして、その後の状況の変化によりまして、それが国等の動きでありましたり。","voiceIndex":31,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"早い時期に動かないと品川区の考え方は入れ込めないねというふうになるわけではないですか。そうしたら、何で当初予算ではなかったのかということは、今のことを伺っても、本当にどうしても理解ができないのです。そうすると、長期基本計画で考えたときの考え方がそこまできちんと組み立てていなかったのかということになってくると思うのですけれども、やっぱり難しかったということなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の羽田空港アクセス線のことなのですけれども、ＪＲ東日本は今駅を造る方針はないということになっていると思うのです。それを区がこういうふうな形で検討して駅を造ってほしいということで要望して、ＪＲ東日本が、では造りましょうというふうになった場合は、駅を造る場合の負担というのは区も負担するようになるのか。ちょっとその点について伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"意見だけになるかもしれませんが、今の羽田空港アクセス線新駅可能性検討経費というのは、ぜひ品川区政にとっても品川区民にとっても何とか利益をもたらすように、私は頑張っていただきたいと思います。間に合うのか、間に合わないのか分かりませんが、必要に応じて、どなたか特命役員かなんかをつけてどんどん積極的に交渉していただきたいと私は思います。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-015"},{"speaker":"つる副委員長","kind":"質問・要望","question":"うちからの質問だったか、他の議員の方からの質問だったか忘れてしまったのですけれども。物品購入のものに関わってということなのですけれど。細かい部分、すみ分けとして。区独自ということで、新型コロナウイルス感染症対応地方創生臨時交付金を活用しての２万円というのは、これは物価高騰の影響ということになっているのですけれども、そこの部分の捉え方をちょっと確認させていただきたいと思います。","respondent":"黒田財政課長","answer":"子育て世帯の家事支援用品購入支援および子育て世帯サポート事業につきましては、事業の組立てとしましては、今ご指摘があったとおり家事支援用品購入支援事業は、コロナ禍において家事育児ヘルパーのサービスが行き届いていない家庭に対していわゆる家事支援用品の購入をして。","voiceIndex":38,"id":"exchange-016"},{"speaker":"つる副委員長","kind":"確認","question":"細かい部分での確認です。１点、ちょっと所管的な感じになるかもしれませんが、総合的にという視点で極力伺いたいのですが、今確認させていただいたように、用品購入のときに対象家庭があくまでも保育サービスを利用していないことが条件なのですが、例えば申請した後、この物品購入を受けた後にサービスを受けることもできないという設定でしたね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-017"},{"speaker":"大倉委員","kind":"質問","question":"避難民の方が来られてというので、ごみの出し方が分かっていないようなので、どうやってお伝えしたらいいですかねみたいな話もあるというふうに聞いておりまして、２０人ということなので、そういう方たちの不安が募らないように、何かその辺の日本のルール、マナーみたいなところの伝え方とかはやられているのだと思うのですけれども、どのようにされているのかなというのを教えていただければと思います。","respondent":"古巻総務課長","answer":"ごみの出し方ということで、今委員からご指摘がありましたけれども、そういったことにつきましては、まだ個別にいろいろ対応できるぐらいの人数でありますので、そこは個別に対応させていただいているということと、あとは一般的には、英語版。","voiceIndex":43,"id":"exchange-018"},{"speaker":"大倉委員","kind":"意見","question":"それはＬＩＮＥをお伝えして、しっかりやっていただいて、英語もしゃべれるというようなお話だったので分かるのかなと思いますが、今後２０名予定されている中で、なかなかそういうことも難しい方もいらっしゃるかもしれないので、何か分かるようにきちんとお伝えしていただければと思います。そこはよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さらにまた、先ほどもありましたけれども、区民の状況というのは大変厳しい状況がありますので、さらなる支援の検討を求めて、この補正予算全体としては賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"結論からいいます。理由を言わせていただきたいと思います。品川・生活者ネットワークは以前も総合審査というところで項目としては１つだけ反対だったのですけれども、ただ、補正予算の中にそういう形の、何だか全体は反対しにくいというか、全体は賛成が多い補正予算の中に、あるべき形ではない形で補正予算で入れてしまうということは、やはりこういうやり方はあってはならないのではないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-021"}]},{"id":"topic-02","title":"冒頭に申し上げましたとおり、取り上げる順番を変更し、(3)品川区長選挙および品川区議会議員補欠選挙における執行計画","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更し、(3)品川区長選挙および品川区議会議員補欠選挙における執行計画","exchanges":[{"speaker":"吉田委員","kind":"提案","question":"と申しますのは、最初に提案されたときの次の選挙のときにちょっと調査をかけたのです。せっかく選挙管理委員会のほうで税金を使ってそういうものを用意されたのに活用されていなくて残念だったなと思ったことがあるので、ぜひそういうものはきちんと活用していただきたいという思いで現状を確認させてください。出せるのだけれども、出していないのでしょうか。その辺についても教えてください。","respondent":"鈴木選挙管理委員会事務局長","answer":"投票事務の事務長の説明会が必ず選挙ごとにやっておりますので、その席で改めて徹底できるように周知をしてまいります。","voiceIndex":59,"id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"「遅い」と叱られたのですけれども、誰かが読んで作るということがあると思うのですけれども、もちろん届出がないうちに選挙公報を作るわけにいかないので、一定制約があることは重々承知しているのですけれども、その辺の仕組みといいますか、ちょっと私はそういうシステムのことが疎いのですけれども、誰がそういう音声にして、どういう形で視覚障害者のお手元に届くのか。","respondent":"鈴木選挙管理委員会事務局長","answer":"したがいまして、委員からもご指摘がありましたように、立候補の手続が終わってからでないと調製、配布の準備ができませんので、どうしても選挙期日間近になってしまうというのが現状です。","voiceIndex":61,"id":"exchange-023"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。どういうふうにしたら私たちとしても早く届けられるか。だから、努力しなければいけないということですよね。具体的にどうしたら早く当事者のお手元に届くのかということは、また後で伺いたいと思います。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"１点だけ。ちょっと確認をしてほしいのですが、公営ポスター掲示板の設置場所に対しては、いろいろご尽力くださったり、ご苦労されていると思います。それはよくわかります。このたび、参議院議員選挙から、小山３－２３－２３あたりにあった公営ポスター掲示板が、荏原５－１－２の荏原中央公園内に移転したみたいなのですね。お願いします。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-025"},{"speaker":"大倉委員","kind":"質問・要望","question":"投票率向上というところで、以前、投票済証かなんかを新しくして、またそういうものを啓発に使っていきますというお話だったかと思うのですが、それについてホームページを見てもなかなかちょっと出てこないのですけれども、これからどういうふうに活用されていくのか、考え方があれば教えていただきたいと思うのです。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご質問の投票済証の発行ですが、ご指摘のあったいろいろなご意見だとかアイデアをいただいたことは私どもも引き継いでおりまして、この秋の区長選挙と区議会議員補欠選挙につきましては、区のオリジナルの投票済証、具体的には区の観光大使をやっていますシナモロール。","voiceIndex":65,"id":"exchange-026"},{"speaker":"大倉委員","kind":"意見","question":"そうやって新しく取組みをしながらさまざまな整備、また投票に行ってもらうというところで非常にすばらしい取組みをしていただいているなと思っています。何かあれば。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご指摘のように若い方への投票行動の呼びかけや、商店街との協力関係というのは区全体にとってもいいこととなると思いますので、まず今回秋に実施をして、投票済証の反応だったり、また課題がないかというようなところも検証した上で、今後さらに活用ができるのであれば。","voiceIndex":67,"id":"exchange-027"},{"speaker":"湯澤委員","kind":"質問","question":"今回区長選挙のほうでも、配布期間が令和４年９月２６日から１０月１日ということで、投票日の前日までに配布するということになっているかと思うのですけれども、参議院議員選挙のときにも「選挙公報はいつ来るの」という声がありまして、今、期日前投票なんかもかなり盛んに行われているので、結局、期日前に行こうかなと思っても、選挙公報が届かないと。","respondent":"鈴木選挙管理委員会事務局長","answer":"それと、品川区の場合は、全世帯に個別の全戸配布をいたします方法として、品川区シルバー人材センターにお願いしているというのがありまして、やはり区としても支援している団体ですのでお願いをしているという経緯はあるのですが、二。","voiceIndex":69,"id":"exchange-028"},{"speaker":"大倉委員","kind":"質問","question":"例えばある程度確定したデータができた場合にＬＩＮＥで、それこそシナモロールと併せて、今度の選挙についてはこういう方たちがこういう主張をされていますみたいな発信などというのはルール上できないのか、理屈上できないのか、既にやっているのか、よくわからないのですけれども、多分ホームページとかに出されたりもするのでしょうし、そういった活用というのはできないのですか。","respondent":"鈴木選挙管理委員会事務局長","answer":"選挙公報につきましては、法の規定によって作成・配布するのが定められているので、一般的な ＳＮＳなどをどこまで活用できるかというのは、ちょっと確認をさせていただきたいと思います。ただ、現時点ではまだそこは活用していないという手法になります。","voiceIndex":71,"id":"exchange-029"}]},{"id":"topic-03","title":"八潮中央保育園大規模改修機械設備工事請負契約","agenda":"八潮中央保育園大規模改修機械設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"１点だけなのですが、契約金額が１億３,０９０万円ですよね。これに対して大洋テクニカと中央工設が入札されたということなのですが、ＪＶ２社で組む必要があるのですか。金額もそうなのですが、工事内容はそんなに大きくないのに、何か理由があるのでしょうか。","respondent":"東野経理課長","answer":"設備関係の工事請負契約につきましては、１億３,０００万円以上のものにつきましてはＪＶ工事ということで規定をしています。","voiceIndex":79,"id":"exchange-030"}]},{"id":"topic-04","title":"台場小学校空調設備改修工事請負契約","agenda":"台場小学校空調設備改修工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"工事内容なのですけれども、屋上に設置されている冷温水発生器というのはどういう機能というか、どういうものなのか、教えてください。ごめんなさい、基本的な知識がないので、この設備がどういう目的で設置されていて、このたび多少不具合が出たとか、更新時期が来たとか、そういうことだと思うのですけれども、その辺についても教えてください。","respondent":"小林施設整備課長","answer":"大体この機械自体が耐用年数というのが定められておりまして、およそ１５年ぐらいです。この施設につきましては、１８年程度既に経過していますので、機器の状況とか数字が結構悪くなっているということで今回改修工事を行うです。","voiceIndex":85,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"基本的に、これは小学校の屋上とかにはみんな設置されているものなのでしょうか。それとも、特別にこの学校にそういうことが必要で、そういうふうに設置されているのか。すみません、学校の現状に全然詳しくないので教えていただければと思います。","respondent":"小林施設整備課長","answer":"全ての学校がどうかというところまでは把握できておりませんが、通常大きな施設で、１か所の場所で、要は冷たい空気とか温かい空気を作る場合については、こういったような大きな機械、冷温水発生器みたいな大きな機械を使ってまとめて作り出すということは一般的です。","voiceIndex":87,"id":"exchange-032"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今お話を聞きまして、私としては安心しました。ただ、１点だけ、これは一緒なのですかね。尼崎市はまず大きな会社に情報、そういう管理ですか、整理とか何かを協力会社としてまずそこに一括してお願いする。情報の整理ですね。それをさらに外部に、ほかの会社に、その協力会社の別の会社に委託するということはありなのですか。それも一切なしということですか。それだけ。","respondent":"宮澤情報推進課長","answer":"委託業務の再委託の考え方です。基本的には禁止しておりますが、やむを得ない場合と許可がある場合は許可を与えているです。","voiceIndex":101,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問・要望","question":"皆さん、それが一番心配しているところなのです。どこでどう漏れるか。区としては厳格な規則を作って運営されていると思いますが、やはり人はそこで必ず介在していますから、その辺、さらなる厳重なチェックができるように、くれぐれも細心の注意を払っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"そういうお答えですよね。そこをどうするのですかという話になるのですね。特にデータの解析とかデータの整理とかといったら、庁舎の中で全部やるのですかという話ですよ。ただ、先ほどの指紋認証とかがあるので、誰でも開けられるというわけではないということを考えれば、ある程度対応はあるのかなと思うのですが、今後そういう業務というのはいっぱい増えると思うのですけれども、どう考えられるのですか。","respondent":"宮澤情報推進課長","answer":"そういった形で個人情報の外部持ち出しというのは、業務上必要な範囲というところで適切に管理しながら対応しています。","voiceIndex":104,"id":"exchange-035"},{"speaker":"西本委員","kind":"意見","question":"そういう決まり事をきちんとしていなかった、しかも飲みに行ってしまったなどというのはとんでもない話であって、そういうことは徹底して周知をすれば、そういう状況にならなかったというか、そちらのほうが今回は大きかったのかなと思うのですけれども、それも含めて対応していただきますよう、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2238#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":34714,"voices":108}},{"id":"r04-20220629-14","meetingId":"r04-cm06","date":"2022年6月29日","dateIso":"2022-06-29","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、私たちは超高層ありきではなく、低層、中高層で検討すべきだという意見をずっと申し上げていますけれども、今回のこの計画ですと、低層部分というのは、ニュースだったりこの間の第８回の資料の中の１２ページだったかのところに書かれているこういう図で、低層階というのは何階までを低層階ということで示されているのか、その点についても伺いたいのと。","respondent":"大友新庁舎建設担当課長","answer":"こちらですけれども、フロアとしては３階に取りつく予定になるかと想定しております。まだ設計しておりませんので、１階のフロア高によって変わってくるかと思いますが、想定上では３階になるかと想定しております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この２,５００m2に対して、今の平米数がどれくらいかというのを教えてください。それで、低層が六、七階から１０階ぐらいだと。そうすると、中層階と高層階とあと地下ということで、４層に分かれているのですが、中層階と高層階というのはそれぞれ何階ぐらいになるのか、何階ぐらいを中層階、高層階と考えられているのか、その点についても伺います。","respondent":"大友新庁舎建設担当課長","answer":"ご質問の第２点目の、低層階、中層階、高層階というところの分けですけれども、誠に申し訳ありません、ご指摘をいただいた資料をもってご説明すると、第８回の資料で提示をしていますゾーニングの方針で、使い方をある程度書かせていただいております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それからあと、区民協働交流スペースというのが歩行者デッキの下のところに書かれているのですけれども、これはそうすると３階以下、１階、２階のところの部分が区民協働交流スペースというふうになるのでしょうか。それで、そういう部分というのは区民サービスに使うほうが、区民サービスにつながっていくかなという思いがあるのですけれども、この区民共働交流スペースというのはどういう中身なのか。","respondent":"山下新庁舎整備課長","answer":"災害発生時等々におきましては、そういった場所を罹災証明書の発行でしたり、災害時について比較的自由に使えるスペースとしてしつらえられたらという考え方が基本にございまして、このようなお示しをしています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いろいろ私も第８回の策定委員会の、議事録が既にホームページに上がっていましたので、これは読ませていただいて、かなりたくさんの委員の皆さんがいろいろ様々な意見を言われていて、それに区がどう答えられているのかというのも見させていただいたのですけれども、その中で、改めてそれを踏まえて申し上げたいと思ったのが、この１番の区民サービスのところで、ここには窓口機能の配置ということで。","respondent":"山下新庁舎整備課長","answer":"実際来庁される頻度ですとか、そういった割合を考えますと、一番入ったすぐのところにあるのが利便性としては高いかなというところは一定ありますけれども、高齢者福祉、障害者福祉の部門といったところでは、来庁される方のご容体といいますか。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その点について伺いたいと思います。いろいろなところで障害者の方の配慮がやはり必要だと思うのですけれども、その配慮が具体化される形で、ぜひその障害者の方々から、庁舎の設計に当たって意見を聞く仕組みを作っていただきたいと思うのですけれども、その点についても伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ところが今の発言は、聞いていると、よく見ても基本設計、それから実施設計まで入り込んでいる部分の発言がほとんどで、安藤委員がその発言をしたのはいいけれども、それは今、基本計画策定委員会でやっていても、それは区民の方もいらっしゃったりいろいろな方がいるけれども、ここは行財政改革特別委員会で、議員がしっかりそのルールは守ってやろうよという中でこの特別委員会もできているわけだから。","respondent":"若林委員長、山下新庁舎整備課長","answer":"そういう原則のもとで本委員会が行われているということで、改めて認識をさせていただいて、鈴木ひろ子委員の質疑については、確かに設計のほうに入ってきている部分もある。別紙１にお示ししております相談ブースのところですけれども、見た目には相談されている方々が映るようなイラストをしつらえとしておりまして、このようなイメージになっておりますけれども。","voiceIndex":17,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"提案","question":"私からは３つ、確認を含めてお伺いをしたいと思います。その前に、共産党の鈴木ひろ子委員から様々、非常に新庁舎に対しての前向きなご発言があったことについては、非常に歓迎をしたいと思いますし、ぜひ新庁舎、すばらしい庁舎ができるようにというところで、様々なご提案とかご意見、どんどん述べていっていただきたいと思っています。この３点をお伺いしたいと思います。","respondent":"山下新庁舎整備課長","answer":"３点目のＪＲのレンガの倉庫ですけれども、新庁舎整備に関わるところに近いのですが、実際各所管のほうでその対応をやられているとは聞いておりまして、進捗の事細かなところまでは承知しておりませんけれども、対応は進んでいるものと捉えております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"例えば品川区として、まだ新庁舎ができるのは先ですけれども、このワンストップサービス、今表にはこの２種類がお示しされていますけれども、他の人口規模が同等な自治体ですとか、事務取扱とか、何か研究とかをされていて、イメージとしてもうこれはいい、こちらがいいみたいなのが、ある程度あるのかどうなのかというのをちょっと１つお伺いしたいところだったのですけれども。それと、やはり転入・転出。","respondent":"山下新庁舎整備課長","answer":"まだどちらのほうが優位かというところまで結論は出ていないところですけれども、例えば職員ローテーション型のワンストップにおきましては、特定の処理が重なった時に。","voiceIndex":22,"id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"課長さんのお口からも出てきたそのスーパーマン方式というのは小さい自治体だったらいいかもしれないですけれど、これだけの規模の自治体で、それはスーパーマンをしこたま用意しておかないと回らなくなりますので、難しいのかなというのもあるのですが、先ほど申し上げたそのお悔やみの部分と。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"ご説明があったかもしれないですけれど、ちょっと聞き漏らしていたらすみません。裏面の新庁舎の規模のところで、現庁舎規模から線が出ていて、赤い点線と青い点線があるのですけれども、この赤と青というのは何か意味の違いというのは特にあるのですか。そこについて、最初に教えてください。","respondent":"大友新庁舎建設担当課長","answer":"赤の線と青の線の違いについてですけれども、こちらのほうは第８回の時に少し変更をした部分が赤になっておりまして、変更がないところが青のままという形で色分けをしてお示しをしているような状況になります。","voiceIndex":25,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"どれぐらいの使用率というか、駐車場が今よりは広がるのでどうなのかなという感じはあるのですけれども、結構最近駐車場もいろいろ入れない時があったりするので、現駐車場でいっぱいになっているというのがあったりするので、もしかしたら第２駐車場をうまく活用するということも検討していただく必要があるのかなということも思いますので、これは意見として述べさせていただきたいと思います。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"入るという内諾の協定締結に向けまして、今動いているという状況です。先ほどほかの委員からもございましたけれど、まだそのワンフロア当たりの平米数といったところも、設計ではないところから決まっていないこともございまして、かちっとその数字を決めてしまうと。","voiceIndex":29,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。今ある国や都の機関は基本的に継続というか、新庁舎にそのままということがありましたので、そこは区民サービスの維持という意味では大変に安心をいたしました。スペース等は拡充になるので、どこがどれだけ広がるかというのは、いろいろな方々のご意見というか思いもあるでしょうから、なかなか落としどころはいろいろだと思いますけれども、引き続きよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"前回の調査事項概要の説明の時だったと思うのですけれど、このスケジュールで、７月に第９回が行われて、８月にパブリックコメントということになると思うのですが、このパブリックコメントの前に説明会をぜひやっていきたいということでのご答弁をいただいたと思うのですけれども、それはいつ頃、どのような形で説明会をされていくのか伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"基本計画素案が固まりますのが、そういった意味では７月１９日以降というところになりますので、そちらをもって説明をする場というのは設けていきたいというところで、今、種々調整に当たっているところです。","voiceIndex":33,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８月のパブリックコメントの前に説明会が行われるということでよいのですよね。できれば何回かやっていただきたい。その日ということだと都合が悪くて来られないという方もいらっしゃるのではないかなと思うので、区民にとっての、区民の財産の庁舎を造るわけなので、ぜひそういう形では区民に示す形で、ご意見もいただけるということでの説明会をしていただきたいと思うのですが、いかがでしょうか。","respondent":"山下新庁舎整備課長","answer":"そこで、パブリックコメントを実施している最中、できれば複数回の開催をということで今種々調整に臨んでおりまして、新型コロナウイルス感染症でしたり、その他いろいろな諸事情、諸状況があるかと思うのですけれども、やはり今回満を持してといいますか。","voiceIndex":35,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"説明会を各地域、複数回ということでしていただくというのは本当によかったと思っているのですが、ぜひパブリックコメントに反映できる形で、パブリックコメントが行われる前に説明会をやっていただきたいということで、これはちょっと要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何点か教えてください。資料の５番の新庁舎の規模の赤枠の考え方を教えていただきたいと思っています。この保健センター管轄区域を再編成して、この一部機能２,０００m2をというのは、これまで我々議会としても、コロナがあったりしてそういう対応ができるような形で強化をしたほうがいいのではないですかという判断をしていただいたのだと考えています。これで文書・物品の削減量を５０％にしていこう。","respondent":"大友新庁舎建設担当課長","answer":"各委員会などで必要な機能を盛り込んでいった合計になっておりますが、今後ご指摘のとおり、まだ必要な機能が追加されることがあったり、新庁舎のオフィスでもっと文書を削減できるのではないかとかいうことで、今は５割となっているのですけれども。","voiceIndex":38,"id":"exchange-016"},{"speaker":"西村委員","kind":"意見","question":"これに関しては、子育ての部分ではワンストップサービスで、今回は細かく具体的な話はありませんけれども、どこに何を相談していいか分からないというのが、特に子育て分野かなと思いますので、例えば子育てナビゲーターみたいな詳しい方がいらして、お願いしたいなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-017"},{"speaker":"西村委員","kind":"意見","question":"もう１点だけ、相談機能の充実のところです。本庁舎以外の行政拠点とテレビ電話などで相談できる設備の導入の部分で、すみません、以前もご説明があったら申し訳ないのですが、例えばどのような支援が考えられるのかお聞かせください。","respondent":"山下新庁舎整備課長","answer":"いわゆる子育てにおけるワンストップサービスといったところにつきましては、所管のほうでもいろいろ検討を進めているところだと思います。","voiceIndex":41,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6132#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":23933,"voices":49}},{"id":"r04-20220630-19","meetingId":"r04-cm06","date":"2022年6月30日","dateIso":"2022-06-30","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ０時３２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"最終目標が、２０５０年二酸化炭素排出実質ゼロということです。このＡ３、１枚目の資料の裏側にある環境活動推進会議の意見というところを見ましても、環境問題の中でも地球温暖化対策、カーボンニュートラルというのが重視されているのだと思いました。この２点の転換が必要だということに関して、区はこの認識をお持ちなのか、あるいはどのようにお考えなのか、その点を伺いたいと思います。","respondent":"河内環境課長","answer":"そういった意味で、こういった認識を改めていくには、区民の取組からというところで、そういった啓発をしっかりやっていきたいという考えで進めたいと思っているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"今おっしゃったところは、国のエネルギー政策の転換には触れないということなのでしょうか。触れなくても、区はその必要性はないという認識でいるということなのでしょうか。","respondent":"河内環境課長","answer":"エネルギー政策につきましては、国で考えていただくことという認識もありますが、商用電源でございまして、それは買ったばかりでは区民の方は選択できない状況ですが、選択できるのは、脱炭素電力を契約されるだとか、あるいは自分のところで創エネや省エネをされるとか。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"最終目標をこのように掲げる以上、そして、２０５０年にこの最終目標を達成するためには、２０３０年までに何らかの目標を立てて取り組まないといけないというふうに、中間見直し、考えられていて、それで目標を立てようとされていると思うのですが、その際に、この最終目標に向けて、やはり国のエネルギー政策、幾ら商用電源の話であっても。","respondent":"河内環境課長","answer":"原発の問題につきましては、なかなか困難な問題と認識しておりまして、私どもが考えるにはなかなか難しいので、国の政策に委ねるしかないかと思っているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"確かにいろいろな手段があるのです。それは認識しているのですけれども、一般に、原発の問題と、それから石炭火力発電の問題は、カーボンニュートラルを論じられるときに、必ず避けて通れない問題として、この２つの問題に対してどういう態度を取るかというのは、必ず論じられるではないですか。これには触れざるを得ないのではないでしょうか。","respondent":"河内環境課長","answer":"そういったところは、エネルギー政策も踏まえまして国が判断いただくことということで、私どもの計画の中では、脱炭素に向けた取組を強化するという方向性で考えたいです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"私としては、この最終目標をこのようにきちんと掲げる以上、またそれに向けての２０３０年の中間目標を掲げる以上、それに対して責任を持って区民の方々に呼びかけ、また、品川区としても、アクションを起こす以上、石炭火力発電から撤退する、それから、原発からは即時撤退するということを国に対して申し入れる。もう一度、この点について、区の考え方を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"環境に有害物質が流出してしまわないように、その取組としてＰＲＴＲ制度を利用して、事業者の方たちも頑張られている中で、区として一番問題なのは家庭からの排出がとても多いこと、区民への周知がとても重要だということを含めて、昨年の第２回定例会でうちの吉田議員が一般質問をしているのですけれども、計画の中でどのように有害物質の部分を具体的に示していただくのかというところと。","respondent":"河内環境課長","answer":"そちらにつきましては、基本目標４「すこやかで快適な暮らし」を実現するというところで検討を進めてまいりたいと考えています。エコルとごしの常設展示におきましても、例えば、洗剤の希釈率などの提示で皆さんにご覧いただいているところもあります。","voiceIndex":18,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひこの中間見直しの計画の中できちんと位置づけていただいて、そして、きちんと示してほしいということを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"やはり基本計画の策定に当たって、気候危機の克服、また、気候危機克服への危機感、これを前提として、共通の問題意識としてしっかり位置づけることが何よりも今大事になってくると思いますが、その点、お考えを伺いたいと思います。","respondent":"河内環境課長","answer":"脱炭素、温暖化についてのアプローチですが、先ほど申しました、地域脱炭素ロードマップにもありますが、２０２０年から２０２５年までの５年間を集中期間としておりまして、政策を総動員しながら、２０３０年に全国で多くの脱炭素ドミノを起こすことができるようにということで。","voiceIndex":22,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは現状の区の取組ではなくて、品川区環境基本計画の策定に当たって、気候危機の克服、また、この危機感、これを共通の認識として計画にしっかりと位置づけるべきだと伺いました。改めて伺いたいと思います。","respondent":"河内環境課長","answer":"共通の認識として、区民一人ひとりの行動などに結びついた施策などにつきまして、細かくそこら辺は例示していきたいと考えているところです。","voiceIndex":24,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"計画策定に当たっての気候危機の克服、この危機感を位置づけていただきたいと思います。率直に言って、その原因は何か、区の考えを伺いたいと思うのですけれども、私はこの間、政府が怠ってきた省エネルギー化、さらには自然再生エネルギーへの取組、この不備、失策、無策が電力逼迫の一番の原因だと思うのですけれども、区のお考えを伺いたいと思います。","respondent":"河内環境課長","answer":"同じ５０ヘルツ帯の中で融通できるような回線の整備とか、これからそういったものを整備することによりまして、再生エネルギーが広範に普及した際にも、そういったトラブルにならないようなものが進んでいるという認識です。","voiceIndex":26,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、先ほど国に対して火力発電所の廃止、原発ゼロを働きかける考えはないと、区の答弁がありましたけれども、やはりこれは品川区の環境基本計画の中にも、石炭火力発電所の廃止を国に求めていく、また、福島原発事故でも明らかなように、環境への影響が多大な取り返しのつかない事態を招く、原発ゼロを国に働きかけていく、そうした区の取組も環境基本計画に盛り込むべきだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません。先ほどのＰＲＴＲデータのところなのですけれども、品川区のホームページの環境のところでは、環境省が公表している「ＰＲＴＲデータを読み解くための市民ガイドブック化学物質による環境リスクを減らすために」というものがリンクづけがされていないので、ぜひ区民の方に知っていただくためにも、環境のところにリンクをつけていただきたいということを要望したいのですが、いかがでしょうか。","respondent":"河内環境課長","answer":"はこちらのスケジュールにつきましては、骨子案の作成スケジュールでございまして、区民の方のご意見といたしましては、ハイアマチュアとアマチュアの中間にあります環境活動推進会議のメンバーと、それから、無作為抽出で行いました１,５００名の区民の方。","voiceIndex":30,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"スケジュールのところです。パブリックコメント募集が今後されるということなのですけれども、それは具体的にいつ頃なのかというところと、そのパブリックコメントの実施の前に区民に対しての説明だったりとか、そういう機会をぜひ取っていただきたいと思うのですけれども、いかがでしょうか。","respondent":"河内環境課長","answer":"パブリックコメントの時期につきましては、１月を予定しております。そのアナウンスにつきましては、こういった項目でこういった見直しをしているというようなものを皆さんに公表した上で、パブリックコメントを行いたいということで、現在準備を進めているところです。","voiceIndex":32,"id":"exchange-013"},{"speaker":"たけうち委員","kind":"質問","question":"表２のところで、アンケート、区民の方ですと１,５００名で５１５名から回答があったということで、事業者等についても半分以下ということなのですけれども、その辺の返信率というか、それについてはどのような、大体それくらいなのかということなのか、もう少し欲しかったということなのか、どのような感想をお持ちなのか教えてください。","respondent":"河内環境課長","answer":"まだ最終的な数値ではございませんで、遅れて出される方もいらっしゃると思いますので、区民の方はまあまあかと考えていますが、事業者の方はなかなか進んでいない状況もございまして、今後またランダムに電話などを入れながら。","voiceIndex":35,"id":"exchange-014"},{"speaker":"たけうち委員","kind":"質問・要望","question":"下線で引いていないのは、区のほうでこの項目の中で重要だということで入れたということでいいのかということと、それから、区民のアンケートについては、おおむね大体３割ぐらいなのでという部分でいくとまあまあということですが、正直、今、環境の問題が非常に多く話題にされる中では、私、個人的な意見では、もう少し返信があったのかななどという気がしたので。","respondent":"河内環境課長","answer":"返信率の話ですが、委員と同じような思いを私も思っておりまして、もう少しいくかと思っておりましたが、なかなかそれは難しい点もございまして、ただ、数ではないという点で、質でいろいろ頑張っていきたいと考えていますので、またご指導をよろしくお願いいたします。","voiceIndex":37,"id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"これが全部コストオンされて商品の価格とかになっていたりするのですけれども、行政の場合はなかなかそういった立て方はあまりしないので、アウトカムでどう見ていくかというところまでやるのが限界なのかと思ったりするのですが、ただ、環境というのは、私たちの日常生活に非常に関わりがあるというところで、５月１日にオープンした環境学習交流施設をきちんと活用していったり。","respondent":"河内環境課長","answer":"電力逼迫だとか猛暑だとか、いろいろな要因が今重なっておりますが、その中で、こういったことをやり続けないと今後もこういったことはよくならないという大きなものではなくて、そこを対応するためには、こういった行動が大事ではないかという点で。","voiceIndex":40,"id":"exchange-016"},{"speaker":"つる委員","kind":"提案","question":"そこは対策の部分になってしまうのでしょうけれども、私たちがやることでこれだけ変化したという数値目標の見える化というのを、これまでもやっていただいているとは思うのですけれども、ただ、こういう計画にないことは、逆に言うと行政のジレンマでできないとなってしまうので、やはり区民全体で、また行政、地域、事業者も一体となってという。","respondent":"河内環境課長","answer":"今後、そういった方が社会の中心になったときに、新たな脱炭素というところで、先ほどの気候変動に対しての一つの答えを出せると思っていますので、そういった力をうまく活用しながら今後進めていきたいという考えです。","voiceIndex":42,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"その点で、パブリックコメントですけれども、やはり区がこういう計画をつくろうと思っているという説明を行って、皆さんのご意見をお寄せいただきたいという姿勢が、より多くの区民の声を集めることにもつながってくると思うので、ぜひパブリックコメントを実施する際には、説明会を各地域で実施していただきたいと思いますが、いかがでしょうかというのが１つです。議事録を作成し公開していただきたい。","respondent":"河内環境課長","answer":"一方で、議事録でありますとか、そういったところを皆様に公開することによって、環境意識の啓発につながればということで、そういったことは会議体の座長などと一緒に検討を進めていきたいと考えております。","voiceIndex":44,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"環境活動推進会議ですけれども、座長と相談してということですが、やはり計画策定の経過が見えてくると参加もしやすいし、こういう視点もあったのかと、人の意見を聞くことで自分の意見を考えたりする機会にもなるかと思いますので、傍聴や議事録の作成や公開をしっかり位置づけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"それについてどう思われるか。それはどんどん進めているわけですから、それに対して今度、電力が足りないから皆さん絞ってくださいというのも、何を言っているのか、ちぐはぐな気がします。だから国も脱炭素云々と言っているなら、そういうところも国全体として考えなければ、なかなかこういう環境対策というのもまとめていくのが難しいと思うのですが、その辺についてご見解だけお聞かせください。","respondent":"河内環境課長","answer":"その真価を確かめることが今後の環境では大事だという用語なのですが、そういうところの検討も含めましてしっかりやっていきながら、選択はいろいろあると思うのですけれども、しっかり区民の方に情報発信をしていって。","voiceIndex":48,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"もう１点聞いたのですが、要は、急速に進める。そうすると、生活に影響を及ぼす。目標を決めるのはいいのですが、科学技術が追いつかない中で、目標ありきでやったとして、後で達成されませんというのもいかがなものかと思うのですが、その辺についてどう思われるか。だけど、それは区民生活に大きな影響を及ぼしてしまうのではないかという心配があるのですが、その辺についてご見解だけお願いします。","respondent":"河内環境課長","answer":"目標達成に向けてというところで、確かに急速に環境も変化してまいりまして、電力逼迫という点で、いろいろな条件も重なった上での結果だと思われますが、そういったところのないように、例えば、先ほど申し上げていない部分で言いますと、アンモニア発電でありますとか。","voiceIndex":50,"id":"exchange-021"},{"speaker":"のだて副委員長","kind":"質問","question":"やはりそれだけ地球温暖化対策をしっかりやっていかなければいけないと思いますけれども、２０５０年ゼロカーボン、脱炭素に向けて、２０３０年の排出目標として、中間見直しの計画の中にも、２０１０年比で少なくとも５０％以上削減をするということを位置づけるべきだと思うのですけれども、いかがでしょうか。","respondent":"河内環境課長","answer":"そういったところで足並みをそろえていくことも一つかというところで、現在検討を進めているです。それから、２点目の部門ごとの目標です。全体目標に向けて、部門ごとにこのようなことができるという点は進めたいということで、今検討を進めているところです。","voiceIndex":53,"id":"exchange-022"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"試算である程度分かるというお話だったので、それはやはりしっかりと区が取り組んだものがどれだけ効果があって、どういった手を打っていかなければいけないかというところを把握して進めていっていただきたいと思います。それと、これは最後に意見として述べておきたいと思いますが、２０３０年の削減目標を、ぜひ５０％以上削減というのを計画に位置づけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-023"},{"speaker":"松澤委員","kind":"質問","question":"環境の言葉というのですかね。例えば、サーキュラーエコノミーというのも、循環型経済ですよね。だからこそ、難しい言葉はあると思うのですけども、それをいかに分かりやすく砕いて教えていくということはとても大切かと思いますので、そこら辺いかがでしょうか。","respondent":"河内環境課長","answer":"そういったところは丁寧に分かりやすく用語解説などもするのですが、言い回しがもう少しないかとか、そういったことも検討しながら、誰にでも分かりやすい表現を心がけたいと考えているところです。ご指摘ありがとうございました。","voiceIndex":59,"id":"exchange-024"}]},{"id":"topic-02","title":"東京都による新たな被害想定の公表","agenda":"東京都による新たな被害想定の公表","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"人的被害は、死者数が２８８人、そのうち火災が１６０人というところで、恐らく木造密集地域が中心になってくるのではないかと思いますが、そちら、教えてください。","respondent":"平原防災課長","answer":"建物の耐震化が進んで、全体的には軽減傾向が出ているのですけれども、やはり木造密集地域を中心とした被害が想定されているところです。そういったところが今回想定でも表れているものと考えているところです。","voiceIndex":67,"id":"exchange-025"},{"speaker":"小芝委員","kind":"質問・要望","question":"今、どこのエリアでも毎年防災訓練を行っているわけですけれども、やはりこういった被害想定の特徴というのを、ぜひ区民の方にも周知していただきたいということ、より一層、危険度の高いエリアでの、地域そして行政との絆といいますか、連携を取った訓練の練度をぜひ高めていただくようお願いしたいと思いますが、その辺り、教えてください。","respondent":"平原防災課長","answer":"そういった中で、まだ具体的には東京都から全体的な背景のデータとかが出てきているわけではございませんので、分析はこれからということにはなりますけれども、どういった施策が必要なのか、これまでと何が変わってくるのか、あるいは何を引き続きやるのか。","voiceIndex":69,"id":"exchange-026"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。今回の品川区の被害想定の見直しも、タブレットを活用したご説明をしっかり進めていただきたいと考えていますが、現状のこのタブレットの活用の仕方であったり、今後、タブレットの活用においてどのような想定がされているのかというところを教えていただきたいと思います。","respondent":"平原防災課長","answer":"かなり進んでいるところにつきましては、防災タブレットを使って、防災訓練の実施から、実際に何かが起こったときの状況の集約、そういったところまで活用されているような地域もございましたり、あるいはなかなか使い方が難しいので。","voiceIndex":72,"id":"exchange-027"},{"speaker":"新妻委員","kind":"質問・要望","question":"私も地域の中で活用している事例を伺うと、地域の防災区民組織のリーダーが防災タブレットの講習会を開いているということで、なかなか使いこなせない世代の方も、地域でやっていただいている、そういう講習会で触っていく中で使いこなせるようになったということも聞いておりますので、ぜひ大事な予算をつけ対応していただいているこの機材についての活用を、併せて進めていただきたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-028"},{"speaker":"おくの委員","kind":"質問","question":"被害想定の見直しを受けた区の取組ということが最後に書いてありますけれども、区の取組としても、そういう対応をどのぐらい考えていらっしゃるのか、あるいは考えようとしていらっしゃるのか、その辺りのことを全般的にお伺いしたいと思います。","respondent":"平原防災課長","answer":"続きまして、それを区の施策にですけれども、従来から区のほうでもマンション防災を進めてきたところですが、品川区内の地域の構造を改めて分析して、例えば、木造密集地域、木造住宅が中心となるようなエリアもございましたり。","voiceIndex":76,"id":"exchange-029"},{"speaker":"おくの委員","kind":"質問・要望","question":"本当に対応のところで、マンションもいろいろ、タワーマンションと従来型のマンションというのが典型的にタイプが違うと思うのですけれども、タイプ別にどういう対応が考えられるのか、それから、マンションに対してどのように区として働きかけていったらいいのかということを、これまでにもやられているというのを少しは私も承知しておりますけれども、これから計画をさらに進めていかれる中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"新しい被害想定ということで、説明がありました。品川区の被害想定の特徴というところで、人的被害では死者数が火災では１６０人が最も多いと。建物倒壊は１０１人とされています。負傷者数では、揺れによる建物倒壊が３,００７人、火災が６７５人とそれぞれご説明がありましたが、この中でオフィスビルによるもの、いわゆる老朽化した雑居ビルによるものは含まれているのかいないのか、伺いたいと思います。","respondent":"平原防災課長","answer":"こちらの人的被害を出すに当たりましての例えば建物の倒壊、あるいはそういったところですけれども、建物自体のところにつきましては、先ほどの答弁と重なりますけれども、木造・非木造というところで区分けしておりますので、例えば住宅である、マンションである。","voiceIndex":80,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"構造で木造か非木造かという説明は先ほどあったのですけれども、つまりはオフィスビルも含まれているということなのか、そこを伺いたいと思います。","respondent":"平原防災課長","answer":"オフィスビルも含まれているものと考えています。","voiceIndex":82,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひオフィスビルの建て替え、なかなか相当古いと、耐震化というよりも建て替えのほうが現実的なのかと思うのですけれども、そこへの支援を検討していただきたいと思っているのですけれども、ご意見を伺いたいと思います。併せて、避難所避難者数の発生１日後が７万５,７２１人などありますけれども、この避難所避難者数の中にタワーマンション住民は含まれているのかいないのか、伺いたいと思います。","respondent":"平原防災課長、吉岡防災体制整備担当課長","answer":"今後どういった支援を行っていくかというところについては、先日、東京都とのお話合いの場で、施策についてはまだこれから検討というところもございましたので、そういう東京都の動きを見ながら、区のほうでも考えていきたいと思います。帰宅困難者についてなのですけれども、こちら、学校や職場等に戻ることができない、あるいは行楽、観光等により行く当てのない人、移動中の人、こういった定義がされておりますので。","voiceIndex":84,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"避難所避難者数には直接的にはタワーマンションは入っていないけれども、タワーマンションに限らず、マンション住民も想定されているということでありましたが、ご承知のとおり、品川区民の多くがマンションに住んでいるわけでありまして、建物に直接被害がなくても、とりわけタワーマンションなどの高層マンションの上層部では在宅避難が困難になることが想定されておりますし、特に直下型地震となりますと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-034"},{"speaker":"たけうち委員","kind":"質問","question":"木密地域の不燃化プロジェクトとか、またいろいろな、耐震はあれなのか。そうすると、これに基づいて何か指定地域が減らされるとか、また、補助金が削減されるとか、何かそんなことがあってはいけないと思うのですけれども、そもそも都が地域計画をつくるに当たって、区とかの意見を反映できるような場があるのかどうか、その辺を教えてください。","respondent":"平原防災課長","answer":"今後の東京都の地域防災計画の見直しに当たりましては、私ども品川区をはじめまして、各区から意見聴取の場、あるいは進行状況の丁寧な提示、そういったところを強く求めておりまして、東京都もそこに理解を示して、きちんと説明するということでお話を得ておりますので。","voiceIndex":91,"id":"exchange-035"},{"speaker":"たけうち委員","kind":"質問・要望","question":"されてしまうという言い方はいけないのだけれども、そこも大事なのだけれども、品川区は数としては減っているけれども、これはあくまで一つのデータなので、着実に東京都でもしっかり計画を立てていただかないと、品川区の計画も当然それに連動させていく形にある程度なると思うので、数字が減ったから対策が今までよりも鈍ってしまったとか。","respondent":"平原防災課長","answer":"そういったところで、減ったというよりは、まだまだ２３区内でもかなりの被害を出すですので、そういったところにしっかり対処できるような施策が取れるよう、東京都ともしっかりと話し合ってまいりたいと考えています。","voiceIndex":93,"id":"exchange-036"},{"speaker":"松澤委員","kind":"提案","question":"そういう方と連動するとか、１個あるタブレットだからどうするかは分からないのですけれども、それを要は町会内でうまく連携ができない部分は、これは地域活動課なのか防災課なのかは分からないのですが、そういったところには行政として指示というか提案というか、そういうのはしっかりとしていかなければいけないのではないかと思いますので、そこら辺を１個教えてほしいのと、あと。","respondent":"平原防災課長","answer":"一方で、品川区におきましても、ブロック塀の調査、それに基づきます支援策を進めておりますので、今回出てきた結果、それを既存の施策と相まって、改めてそういったところの推進というものも関係課と連携しながら進めてまいりたいと考えています。","voiceIndex":96,"id":"exchange-037"},{"speaker":"松澤委員","kind":"質問","question":"ある程度これは私も学びまして、そういうことなのだと思ったときに、お話があった、品川区だけではないですけれども、例えば品川区の事業所に、どれくらい７２時間帰らない、要は、中小企業の会社の中で従業員を守ってくださいという、その周知が進んでいるか、理解が広がっているか、そういうのが分かるようなデータは取っているのでしょうか。","respondent":"吉岡防災体制整備担当課長","answer":"こういったコロナ禍で、事業者間等の周知、進んでいない部分もあります。今、帰宅困難者対策協議会、こういったものもありますので、こういったものを皮切りに、中小企業等も含めて周知が進むように、充実していきたいと考えています。","voiceIndex":101,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどありました震央や断層などの部分なのですけれども、ごめんなさい、これも調べていないのですけれども、今現在ある品川区地域防災計画で、この震央について、２０１３年に国が示していたことは先ほど確認したのですけれども、区の地域防災計画の中でお知らせがあったのか、区民への周知があったのかというところを確認したいのと、今こうやって示されているということは、今後。","respondent":"平原防災課長","answer":"今後ですけれども、先ほどご説明させていただきましたとおり、まず、１９のモデルが存在しております。","voiceIndex":104,"id":"exchange-039"},{"speaker":"田中委員","kind":"確認","question":"震源モデルの部分については、１９か所散らばっているということで、それは都全体なのか、それとも区で１９か所あるのかというところをまず確認したいのと、ただ、こうやって示されているのであれば、情報があるのであれば、やはりそこに住む住民に知らせるというのはとても重要だと思うので、知っている情報は何でも提供すべきだと私は思うのです。","respondent":"平原防災課長","answer":"今後、これをどう広めていくかですけれども、事実は事実としてきちんと出していきたいと思います。何らそれをどうこうということはございませんので、ただ、それの持つ意味というところも併せてきちんとお伝えしていきたいと考えているところです。","voiceIndex":106,"id":"exchange-040"},{"speaker":"田中委員","kind":"確認","question":"きちんと意味等も含めてお知らせをしていきたいという前向きなご意見をいただけたので、よかったと思うのですけれども、１個だけ確認したいのですけれども、南関東で１９か所ということは分かりました。私、防災タブレットのこと、全く分からなくて、伺いたいのですけれども、そもそもこの防災タブレットは誰が持って扱うもので、どういう想定で利用するのか。発災時の利用も想定しているのか。","respondent":"平原防災課長","answer":"使い方そのものについては、地域それぞれでということで考えていただくような形で進めているところです。","voiceIndex":108,"id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"大きさとか重さとかというのもありますし。発災時にタブレットが故障しているという可能性もあるではないですか。情報収集のために必要というのは本当にそのとおりなのですけれども、壊れてしまった際には意味をなくしてしまうということからも、タブレットの必要性というか、避難所が運営されるようなほかの手段というのはきちんと確保していってほしいということを求めたいと思います。","respondent":"平原防災課長","answer":"先ほど周知という形でお伝えさせていただきましたけれども、そのために、ふだんから消火器の重要性が改めて高い建物の場合は出てくるかと思いますので、そういったときに使い方、実は全然触ったこともありませんではなくて、改めて触っていただくなどというところもありますので。","voiceIndex":110,"id":"exchange-042"},{"speaker":"つる委員","kind":"確認","question":"先ほど来ずっと確認がある震源断層というので、よく報道で聞く、活断層とかがありますよね。いろいろ見ると、都心部のそういう震源断層だとか、活断層が想定されるとか、何たら断層といろいろ名前がついているのですけれども、ここは特にそういうものではなくて、あくまでも、地下でそこが断層がずれたときに起こるであろうという想定という理解なのですか。","respondent":"平原防災課長","answer":"例えば、近くでいきますと、立川のところでは立川断層帯地震という、先ほどご説明させていただきましたとおり、そこに断層があるということが分かっておりますが、東京都区部のところについては、具体的な活断層というよりは。","voiceIndex":113,"id":"exchange-043"},{"speaker":"つる委員","kind":"質問","question":"分かりました。福岡県で大きく大通りが陥没しました。あのような想定というのは、今、熱による、これだけの状況におけるものとかも加味して、ある程度想定があるのでしょうか。スケルカとかを使って、地下の空洞の調査とかはやっていただいていると理解しているのですけれども、この辺りについて教えてください。","respondent":"稲田防災まちづくり部長","answer":"土が雨水で流れて、地下の水で流れていったりという、いろいろな原因がありまして、そういうのを防ぐために、空洞調査とかを区のほうではやっているところですけれども、地震があって、地中に空洞があれば。","voiceIndex":115,"id":"exchange-044"},{"speaker":"つる委員","kind":"質問・要望","question":"そこはこれまでもやっていただいていることも含めて、いろいろな事業者、自治体、国というところで、安全対策を取りながらというところだと思うのですけれども、そういった、例えば、前、川だったところの周りとか、浸水ハザードマップとかがあったりして、そこが下の部分が軟らかいとか、いろいろあるのでしょうけれども、いろいろなことが考えられるのかというところではまさに想定だと思うので。","respondent":"平原防災課長","answer":"ただ、一方で、基地局でも、電源が遮断されましたら非常電源に移るということもありますが、それも３日程度で完全になくなってしまいますので、仮に電力供給がストップしたような場合には、何らかの形で障害が出てくるというのが１点と、もう一つが、１０年前でしたら。","voiceIndex":117,"id":"exchange-045"},{"speaker":"つる委員","kind":"意見","question":"通信事業者の積極的な努力と、その支援ということが当然必要になってくると思うのですが、また、区として、そうした通信インフラの確保というのは、これまでもやってきていただいていると思うのですけれども、実際提供したいと思っても、インフラが遮断されていれば、それはなかなか難しいのだろうと思うので、そこも引き続きお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-046"},{"speaker":"須貝委員","kind":"質問","question":"ですが、世界有数の人口密集地、人口が増えて、建物もこれだけ急速に増えている東京で巨大災害が起きたときに、本当に死者約６,１００人の被害想定、これをそのように受け止めていいのでしょうか。それは全然耐震診断をしていないものもたくさんあって、この被害想定で区は大丈夫だと考えているのでしょうか。１０年前に比べて、これでも被害が減るという想定として考えていいのでしょうか。","respondent":"平原防災課長","answer":"恐らくこの２４件といっても、個別の火災ではなくて、かなり大きいものだと思われます。そういったところもありますので、広域避難場所への避難であるとか、火災時の対応といったところについてもきちんと周知してまいりたいと考えています。","voiceIndex":120,"id":"exchange-047"},{"speaker":"須貝委員","kind":"質問","question":"避難場所、今お話がありましたが、例えば高層マンション、あれだけの住民が住んでいて、その方たちが電気が止まったからといって、どこか避難する場所はあるのですか。ですが、１０年たって、相当変わったのではないか。人口密度がこれだけ多いということは、やはり何か考えなければいけないのではないかと思います。次回、防災に関することで再度質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-048"},{"speaker":"田中委員","kind":"質問","question":"ごめんなさい。重要なのを１つ聞き忘れていました。品川区での想定はどれほどなのかというのを伺いたいのと、あと、要配慮者の方が亡くなってしまう理由として、地域コミュニティとの交流が希薄であることなどです。それらについて区として、そうならないようにしていくための対策をどのように考えているのかという、２点、お伺いしたいと思います。","respondent":"平原防災課長","answer":"区では、こういった方々、現在、個別避難計画等々進めておりますけれども、そういう中で、逃げ遅れない、皆で助け合う、そういったところをきちんと進めて、このような方々が犠牲にならないように、あるいは、避難所に行って。","voiceIndex":124,"id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"ありがとうございました。やはり要配慮者の方自身も地域に出ることで、また、地域の方たちが要配慮者の方のことを知ることで、一緒に防災訓練等をすることが重要なのだということを思います。ですので、地域でお互いのことが知る機会というのをぜひどんどんつくっていただきたいということを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-050"},{"speaker":"のだて副委員長","kind":"質問","question":"１つ大きなところでは、今回、数値に表れないものが定性被害ということでシナリオという形で示されているわけですけれども、それについても区としても対策が必要ではないかと思うのですが、そのお考えを伺いたいのと、あと、先ほど来タワーマンションのお話もいろいろ出ておりますけれども、まずはエレベーターが止まって、高層階の人は上に上がれなくなったりとか、停電になれば。","respondent":"平原防災課長","answer":"おおむね１週間程度で復旧ですが、一方で、北海道で平成３０年に起きましたようなブラックアウトについては、電力需給のバランスの問題ですので、そういったところについては、大災害発生時の東京における電力需給が相当低下しているということが想定されておりまして。","voiceIndex":128,"id":"exchange-051"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"定性の被害のところでは、様々なシナリオが示されているということですので、やはりそこでの対策というのを想定してやっていくべきだと思いますので、よろしくお願いいたします。ほかにも在宅避難者への支援ですとか、停電時のこととかも様々ありますけれども、そうしたことをしっかり想定して対策をしていただきたいということで、意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6618#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":51655,"voices":134}},{"id":"r04-20220706-10","meetingId":"r04-cm07","date":"2022年7月6日","dateIso":"2022-07-06","committee":"議会運営委員会","time":"午前１０時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、令和４年第２回定例会","agenda":"の１、令和４年第２回定例会","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"共産党としては、契約金額の変更であっても、議案については専決処分でなく、議会を開いて議論の上、議決すべきだというのが基本的な立場です。改めて１点だけ確認させていただきたいと思います。そこで伺いたいのですけれども、実際にはどんな場合を想定しているのでしょうかということで、考えられるのは労務単価の上昇や資材高騰などだと思いますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"意見","question":"これを１００分の５だけにしたというのは、ほかのところだったら、金額とかが入っているということを多分おっしゃっているのだろうと思うのですけれども、これも過去の品川区の例を取ると、大体５％以内、なおかつ金額的なものの話をしていくと、いかに流用でやれるかという部分も必ず出てくるだろうと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-002"},{"speaker":"のだて委員","kind":"確認","question":"今回の理由としては、労務単価の上昇とか工期の延長などに対応していくためということで、何でも認めるということではないということを確認させていただきました。私たちは今回の議員提出議案に至る前提となる第１回定例会での請願については、紹介議員になることを辞退した上で、賛成をいたしました。提出者にはなりませんが、事業者負担の改善が必要ということで、議案に賛成したいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-003"}]},{"id":"topic-02","title":"議事日程(3)および追加議事日程","agenda":"議事日程(3)および追加議事日程","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"日程第２２の補正予算についてなのですが、今の局長のご報告では、建設委員会で賛成多数というお話があって、総務委員会では、品川・生活者ネットワークが反対で起立採決だったのですけれども、建設委員会で共産党ののだて委員が反対をされたと思うのですが、総務委員会では、品川・生活者ネットワークが反対ということだったので、総務委員会での共産党の態度と当日の採決における。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-004"},{"speaker":"のだて委員","kind":"意見","question":"建設委員会では、補正予算の建設委員会所管分は反対をいたしました。総合審査では、ほかの厚生委員会、文教委員会の所管業務も含めて総合的に判断をいたしまして、必要なものであるということで、賛成をいたしました。建設委員会の部分は反対であるということで、全体としては賛成だということで発言させていただいているものです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"のだて委員も当日補正予算には賛成するということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-006"},{"speaker":"のだて委員","kind":"意見","question":"私も賛成いたします。この間もあったのではないかとは思うのですが、建設委員会の部分は全体として、予算としては７００万円というところで、総額としては数億円というところでありますので、全体を考慮して、全体としては賛成だということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-007"},{"speaker":"たけうち委員","kind":"意見","question":"会派の考え方と各議員の考え方なので、そこで私がどうこう言う筋合いではないかもしれないけれども、在り方として、ちょっとおかしいのかなと指摘だけしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-008"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"当面は７月７日の明日の本会議と表彰審査会が７月１１日にあるのですが、これに関しては欠席します。私としても、接触等や、本人の対応に対して負荷をかけてしまうと、本人にとってはハラスメントに近い状況になると思いまして、このまま静観させていただき、議会日程等がありましたら、それに対して体調はどうですかという、出席できますかという問いかけだけの連絡を今しているような状況です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5472#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":10110,"voices":47}},{"id":"r04-20220725-6","meetingId":"r04-cm07","date":"2022年7月25日","dateIso":"2022-07-25","committee":"区民委員会","time":"午後 １時００分～午後 １時５１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和４年度地域振興基金を活用した区民活動助成制度の審査結果","agenda":"令和４年度地域振興基金を活用した区民活動助成制度の審査結果","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"似たような説明なのですけれども、その助成目的の中に、将来的に行政と協働で地域課題の解決に取り組むことを視野に、区が提示するテーマに取り組む事業に助成するということで、今の説明の中にもあったように、食品ロスですか、食品ロス削減に向けた取り組みと子どもの学習機会保障に向けた取り組みが募集テーマに選ばれているということなのですが、この食品ロス削減にしろ、子どもの学習機会保障にしろ。","respondent":"川島地域活動課長","answer":"この辺、そうかといって、そのテーマを地域活動課が助成してしまったら何でもできてしまうことになりますので、まずはそのそれぞれの所管課、食品ロスでしたら環境課ですとか、それから、今回の学習支援は発達の特性傾向のあるお子様ということですので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"テーマを選んだのは、委託契約の相手となれればというようなことも見据えてということなのですけれども、それとトライ助成、それは今回のテーマに関してなのですが、トライ助成制度を新たに設けた趣旨というものは何ですか。何でしょう。そこのところ、もう少し。","respondent":"川島地域活動課長","answer":"これまでは、その団体がやるというようなテーマのものを助成してきたものですけれども、今回このように設定したというのは、我々が、区民ニーズなどが非常に高いようなテーマがあるのではないかということで、今回のこの２つについては。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"ＫＤＤＩ株式会社通信障害による児童見守りシステム（まもるっち）への影響および対応","agenda":"ＫＤＤＩ株式会社通信障害による児童見守りシステム（まもるっち）への影響および対応","exchanges":[{"speaker":"おくの委員","kind":"確認","question":"確認なのですけれども、夜間・休日モードに切り替える前までは、発報があるたびに、一々保護者に電話連絡を入れていたという理解でよろしいのですよね。","respondent":"森田生活安全担当課長","answer":"そのとおりです。１件１件の発報について、その都度保護者に確認して、お子様から発報がありますけれども、ご確認願えますでしょうかということを確認しております。","voiceIndex":13,"id":"exchange-003"}]},{"id":"topic-03","title":"臨海斎場の火葬料改定","agenda":"臨海斎場の火葬料改定","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"そのような中、そして物価高騰はもう本当に連日のようにニュースで流されている状況ですから、このような火葬事業にかかる経常経費の増額分を、やはり公費を投入してそれで吸収していく、そして値上げを抑えていくということをやるべきときではないかと思うのですけれども、その点いかがでしょうか。そのようにお考えにならなかったのでしょうか。お伺いしたいと思います。","respondent":"吉野戸籍住民課長","answer":"こちらのほう、この火葬需要に対応するためには、やはり施設の整備、その辺と、あと光熱費など、そういったところも高騰してきておりますので、そういった対応をしなければなりません。ですから、区民の方には一定の受益者負担という形でお願いしたいというふうに考えております。","voiceIndex":20,"id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"死は誰にでも訪れるものですし、使おうと思えば使えるということで、使える施設ということで、困っている方が人生の一番最期の瞬間のときに、何ですか、腹を痛めなければ使えない。そのように考えていいのではないでしょうかと私は思うのですが。臨海部広域斎場組合議会ですか、そこではそのような議論、あるいはどういった議論が交わされたのでしょうか。その点もお伺いしたいと思います。いかがでしょうか。","respondent":"吉野戸籍住民課長","answer":"議会での検討は、この８月１７日、そこで決定という形になりますので、申し訳ありません。その前に一定程度打合せといいますか、こういった案ができたというものです。失礼しました。各区のそういった部長会、課長会を含めまして、そういった組織区においてこういった話し合いをしまして、案をつくっております。その案を８月１７日に諮るというような段取りになっております。","voiceIndex":22,"id":"exchange-005"},{"speaker":"おくの委員","kind":"提案","question":"ぜひ品川区のほうから、今の、私がさっき言ったような、今だからこそこのような、今回は値上げを公費で補填しようではないかというような提案をしていただきたいなと私は考えるのですけれども、いかがでしょうか。","respondent":"吉野戸籍住民課長","answer":"大変、先ほどと話がまたあれになってしまうのですけれども、一定程度、やはり火葬需要というところが増えているような現状ですので、やはり、ほかの民間の斎場と比べましてもかなり安い火葬料になっておりますし、そういったところでは、一定程度そういった。","voiceIndex":25,"id":"exchange-006"},{"speaker":"おくの委員","kind":"質問・要望","question":"そこのところをやはり考えていただきたいということと、それから、やはり今非常に特別な時期だということを考えて、品川区のほうからぜひとも提起していただきたい。今回は公費で負担しようではないかということを提起していただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"例えばここで、今回上がるのは４万４,０００円ですけれども、４万４,０００円で済むわけではないではないですか。火葬をすると。それともう１点伺うのは、これから、今もそうかもしれませんが、多死時代になるわけではないですか。そのような話が、もう一部事務組合では出ているのかなと。その辺についてはいかがでしょうか。２点お伺いします。","respondent":"吉野戸籍住民課長","answer":"実際には……、失礼しました。そういったことを見据えて、将来の火葬需要というところで見据えまして、令和１１年には臨海斎場施設の、こちらの火葬炉のほうを１０基から１６基へ増設する計画を立てているところです。","voiceIndex":29,"id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"火葬料の算定方法というところで少し詳しくお聞きしたいのですけれども、年間の火葬経費というものを年間の火葬料収入で割り返すということなのですが、年間といっても、３年ごとに定期的に見直すということですけれども、年間というのは、この３年間のどこを見ているのか、どう見ていくのか。直近の、去年の年間の経費と収入で、１.１というものをはじき出したのかということを少し詳しく教えてください。","respondent":"吉野戸籍住民課長","answer":"その理由としましては、令和元年度に消費税が前回８％から１０％に上がったということもありますので、令和２年度を見ております。平成３０年度のときも、ちょうど２年前の平成２８年度を根拠にして出しているというものになります。","voiceIndex":32,"id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。この火葬件数が令和２年度の件数で計算しているということなので、今、前の質疑にもありましたけれども、亡くなられる方というものは増えているので、件数が増えてくるということは見込めるのだと思うのです。そのような辺りの、将来的に増えてきた場合の、当初計画よりも余剰分というのか、多い収入、このようなものに対してはどのような考え方を持っているのかお聞きします。","respondent":"吉野戸籍住民課長","answer":"そうしますと、やはりメンテというところで、かなりの高温で火葬炉は使いますので、メンテの部分がやはり、あと光熱水費、こちらのほうも高くなってまいります。メンテナンスです。申し訳ありません。というところでの料金がどうしてもかさんできますので、そちらのほうに充てていくという形になります。","voiceIndex":34,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。それは事情としてはよく分かります。そのような意味では、そのメンテナンス等に係る、あるいは今後増設というお話もありましたけれども、そのような新規の投資、設備投資等にかかる経費というものは、火葬料だけでは多分賄えないと思うのですが、そういったことに対しての財政的な担保というのはどのように考えられるのか、最後にお聞きします。","respondent":"吉野戸籍住民課長","answer":"新規開設のほうなのですけれども、実は平成３０年度から基金を積み立てているところです。そこから、区のほうから負担を出している、その一定数、一定の金額を貯めて、なるべく負担はないようにいきたいと考えてはおります。今回の火葬料で負担するということではありません。","voiceIndex":37,"id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"そこの部分というのは、そういった計算はされていないのでしょうか。そうすると、もう少し値上げを抑えることというのも、経費というものはすごく圧縮できると思うのですけれども、そういった検討というものはなされなかったのでしょうか。","respondent":"吉野戸籍住民課長","answer":"３年後、やはりそのときに委託料を含めて、工事費も含めての算定になるかなと思いますので、今回令和２年度に関しましては、こうしたところも全部踏まえて計算したという次第です。","voiceIndex":40,"id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"今の計算の根拠というものが修繕費という、先ほどの修繕費の話の続きになると、修繕費と言われても、やはり火葬件数によって修繕にかかる費用というものはある程度決まってきていると思うので、そこが物すごく上がるということはちょっと考え難いなと思って、そうであるならば、増えていく件数との関係でいったら、委託料などの比率というものは下がってくるのではないかと思うのですけれども。","respondent":"吉野戸籍住民課長","answer":"その中に、一定の歳入歳出というところの式が出ておりまして、ただ、今回の料金改定なのですけれども、やはり１.５というものを上限に考えまして、なるべく抑えるようなというところになっておりますので、そういったところでの計算はしているところです。","voiceIndex":42,"id":"exchange-013"},{"speaker":"松本委員","kind":"意見","question":"施設全体の管理運営経費の６割というふうに改定率の計算のときに出てくるのですけれども、この６割というものは、どのように考えればいいのか。残りの４割の部分などというものは、扱いとしてはどのようになっているのか。","respondent":"吉野戸籍住民課長","answer":"この６割なのですけれども、あくまでも火葬の敷地面積から取っているところになります。区民の方が利用される部分というところでの算定、それが大体、敷地面積でいきますと６割という形になっておりますので、そこから６割というものが出ております。","voiceIndex":44,"id":"exchange-014"},{"speaker":"松本委員","kind":"質問","question":"今の残りの４割の部分の経費というものは、どこがどのように負担をしているのですか。","respondent":"吉野戸籍住民課長、伊崎地域振興部長","answer":"残りの４割は、申し訳ありません。お待ちください。４割に関しましては、組織の一応負担金という形で予算立てするところになりますので……。ただいまのご質問ですが、火葬料については、基本的に火葬を必要とする方に負担をいただくということで。","voiceIndex":46,"id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"ありがとうございました。火葬の部分はもう利用者負担で、残りの部分はそれぞれ、これは５区ですか、５つぐらい、たしか区で運用しているので、それぞれが分担金を払うというふうに理解いたしました。多摩地域のほうは、組織市内、組織の市内のほうだったら火葬料無料というようなやり方もあるというように伺っています。","respondent":"吉野戸籍住民課長","answer":"やはり、例えばこの火葬料自体をゼロ円にしてしまいますと、当然全ての負担が区の負担になってしまうというところになりますので、利用されている方と利用されていない方というところの公平性の担保からいきまして、やはり利用されている方から一定の金額を、ほかと。","voiceIndex":50,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問・要望","question":"分かりました。ですから、この部分は引き続き議論をしていただきたいなとは、今回反映できなくても、また次、３年後に来ますので、どうかここの部分は、これからどんどんこういった火葬の件数自体が増えるということは、もう先ほどおっしゃられたとおりなので、どのようにこの組織区内の人たちの負担を下げていけるのかというところをご検討いただければと思います。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2936#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":15383,"voices":57}},{"id":"r04-20220725-7","meetingId":"r04-cm07","date":"2022年7月25日","dateIso":"2022-07-25","committee":"厚生委員会","time":"午後 １時００分～午後 ３時１２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"あくつ副委員長","kind":"意見","question":"前例のとおり、頭撮りということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"令和４年陳情第４３号、障害等のある区民に区役所の業務をワークシェアリングしてくださいに関する陳情","agenda":"令和４年陳情第４３号、障害等のある区民に区役所の業務をワークシェアリングしてくださいに関する陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"調達実績のところですけれども、令和２年度は、２３区内では一番多い調達実績だということでした。すみません、聞き漏らしてしまったのですけれど、令和３年度の実績のところで、クリーニング以外の、最初の１６１件、これがどういう内容なのかをもう一回伺いたいです。","respondent":"松山障害者支援課長、崎村人事課長","answer":"私から、令和３年度の調達実績についてご説明いたします。令和３年度の調達実績は、件数が３２６件、調達金額は３億９５万円余です。説明が不足していて、誤解を与えたら申し訳ないのですけれども、昨年調査を行いまして、この４月から実際にもう業務を受けているところです。","voiceIndex":12,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、人事課長のご説明では、２４０件ほどの軽作業があり、約６,５００時間分ということですけれども、どれぐらいの方が今、実際に作業されているのかということを伺いたいのと、こういう作業をしている方々は、障害者の法定雇用率に入ってくるということでいいのでしょうか。国全体では昨年２.６％だったと思うのですけれど、今が幾つで、品川区はどのぐらいなのか、伺いたいと思います。","respondent":"崎村人事課長","answer":"令和４年６月１日現在の数字は、まだ速報値なのですけれども、２.３２％になってあります。ただ、いずれも法定雇用率は満たしておりませんし、引き続き障害者雇用については進めていく必要があると考えているところです。","voiceIndex":15,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"意見","question":"この陳情ではワークシェアリングという言い方をされていて、様々な障害の方がその人に合ったサポートを得ることで、生き生きと働くことができるのだということが書かれておりますけれども、本当にそうだと思うのです。それが仕事の広がりにも、区が呼びかけることでつながってくる部分もあると思いますので、ぜひそういう立場で引き続き進めていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-004"},{"speaker":"あくつ副委員長","kind":"確認","question":"少し数字の確認で、先ほど繰り返しありました令和３年度の実績は３２６件、３億円余ということでしたけれども、国の調査結果で、令和３年と聞こえたのですが、年度なのか３年なのか。３１０件で、２３区中１位の実績でしたというふうに聞こえたのですが、この数字の違いというか、年の違いがあるのか、というところを、まず確認で教えてください。","respondent":"松山障害者支援課長","answer":"国による実績につきましては令和２年度の実績で、令和２年度の国による集計値の時点が令和３年１１月９日、という調査結果でございました。","voiceIndex":18,"id":"exchange-005"},{"speaker":"あくつ副委員長","kind":"質問","question":"もしかしたら今までの本会議の一般質問や委員会質疑等で出てきた数字なのかもしれませんが、品川区がそういう調達の優先をされているというのは数字で明らかに、２３区の中でもより前向きに取り組んでいるということは、はっきりと数字として出ているということを知りました。これからのお考えについて、お伺いしたいと思います。","respondent":"崎村人事課長","answer":"業務支援室については、障害者の方だけではなくて、その障害者を支援する方としてサポートマネジャーを、介護支援専門員の資格を持っている会計年度任用職員の方ですとか、また、福祉職の再任用短時間勤務職員を配置して、その障害者の方の支援も実際に行っているところです。","voiceIndex":20,"id":"exchange-006"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"お答えいただける範囲でお答えいただいたのかなと。先ほど、重度か、それにかかわらず、というご答弁だったので、そういう方も対応してお仕事ができるのかなという理解をいたしました。やはり広く周知すべきではないかと思うのですけれど、採用の拡大のお考えとその周知の方法について、教えていただきたいと思います。","respondent":"崎村人事課長","answer":"今後についても広く周知をしていきたいと考えていますし、また、区内の就労支援施設等とも連携しながら、周知については努めていきたいと考えております。","voiceIndex":22,"id":"exchange-007"},{"speaker":"あくつ副委員長","kind":"質問","question":"最後に、以前、厚生委員会で大分県の巨大な障害者の就労支援施設を見学させていただいたとき、市役所の近くにそういう大きな施設があって、地方だということもあるのですけれど。今度、新庁舎のことも進んでいますけれども、新庁舎もいろいろな課題はあると思うのですが、新しい区役所の中でしっかり、そういった方たちが輝いて働けるような環境づくりをぜひお願いしたいと願って、私の質問は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問","question":"結論を出すで、態度は不採択でお願いします。悪い意味ではなく、ご説明があったように既にもう、この陳情の趣旨によるところの働く機会の増加等、精力的に、あるいは調達実績も踏まえた形で動いているという点から、発展的な意味で、もう踏まえられているという意味での不採択で、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-009"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"結論を出すで、不採択でお願いいたします。理由としては、今、自民党がおっしゃった内容で、ここに書いてあるワークシェアリングをしてほしいという希望は、もう実際に進んでいるですので、今回は不採択とさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"意見","question":"結論を出すで、採択でお願いします。もう既に進められているということですけれども、区としてそういう姿勢をさらに広げていくというところでも、議会として採択をして、後押しになればと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。ただ、少し形態を開拓して、短時間勤務や超短時間勤務などといった作業もあったりしますので、そういう役務もいろいろ、他自治体でも新たに開拓されているので、そういった方面も広げていっていただきたいという要望をつけ加えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"}]},{"id":"topic-03","title":"地域福祉計画改定に伴う区民アンケート調査","agenda":"地域福祉計画改定に伴う区民アンケート調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"第４期に向けてのアンケートということで、まず、調査・分析を委託されるということで、この委託費が分かれば伺いたいのと、策定委員会はもうつくられているのですか。第２期のときも、第３期のときもつくられていると思うのですけれど、それは今回はいつできるのか、もうできているのか、どういったメンバーになるのか、伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"委託費については手元に資料がないのですけれども、２つ目の策定委員会については、今日ご報告しているのは、令和５年度に改定作業を行う、そこで策定委員会等々ができるのですけれども、そのためにアンケート調査結果というものが必要になってきますので、１年前倒しで今年度。","voiceIndex":36,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"区民アンケートを行った上で、次の新たな計画に反映させていくということだと思うのですけれど、今後のスケジュールのところで、もう少し細かい流れをお聞きできたらと思うのですけれど。前回のアンケートの時、区民を対象としたアンケート以外に、専門職の方１２４人を対象にアンケートをしたと書かれていたのですけれども、今回は専門職の方へもアンケートが行われるのか、伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"それから専門職アンケートにつきましては、前回の改定の時も行いまして、今回も予定はしております。区民アンケートに遅れて前回もやっていますので、恐らく年をまたぐ辺りで、今回も予定はしております。","voiceIndex":38,"id":"exchange-014"},{"speaker":"あくつ副委員長","kind":"質問","question":"今のご説明の中で、こういうことをやるから、区民から問合せがあるから先に知らせておきますというご説明だったのですけれど、内容のことに触れてはいけないのですか。この内容について質問してもいいですか。","respondent":"寺嶋福祉計画課長","answer":"もちろん結構です。すみません。","voiceIndex":41,"id":"exchange-015"},{"speaker":"あくつ副委員長","kind":"質問","question":"そういう中で、例えばデジタルデバイド対策みたいなものは、一番最後のページの大項目の５、品川区の地域福祉の施策についてというところでは、問２８、地域で充実してほしい施策についてお答えくださいということで、今までも出てきたような課題、一般的な内容は書いてあるのですけれども、こういう地域福祉計画の中で、取り上げていくのか、いかないのか。それについて、ご意見を伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"デジタルデバイド対策については微妙なところで、全体の中でお尋ねするのがいいという考えもあろうかと思うのですけれども、各個別計画の中でもアンケート調査を今後予定しておりまして、そういったものも、この最終結果には集約して。","voiceIndex":43,"id":"exchange-016"},{"speaker":"あくつ副委員長","kind":"確認","question":"分かりました。地域福祉計画は上位計画ということで、いわゆるそういうエッセンスのことだけ伺うということで、今、確認させていただき、理解しました。これから、個別計画においてはテーマに沿った形でアンケートと区民の意見を集約するということで、ご説明がありましたので、承知しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-017"}]},{"id":"topic-04","title":"はじめてのスマホ体験教室・スマホよろず相談事業の実施","agenda":"はじめてのスマホ体験教室・スマホよろず相談事業の実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"はじめてのスマホ体験教室とよろず相談ということで、ご高齢の方はスマホ自体、もうできないとなったりしてしまうところもあるので、そういう中でも大分、多くの方が持たれ始めているとは思っているのですが。それでよろず相談のほうは、１回につき２０分から３０分ということで、シルバーセンター、ゆうゆうプラザ等でやられるにしても、窓口は１つということなのか、伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"高齢者が１０人いらっしゃって、それぞれ得意、不得意ありますので、把握できるような形で、同一講師による対応とする予定で、今、詰めているところです。","voiceIndex":50,"id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"教える方については事業委託ということで、プロポーザルでと。それで今、選定に向けて検討しているということですけれども。そうすると、携帯電話事業者になるということではないのでしょうか。フレイル予防のほうもこの委託した事業者が講義されて、スマホ体験教室もということなので、どういう業者になってくるのか、教えていただきたいと思います。","respondent":"川原高齢者地域支援課長","answer":"現在、委託契約の締結前ですので、詳細は難しいところでもあるのですけれども、現在選定している業者に関して申し上げますと、携帯電話ショップで実際に教室などをやっている事業者のほか、社会貢献というところで介護予防に対しての知識も。","voiceIndex":52,"id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"質問","question":"はじめてのスマホ体験教室のほうで、１０人以上になった場合はどうなるのかということと、８月のコース、９月のコース、１０月のコース、みたいな感じになっていくのかと想像しているのですけれど、そのことが一つです。それから、よろず相談事業のほうは、これは変な話ですけれど、質問に来た人に、何歳ですかと聞かないですよね。その２点をお願いします。","respondent":"川原高齢者地域支援課長","answer":"ご質問の１点目です。定員１０名を基本としておりまして、定員を超えた場合は抽せんという形にします。８月コースの募集、次は９月の募集という形にしますので、万が一抽選で外れてしまった方は、次の講座へのご案内等もフレキシブルに対応していきたいと考えております。","voiceIndex":55,"id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１０人の定員は柔軟に対応していただきたいと思います。よろず相談は、ふらっと来た方も住所、氏名は書かなければいけないし、事前予約だと伺いますし、何かやっているよと、のぼりも立てるぐらいでしたら、きっとお見えになる方はいると思うので、そのときは対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-021"}]},{"id":"topic-05","title":"認知症本人・家族支援事業の実施","agenda":"認知症本人・家族支援事業の実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと(3)で、認知症本人とその家族の関係性に焦点を当てた支援の必要性が認められてきたということで、これは具体的に、認知症カフェだったり、本人ミーティングだったり、介護者教室、認知症講演会、こういうことの実施で必要性が認められてきたということなので、もう少し具体的に、認知症本人とその家族の関係性に焦点を当てた支援というのはどういうものなのか、伺いたいです。","respondent":"川原高齢者地域支援課長","answer":"３番目の、実際の支援の補助ですが、こちらは介護保険の任意事業という形で、介護保険特別会計予算から支出される形です。厚生労働省の地域支援事業実施要綱に今年度４月１日から新設されましたので、それに基づいて区のほうでも、既に要綱を策定しています。","voiceIndex":62,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、ミーティングセンターを開催して、運営の支援をしていくと。そして、開催・運営に向けた勉強会も実施するということで、これを実施するのは、業務委託になるのか、教えてください。","respondent":"川原高齢者地域支援課長","answer":"なので、区が講師を呼びまして、ミーティングセンターの在り方を教えていただくような形で、運営事業者には予定しています。","voiceIndex":64,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういうミーティングセンターを開催して、運営してもらう事業者を増やしていくというか、つくっていくということだと思うのですけれども、それは、区内にこれだけというような、目標とか計画的なところはあるのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"初めてですので、今年度中に２事業者もしくは３事業者、手を挙げていただけるといいなと考えています。","voiceIndex":66,"id":"exchange-024"},{"speaker":"あくつ副委員長","kind":"確認","question":"予算特別委員会等でも質問は出ていたかと思うのですが、もう一度、都内で初めて行うというミーティングセンターについて、幾つか確認をしたいのですけれども。専門職が関わるということになっていますけれども、今まで何度も出てきている質問だったら申し訳ないのですが、今回のミーティングセンターの持つ意義というものを確認する意味で、確認をさせてください。","respondent":"川原高齢者地域支援課長","answer":"現在、グループホーム等で実施しているかというご質問ですが、２０２１年度に全国のモデル事業所ということで、品川区の１介護事業所が選定されました。","voiceIndex":69,"id":"exchange-025"},{"speaker":"あくつ副委員長","kind":"質問","question":"私の理解が遅くて申し訳ないのですけれど、この（仮称）認知症ミーティングセンターとなっていたものが実際に動き始めるのは、いつからということなのでしょうか。場所というのはどこなのか。もう１回教えていただければと思います。","respondent":"川原高齢者地域支援課長","answer":"場所につきましては、特にこの場所というのは決まってございませんで、例えば今、モデル事業として動いていただいている、多機能ホームを運営している事業所についても、そこから通いやすい場所ということで、先日区のほうで借りたのは東品川文化センターだったのですけれども。","voiceIndex":71,"id":"exchange-026"}]},{"id":"topic-06","title":"後期高齢者医療制度における保険証の更新および窓口負担割合の改正","agenda":"後期高齢者医療制度における保険証の更新および窓口負担割合の改正","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで３年が終われば倍になっていくということですので、本当に大きな負担だと感じております。一番負担が減るのはどこかといえば国、そして自治体だということなのですよね。なので、今からでも、私たちはまたさらに、中止を求めていきたいと思っていますし、区からもそういう声を上げていただきたいと思っています。そこについていかがかということと。そこも伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"それと保険証につきましては、４万１,０００人ほどですけれども、短期証の方もおりますけれども、私どもは全員の方に送付する形を予定しております。","voiceIndex":78,"id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区長会で要望ということですけれども、後期高齢者保険料は今年も上がって、さらに、この６月に年金は引き下げられて、物価高騰もある中で、収入は減るのに、保険料も、窓口負担も含めて増えていくと。本当に、７５歳を超えた高齢者にとって苛酷な負担だと思っています。これ以上の、さらなる対象の拡大などもしないように、引き続き求めていただきたいと思いますが、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"先ほどと同じで申し訳ございませんけれど、私どもとしましては、区長会を通じまして高齢者の医療、生活弱者の方の負担軽減ということで、要望は続けてまいりたいと思っているところです。","voiceIndex":80,"id":"exchange-028"}]},{"id":"topic-07","title":"品川区における新型コロナウイルス感染症対策","agenda":"品川区における新型コロナウイルス感染症対策","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"幾つかお伺いしたいのですけれども、本当に急拡大ということで、都内の新規感染者も過去最高の３万人を超えると、品川区でも、先ほど課長からもありましたけれども、１日の新規感染者が１,０００人を超えているという状況です。今のところ区のホームページ等を見ると、まだ７日間となっているのですけれども、港区の保健所のホームページを見ると、もう５日間に変わっているのです。","respondent":"坂野保健予防課長","answer":"基本的に濃厚接触者の特定は、実はこの２２日の通知前から、やってない区は既にやっていなかったのですけれども、品川区はやっていたのですね。","voiceIndex":87,"id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"発熱外来の一覧表が東京都ベースでは出ているのですけれど、やはり区民は区のホームページで、どうなっているのかと、自分が症状が出たとき、まず何をするのか分からない方は、ホームページ等を見ると思うのです。今、大変な状況になっているのではないかと思うのですけれども、この間各部から応援をお願いしていたと思うのですけれど、今現在はどういう状況になっているのか、というのも伺いたいと思います。","respondent":"坂野保健予防課長","answer":"医療機関のリストですが、今、委員からお話もあったように、東京都のほうで一覧表を出して、区のほうからもう少し分かりやすく、確かにもうコロナは２年半以上やっております関係で、コンテンツがかなり、増築、増築で来ているものですから、若干分かりにくい部分がございまして。","voiceIndex":89,"id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"各部からも応援が来られているということですけれど、それで今、回っている状況なのかというのと、今、夜間までということでしたが、私たちも質問で取り上げてきましたけれども、深夜にまで及んで、本当に午前様のような状況もあったということで、残業時間も２００時間を超える方もいるということでしたけれども、今現在、それに似た状況になってしまっているのかどうか。","respondent":"坂野保健予防課長","answer":"ほかにも、例えば食べ物を届けるのは東京都がメインで、区は補完的にやっているといったような部分もございまして、なかなか説明しづらい部分も結構あるのですが、主にそういう分担です。","voiceIndex":91,"id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこへの支援というのを、もう少ししていただけないかというのが今、医師会等々からも要望されているのですけれども、都や国に求めると同時に、区としても考えていくべきではないかと思うのです。なので、そういった手当などを、やはり国や都に求めつつ、区としても検討していただきたいと思うのですけれども、いかがでしょうか。","respondent":"坂野保健予防課長","answer":"病院、医療機関、介護のところの負担がすごく増えているというお話ですけれども、いろいろこちらでもご意見いただいておりますので、適時適切に、都や国のほうに上げていきたいと考えています。","voiceIndex":93,"id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に、今、必要なところなので、ぜひ国や都がすぐにできない場合は、区のほうでそういう支援も考えていただきたいと思います。ですので、引き続き、これだけ急拡大している中で、またさらに防護服やゴーグル、グローブ……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今それが必要だと私も思うので、求めているのです。なので、ぜひ介護事業者へのそうした物品購入費の助成というのも、また国や都に求めていただきたいですし、区としてもぜひ検討していただきたいと思いますけれども、いかがでしょうか。","respondent":"今井福祉部長","answer":"介護事業者だけではなくて、今、高齢者施設でも職員の陽性者が増えている状況で、既に抗原検査キットなど手持ちのものは既に、追加して渡しているような状況です。今後も現場の状況をよく踏まえながら、どのような支援が必要かというのは検討していく内容だと考えています。","voiceIndex":97,"id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひお願いしたいと思います。それと最後ですけれど、今、抗原検査キットなども、もう早晩に足りなくなるのではないかという声が、現場からも出ているのですけれども、区としても確保が必要なのではないかと思うのですけれども、今、確保はされているのか、どれぐらいなのか、分かれば伺いたいのですが。","respondent":"坂野保健予防課長","answer":"具体的に何個かというのは今、手元に資料がないのですけれども、抗原検査キットは確保しております。","voiceIndex":99,"id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今、薬局でもＰＣＲ検査が、都の事業ですけれど、無料で無症状の方はＰＣＲ検査ができるようになっていますけれど、そこに私も問い合わせたところ、検査よりも抗原検査キットの売れ行きのほうが増えてしまっていて、もう足りなくなってくるのではないかというのが、薬局からも来ていますし、介護事業所、高齢者施設等々からの声もありますので、ぜひそこはさらに確保をしていかないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-036"},{"speaker":"あくつ副委員長","kind":"質問","question":"ワクチンの先ほどのご説明のことで、幾つか教えてください。ここについては、４回目は今、６０歳以上の接種率が２４.６％ということで、それなりに進んできてはいると思うのですが、例えばこの４回目を打たないで、つまり４回目にオミクロン株対応のワクチンを受けるということが、可能なのかどうか。そこまでまだ分からないということなのか。そこを教えてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"恐らくこの辺りの内容も、明日詳しく説明があるのではなかろうかと思いますが、現時点で私が把握している情報は、以上になります。","voiceIndex":103,"id":"exchange-037"},{"speaker":"あくつ副委員長","kind":"確認","question":"それと、４回目接種について、医療従事者、高齢者施設等の従事者に対しても拡大するということで、先ほどのご説明の中で、先週金曜日にホームページを確認したとき、そのような記載がもうあって、先ほどご説明があった８月４日以降、抽出した接種券については郵便局に持ち込むと。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その他については、他会場に行く、もしくは東京都の大規模接種会場等で打つという方に関しては東京都のルール、品川区内の集団接種会場にお越しの際は、やはり集団接種会場ですので、その後混乱を来しますので、券をご準備の上。","voiceIndex":105,"id":"exchange-038"},{"speaker":"あくつ副委員長","kind":"確認","question":"分かりました。ということは確認ですが、今のところ、いわゆる接種券なしでの接種については広報はしていなくて、さっきおっしゃったように関係者、自分のところでやっているところについては、そこの医院の判断、もしくはご自身の判断において、口コミでやっているということでよろしかったでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"はい、現在そのような運営をしております。","voiceIndex":107,"id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"理事者が入れ替わってしまったので聞けないかなと思いつつ、部長もいるので。発生状況を把握して、広がりを把握して対策を打つのが大事だと思うので伺うのですけれど。クラスターは高齢者施設、障害者施設で出ているのか、どのぐらい出ているのか、分かれば教えていただきたいのですが。","respondent":"坂野保健予防課長","answer":"毎日、数が更新されているので、今、幾つだというのは難しいところなのですけれど、数件、発生はしております。","voiceIndex":109,"id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"それは、高齢者施設でも障害者施設でも、数件あるということで、いいですか。","respondent":"坂野保健予防課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3636#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":33707,"voices":117}},{"id":"r04-20220725-8","meetingId":"r04-cm07","date":"2022年7月25日","dateIso":"2022-07-25","committee":"建設委員会","time":"午後 １時００分～午後 ４時３８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を72件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"(3)および(4)に記載の陳情３件につきましては、関連する内容のため、一括して議題に供します。 進め方としまして、３件の陳情","agenda":"(3)および(4)に記載の陳情３件につきましては、関連する内容のため、一括して議題に供します。 進め方としまして、３件の陳情","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"意見陳述を先に、住民の方の意見を聞いて審議をしていくべきだというふうに思いますので、そういった運営をよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":4,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、この３つの陳情、武蔵小山の再開発についての陳情ということで、まず、４４号について伺っていきたいと思うのですけれども、地権者の数等の説明を求めるということで書かれておりますが、やはり住民の今の関心は、どれだけの人がこの再開発に賛成をしているのか、あるいは準備組合に入っているのかということ、準備組合にどれだけの人が入っているかということも分からないところがありますので、あと。","respondent":"多並都市開発課長","answer":"今後につきましても、そういういろいろな多少の、総会の中でも状況をお聞きしていますが、年に１回は大きな中でお聞きしていますけれども、あとはタイミングを持ちながら区としても把握していきたいと思っているところです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"それと、今回様々な物価高騰などで、この事業がどうなるのだということも書かれておりますけれども、今、この事業はどういう状況になっているのかということ、この物価高騰に対してということです。それと、今回これが破綻をした場合に、地権者の連帯責任とか、そういった心配はないのかということも書かれておりますが、仕組み上、そこら辺がどうなっているのか、そこを伺いたいと思います。","respondent":"多並都市開発課長","answer":"それを今、準備組合の皆さんの中で検討されているということですので、破綻等がないように、まずは準備組合の中で検討していただいて、その検討された結果が申請として出されて、それが事業遂行能力として、必ずそれが進められるのかどうかについては、区もそうですけれども。","voiceIndex":11,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、これから進めていく手続きの流れというところでは説明いただいたのですけれども、それとあと、地権者が連帯責任を負うのではないかということで書かれているのですが、そこのところの仕組み、再開発の仕組みのところだと思うのですけれども、そこの説明をいただきたいと思います。","respondent":"多並都市開発課長","answer":"具体的な内容は、やはり事業の組立てがまだできていない段階ですので、これ以上この事業についてのお答えはできないかと思います。","voiceIndex":13,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"本組合設立後は、組合の施工だということで組合が責任を負うということだと、組合に入っているのは地権者の皆さんですから、その地権者の皆さんが責任を負うことになってしまうということだと思います。そこを伺いたいのと、先ほどの本組合のときに同意数を確認するというお話でしたけれども、これは区独自で把握をするということなのか、そこを確認させていただきたいと思います。","respondent":"多並都市開発課長","answer":"事業計画の前にというところですけれども、これについては、準備組合の皆さんで検討されている段階で、もちろんそれが成り立たないのであれば進まないはずですし、また、それをまとめられたとしても、東京都のほうの事業遂行能力というチェックの中で難しいということになれば。","voiceIndex":15,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"事業計画のところですけれども、本組合になる前の地権者の責任というか、被害というか、影響がどうなるのかというところを伺いたかったのですが、そこのところをもう一度ご説明いただければと思います。","respondent":"多並都市開発課長","answer":"事業計画を立てる際には、資金計画が必ず出てきますので、それを皆さんにご承認いただくことになります。その中で、誰がどういうふうに出すかというのが、もちろん財源構成の中に出てきますから、それをみんなで確認していくと、そういうことだと思います。","voiceIndex":17,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"この陳情のところで、４番目に現地視察をやるべきだということで、私もぜひやるべきではないかというふうに思います。この間もいろいろ議論はしてきましたけれども、現地を見ることで、より理解も深まるというふうに思いますので、この現地視察はやっていったらいいのではないかというふうに思いますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたら、質疑を続けさせていただきたいと思うのですが、４６号の陳情についてですけれども、まず事実関係の確認として、今回のこの計画で、アーケードとか駐車場などはどうなるのか。先ほど、アーケードは造り替えるということで、架け替えるということでありましたけれども、商店街の持ち物としてあるものが、開発によってどうなるのかというところをご説明いただきたい。はそれで。","respondent":"多並都市開発課長","answer":"もう１つの駐車場につきましても、現在、これはまたこれからお話ししながら、事業の計画としては、駐車場は地下に設ける予定ということになっております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"まだ最終的なところは決まっていないという下で、一旦壊されるわけですね。それで、今回新しくアーケードは架け替えるということですけれども、今回、第１・第２地区のところで新しくアーケードが造られるということだと思うのですが、そうすると、その後のここにある３部、４部とのつながりはどうなってしまうのかなというふうに思ったのですけれども、そこのところも確認させていただきたいと思います。","respondent":"多並都市開発課長","answer":"毎年、進捗状況に応じてトピックスになることをご説明いただいたり、または、アーケードの架け替えについて、こういう話をしてまとまったとか、あとは、最後にあるように、ザモールの関係で、こういうスキームで今回の商店街組合のほうに入っただとか。","voiceIndex":23,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"この陳情の中にも、３部、４部への流れがなくなってしまうということで、損害が生じるのではないかということが言われていますけれども、こういったことは、区として、どのように考えているのでしょうか。３部、４部への影響、損害です。そこを伺いたいと思います。","respondent":"多並都市開発課長","answer":"今おっしゃったつながりについては、もちろんこれから進めなければいけないところでもありますので、こういう点も踏まえながら、地域の方と一緒に考えていかなければいけないかなということを現段階で思っているところです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"そうした下でこの再開発も進められているわけですけれども、商店街の中で見ても、やはりこういった声が上がってくるというところでは、しっかりと合意形成ができていないのではないかというふうに思うのですけれども、区の認識を伺いたいのと、そうした中でこの再開発を強行していくというのは、やめるべきではないかというふうに思うのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"特に、賑わいの連続性がなくならないように工夫しなければいけないということで、開発の工事中も、そこはしっかり確保しなければいけないということで、そこについては、そういう点も区のほうから示しながら、皆さんで、特に商店街の方も一緒に入って、今、検討されているです。","voiceIndex":28,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうなると、３部、４部の方たちには大きな被害が出ることになってしまう。やはりこの中にも知らない人がいるということですとか、もちろん反対している人もいるというところで、こうした強行再開発、品川区としても税金を投入していくわけですから、こちらの責任があると思うのですけれども、この再開発を進めるべきではないというふうに、これは強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"この４７号の陳情は、いろいろこの間、武蔵小山の再開発の問題でも陳情が出されておりますけれども、陳情者の方にもお話を聞きまして、１つ１つの陳情で求めていることは違うものですので、それをやはり丁寧に審議してほしいということで、やはりそうしたことは、私もいろいろな意見を出しながら議論をしていくべきだというふうに思っているのですけれども、皆さん、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"芹澤委員","kind":"質問","question":"４７号について、まず、私の発言が発端でありますので、補足も含めて意見しますが、私の意見というか認識は、この切り抜きの発言から特段変わっておりません。ただ一方で、特に補足資料のほうですか、単に反対と位置づけるのは誤りであると考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-014"},{"speaker":"芹澤委員","kind":"意見","question":"そういう意味で、議論はこれまでも何度も何度も建設委員会のほうで丁寧に進めていると思っていますが、地権者でない、例えば私の発言で、反対、中止させるとか、あるいは逆に実施させるというような思いはありませんので、そういった意味で発言をさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-015"},{"speaker":"芹澤委員","kind":"質問・要望","question":"すみません、では、４６号の確認であります。先ほど、アーケードの話がいろいろ出ていたのですけれども、要旨としては、法的な瑕疵、根拠を欠くというところが前提にあると思うのですけれども、そこだけ改めて行政の認識を教えていただきたいと思います。","respondent":"多並都市開発課長","answer":"この陳情の中で書かれております商店街の重要財産の処分に関する等の法律につきましては、商店街振興組合法の６４条に特別の議決ということでありまして、この中では定款の変更だとか、組合の解散又は合併、組合員の除名と限定列挙されている内容であって。","voiceIndex":37,"id":"exchange-016"},{"speaker":"のだて委員","kind":"意見","question":"すみません、先ほどの４７号の芹澤委員の発言で、賛成、反対は言えないというような説明でしたけれども、やはり議会は、最終的には、賛成、反対を問われることになりますので、当事者としてと言うとおかしいですけれども、陳情者の意見を踏まえて、自分なりの賛成、反対を出していくべきではないかなというふうに思うのですけれども、それが議会の役割ではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-017"},{"speaker":"芹澤委員","kind":"意見","question":"賛成、反対を、私個人として、委員として言えないという話ではなくて、我々が、それこそ今おっしゃっていただいたように、それぞれの地域の代表でありますから、それを言うのはもちろん結構でありますけれども、その意見をもって、議会がその事業を中止させるとか、あとは実施させるということはできないというようなお話をさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"それぞれの地域の代表で出ているわけで、その事業の中止をさせることはできない。当然、執行者は自治体なわけですけれども、やはりそうしたところで、そうした執行者は二元代表制になっているのが議会ですから、議会での結論を反映してやっていくということになると思いますので、議会としてもそういった立場をしっかり表していくべきではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民の方が直接議会にいらしていただいている下で、直接声を聞くということが、実態をより把握することになると思いますので、意見陳述をぜひ実施していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-020"},{"speaker":"芹澤委員","kind":"確認","question":"本日結論を出すで、不採択でお願いします。内容として、まず、そもそものタイトルにもあります虚偽答弁というものも確認がとれませんでしたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"本日結論を出すでお願いします。不採択を主張いたします。今、質疑が行われました。それを聞かせていただいたときに、答弁のところから状況も理解できましたし、また、私は今日の委員会に参加するにあたって、６月２７日の議事録ももう１回見直してきました。そういった意味からすると、本陳情については、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-022"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、趣旨採択を主張します。地権者等の数ですとか、あと、物価高騰で事業がどうなるかということを説明してほしいという気持ちは分かりますし、より理解を深めるために現地調査もすべきだと考えますので、趣旨採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-023"},{"speaker":"芹澤委員","kind":"確認","question":"本日結論を出すで、不採択でお願いします。先ほどと同じですが、前提条件の法律の根拠を欠くというところが確認とれませんでしたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-024"},{"speaker":"こんの委員","kind":"確認","question":"本日結論を出すでお願いします。不採択とします。商店街振興組合のほうで事業計画等々を出されているのも確認をしてくださっているということを伺いましたので、よって、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-025"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、趣旨採択を主張します。商店街において合意形成が不十分であり、その上で再開発を進めるべきではないというふうに考えますので、趣旨採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-026"},{"speaker":"横山委員","kind":"確認","question":"本日結論を出すで、不採択でお願いいたします。先ほどのご答弁のご説明の中で、他課と情報共有していただいたりですとか、あとは、それぞれのタイミングで区のほうではチェックを、確認をしていただいているということでしたので、そのようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"結論を出していただきたいと考えています。不採択でお願いいたします。これは我が会派の芹澤委員からも、先ほど来、審議の中で話をさせていただきましたが、そのときも申し上げたと思いますが、我々は、反対意見であるようなことだからといって、しっかりそれは公平・公正な取扱いをしていると我々は思っておりまして、不採択ということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-028"},{"speaker":"こんの委員","kind":"意見","question":"本日結論を出すでお願いします。不採択とします。委員会の審議は、様々な意見で議論をしながら、各会派から代表の議員が出て議論しているわけですので、そうしたことの中で結論を出していくということを考えると、これまでも公正な取扱いをしてきたと、このように認識しておりますので、不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日、結論を出すということで、不採択を主張します。陳情者にお話も伺いましたけれども、武蔵小山の再開発に関わる様々な陳情、各委員が１つ１つ丁寧に審査をしてほしい思いだということが分かりました。発言する、しない、どのような発言をするかは各委員の責任に委ねられますので、したがって、１つ１つ丁寧に議論してほしいという気持ちは分かりますけれども、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問","question":"この再開発がいろいろな影響を及ぼしているという陳情ですけれども、特に電力不足ということで書かれておりますが、再開発をすることによって電力の消費が増えるというふうに私は思うのですが、区の認識を伺います。","respondent":"多並都市開発課長","answer":"ただ、このまちの基本としては、地域の方が皆さんでお話合いいただき、その中で共同化しながら事業を進めていこうということで、その事業の過程で進んでいる事業でもありますので、そのような中で一定共同化しただけではなくて。","voiceIndex":80,"id":"exchange-031"},{"speaker":"のだて委員","kind":"確認","question":"計画の中の位置づけで環境への配慮がされているという意味の答弁ですか、今のは。その確認と、超高層ビルが建てられると、ここにも書いてありますが、４０階建てとかが建つわけです。住宅はもうそんなに必要ないという話もありますけれども、住宅供給としても、これは品川区内でということになると思いますけれども、区としては、住宅供給が足りないと考えているのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"省エネルギー化についてのお話ですけれども、もう一度ご説明しますと、都市開発諸制度という制度で、公共性の空地などを設ける代わりに高度化を図るというその制度の中でいろいろ公共施設を整備することが義務づけられていまして。","voiceIndex":82,"id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"省エネのところ、地域の課題解決をどうやるかというところで、多くの場合、超高層再開発になってしまうという実態があります。その中で省エネもやっているということですけれども、やはり省エネしても、床の増える量が尋常ではないですよね。やはりそこでエネルギー消費は必然的に増えていくということになってしまうと思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"従前の土地の捉え方も１つありますけれども、今、要するに、本来だったら容積率がありまして、それいっぱいに建てる建物が建っていることがあれば、それがまず１つですけれども、よくあるケースは、駐車場だったり、未利用地が非常に多いところに対して。","voiceIndex":84,"id":"exchange-033"},{"speaker":"のだて委員","kind":"質問","question":"実際は増えていると私は思うのですけれども、そうしたことも実際やるべきだと、把握しないと実際の影響は分からないというふうに思うのですけれども、いかがでしょうか。考えないと、どんどん増えていく一方になってしまうと思うのですけれども、いかがでしょうか。それで、日照の問題も今回書かれておりますけれども、１００ｍを超える超高層ビルが建てば、やはり周辺住民の方には大きく影響が出る問題です。","respondent":"多並都市開発課長","answer":"地区の特性に応じてそれも示されているものでありますので、これにつきましては、先ほど申しましたけれども、地区に応じて、まずは地域の方が、お住まいの方々がどういう生活再建をされるかというのが１つと、あとは。","voiceIndex":86,"id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"いろいろ説明いただきましたけれども、やはり地域住民にもそうですし、区全体での影響も様々あるという中で、やはり地域の課題解決に向けては、超高層ビルでないやり方もあるわけですから、ぜひそうした様々影響のあるようなやり方ではない方法でやっていくべきだと言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-035"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。要旨にあるような建築物の大型化、高層化ありきの再開発という認識ではありませんので、先ほどお話もありましたが、まず、まちの課題があって、それを解決するための開発が一定程度あって、電力についても、先ほど省エネルギー化というような制度もあるというお話もありましたので、今回に関しては不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-036"},{"speaker":"こんの委員","kind":"質問","question":"本日結論を出すでお願いします。不採択でお願いします。感覚的に、床が増えれば消費電力が増える、感覚的にそうなのだろうというのは、否定というか、理解というか、そうなのだろうとは思うのですが、今の質疑の中で、きちんと開発を進めるに当たっては、省エネルギー化基準にのっとってとか、また、従前との比較が難しいというご説明もありました。よって、これは不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-037"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。超高層ビルが都心に建ち並び、電力消費、大量に消費をするということや、周辺環境を悪化させているという中で、この超高層ビルはやめるべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-038"},{"speaker":"横山委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。先ほどありました議論の中で、区としましては、地域特性によって、区や都の施策に沿ってまちづくりを進めていて、また、法律ですとか、方針ですとか、様々な基準に従って進めているというふうに理解いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-039"}]},{"id":"topic-02","title":"八潮五丁目地区まちづくりワークショップの実施状況","agenda":"八潮五丁目地区まちづくりワークショップの実施状況","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認のところで、取り組みテーマのテーマ3)コミュニティのところで、多世代交流や賑わい創出を支援するまちづくり拠点の整備を促進ということで書かれているのですが、まちづくり拠点というのは、どういうものなのか、これから具体的に検討していくということになると思うのですが、そこを伺いたいのと、テーマ4)のにぎわいのところです。","respondent":"鈴木都市計画課長","answer":"資料２の、まずご質問いただきましたテーマ3)のコミュニティのところですが、具体的に、本ガイドラインにつきましては、何かもう決まって、ハード的な建物、特にハード的な整備を目指して。都心に立地しながら有する豊かな自然環境を、土地利用との調和を図りながら保全・活用、八潮の地域の皆様も感じていらっしゃる、区のほうでも感じている最大の魅力は、やはり豊かな緑ですので、ここを今後もしっかり。","voiceIndex":102,"id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"意見のところにも、落ち葉がたまって歩きづらいということが書かれておりますけれども、私も通ったことがありますけれども、硬い種か何かがいっぱい落ちていて、そこを歩くと、本当に歩きづらいというのは確かにあるのですけれども、やはりそうした自然が自然のままあるというのも、やはり緑道の魅力かなというふうに思いますので、歩くスペースは確保していただいて、緑道の自然を残しつつ。","respondent":"鈴木都市計画課長","answer":"初めの緑道のところの樹木の伐採のお話ですが、東京都もこの緑道公園部分、最近整備していただいたところもあって、そうしたときには地域の方の意見もお聞きして、ファニチャーなどの整備も押してやっていただいたというところで。やはり地域の方にお集まりいただいていろいろご要望をいただきますと、本当に具体的な機能を欲しいと、その眼科も１つの具体的な声としていただいているわけですが、区とすれば、そうした施設を誘致というのは。","voiceIndex":105,"id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"倒木で停電があったということで、ここはやはり安全な管理をできるようにしていただきたいというふうに思います。ワークショップとかのことですが、今後、予定どおりやっていくというような説明だったと思うのですけれども、今回公募してワークショップをやらないとした理由を伺います。","respondent":"鈴木都市計画課長","answer":"失礼しました。最終的に、今回は全戸配布による意見募集も素案に対して行う考えでおりますので、公募によって今回募集というよりは、自治会、あるいは子育て世代、そうしたところにお声がけをさせていただいて進めさせていただいたです。","voiceIndex":108,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"全戸配布で意見募集をするということで公募しなかったということですが、やはりそういった意見募集とワークショップとかをやるというのは、少し違ってくると思うので、ここはやはり今後でもやるべきだなというふうに、これは要望しておきたいと思います。意見募集を、八潮内は全戸配布するということですが、そのほかの区民に対しての周知はどうなっているのか伺います。","respondent":"鈴木都市計画課長","answer":"今現在、素案の段階で、同様に広報に載せて意見募集をするという考えは今のところございません。やはり地域の方に全戸配布して、まずは意見をいただきたいです。","voiceIndex":110,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"今回、意見募集は、ほかの地域ではやらないということですが、区報に載せるぐらいはするべきではないかというふうに思いますが、いかがでしょうか。そうすると、ほかの地域の人たちは、このガイドライン案がまとまったところで意見募集とかパブリックコメントをやるということなのでしょうか。他地域の人の意見を反映するというのはどうされるのか伺います。","respondent":"鈴木都市計画課長","answer":"その上位計画のマスタープランの中で、マスタープランのほうは、当然ながら、このガイドラインの上位計画になりますので、より細かいところの記載というよりも、もうちょっと広い視点での記載になりますが。","voiceIndex":113,"id":"exchange-044"},{"speaker":"こんの委員","kind":"確認","question":"細かいところを１点確認させてください。このワークショップの主な意見の中で、団地内の緑道に仕事ができるスペースがあるとよいという、この仕事ができるスペースとはどういうものなのでしょうかというのが１つ。もう１つは、そもそもこの八潮団地を品川区が開発し、ああいうまちづくりをしたコンセプトを確認させてください。","respondent":"鈴木都市計画課長","answer":"ご質問いただいた八潮団地、まちづくり、当初の全体のコンセプト、考え方、委員にご指摘いただいたとおり、居住機能だけ充実させていきましょうということではなくて、団地内で、学校を含め、福祉施設を含め、生活支援機能を含めて。","voiceIndex":116,"id":"exchange-045"},{"speaker":"こんの委員","kind":"質問・要望","question":"よく分かりました。今のテレワークをされたい、あのまちの中でお仕事もできる環境をというのは、確かに、あそこの八潮団地内が高齢化していることを考えると、若い世代も取り込めるということを考えたときに、そうした考え方を取り入れていくまちづくりは必要なのだろうなと、今聞いていて思いました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-046"},{"speaker":"横山委員","kind":"確認","question":"すみません、まず確認をさせてください。Ａ４のほうですけれども、第２回ワークショップの実施というところで、こちらの参加者は、第１回のワークショップと同様の方々、自治会・管理組合からの推薦の方と子育て世代の方ということでよろしいのか、確認をさせてください。","respondent":"鈴木都市計画課長","answer":"Ａ４縦の資料の２回目に参加の方々が同じ方々かというところですが、2)、3)の子育て世代、２回に分けて行っておりますが、この方々は１回目と同じ方々です。","voiceIndex":120,"id":"exchange-047"},{"speaker":"横山委員","kind":"質問・要望","question":"八潮の本当に緑豊かな環境は、八潮の子どもたちもそうですけれども、全区的に、品川区内の子どもたちにとってもすごく財産になるのかなと思いますので、まずは八潮の子どもたちというところからスタートなのかと思うのですけれども、そこから家庭菜園を借りてですとか、具体的にというのはこれからかと思いますけれども、緑育活動を八潮を中心に広めていけるような。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-048"},{"speaker":"西村副委員長","kind":"質問","question":"１点だけ、すみません。意見のところにも課題のところにもありまして、近年、八潮のほうで外国籍の方が増えてきているというところで、今後の予定の９月、意見募集のところで、全戸配布、英語の記載などをご検討かどうかだけお伺いさせてください。","respondent":"鈴木都市計画課長","answer":"具体的には、配布に当たって、戸別配布を考えておりますので、どこに外国の方がお住まいなのかというところの、そうしたところに英語表記のものをいかに正確にお届けするかというところの工夫は必要かと思いますので、場合によっては、ネット等も活用して。","voiceIndex":126,"id":"exchange-049"},{"speaker":"西村副委員長","kind":"意見","question":"なかなか全て英語でどこまで皆様に届けられるのか、難しい部分はあると思うのですが、ＱＲコードで飛んでみるとか、今風かもしれませんけれども、ぜひともご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-050"}]},{"id":"topic-03","title":"東京都市計画 住宅市街地の開発整備の方針の変更","agenda":"東京都市計画 住宅市街地の開発整備の方針の変更","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、新たにゾーンになったのが国際ビジネス交流ゾーンというのができまして、この中では国際水準の住宅やサービスアパートメント、企業、保育、子育て施設などの整備を急増すると書かれているのですけれども、これは外国人富裕層のためのまちづくりをしていこうということではないかと思うのですが、そこのお考えと、そういったことはやはりやめるべきだというふうに思うのですけれども。","respondent":"鈴木都市計画課長","answer":"外国人向けのホテルですとか、サービスアパートメントですとか、そうした機能の集積、これは、例えばですが、荏原地区にも該当するような、木密地域にも該当するような記載となっておりまして、繰り返しになりますが、やはり２３区全体、特に、国際交流。","voiceIndex":133,"id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"特に、ここだったら品川駅南のところは地区の中に都営住宅も入っておりますので、やはりそうした都営住宅をさらに増やしていくですとか、区営住宅でもいいですけれども、そういったことをやっていくことが必要だというふうに思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今後、区営住宅を増設していくというところの考えはございません。","voiceIndex":135,"id":"exchange-052"},{"speaker":"のだて委員","kind":"質問","question":"日本の住宅自身が狭くて、今、国が決めている一般的な水準を確保しようというところにも達していないところが多くあるところですから、そこの全体を引き上げていくということに注力をしていくということが必要だというふうに思います。もし答弁が何かありましたら。","respondent":"鈴木都市計画課長","answer":"この政策を、住宅施策、外国企業誘致の施策を最重要、最前面に押し出して、都として取り組んでいくということは、全くこの方針の中ではそうした位置づけを書いているわけではございませんで、様々な対象の方に対して、住宅施策を各自治体と連携して取り組んでいく。","voiceIndex":137,"id":"exchange-053"}]},{"id":"topic-04","title":"会議の運営上、予定表の順番を入替えまして、(4)「東京河川改修促進連盟」の総会および促進大会","agenda":"会議の運営上、予定表の順番を入替えまして、(4)「東京河川改修促進連盟」の総会および促進大会","exchanges":[{"speaker":"こんの委員","kind":"意見","question":"今、芹澤委員のほうからもありましたので、どうぞというところで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうですね、立候補がありましたので、ぜひ行っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-055"}]},{"id":"topic-05","title":"（仮称）旗の台六丁目公園整備工事","agenda":"（仮称）旗の台六丁目公園整備工事","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、若干、防災訓練のできる広場中心ということでご説明があったのですけれども、この中に防災井戸とか、かまどベンチですとか、マンホールトイレもありますけれども、そうすると、この公園の位置づけというのですか、防災公園ということになるのか、そこを伺いたいと思います。","respondent":"高梨公園課長","answer":"ただ、公園には様々な機能がございまして、遊具で遊べば児童遊園的な側面もありますし、今回、ワークショップ等で一番声の大きかった防災訓練をメインで使いたいということですので、防災広場的な機能も備えた公園という形になろうかというふうに考えております。","voiceIndex":156,"id":"exchange-056"},{"speaker":"横山委員","kind":"確認","question":"すみません、何点か確認させてください。マンホールトイレですけれども、こちらの型式はどのようなものになっておりますでしょうか。健康遊具も具体的にどういったものを予定しているのか教えてください。","respondent":"高梨公園課長","answer":"マンホールトイレですが、こちらは溜め式のものを予定しております。それと、健康遊具ですけれども、これはステップして運動ができるような形、このようなものを考えているところです。","voiceIndex":159,"id":"exchange-057"},{"speaker":"こんの委員","kind":"質問・要望","question":"私も２点確認します。防火水槽ですけれども、これは今回、防災訓練をできる公園という要望から、この防火水槽、いわゆる防火水槽を設置できるのは、何か基準があるのか。ほかの公園にも防火水槽をつけることができるのか、その辺を教えてください。入り口、それから園内全体とか、カメラそのものの機能はどういうものが設置されるのか教えてください。","respondent":"高梨公園課長","answer":"ただ、出入口部分を含めて、できるだけ多くの部分を視界に入れることができるような、そういった立地関係を検討いたしまして、今回も入り口近くに設置して、より広い部分を網羅できるような形で設置をしたい、このように考えているところです。","voiceIndex":162,"id":"exchange-058"},{"speaker":"こんの委員","kind":"確認","question":"防火水槽、分かりました。こうしたものは、ほかのところでも必要だと思うので、設置基準、あるいは対象となるところは可能であれば、こうした整備は今後もお願いしたいというところです。防犯カメラも分かりました。公園の周りが住宅地なのか、それとも商業地なのかにもよるので、防犯の意識によって、やっぱり１台ではなく２台つけていくという考え方があるのか、その辺をもう１回確認させてください。","respondent":"高梨公園課長","answer":"今回の（仮称）旗の台六丁目公園は、四角い形の比較的形のいい公園ですので、入り口も１つですし、１台設置すると、機能的には網羅できるのではないかというふうに考えておりますが、公園の中には長細い公園もありますし、複数出入口があるような公園もありますので。","voiceIndex":164,"id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"確認","question":"ちょっと確認だけさせてください。これ、防火水槽を置くということは、防災倉庫にスタンドパイプとかを置くという理解でいいのでしょうかということが１つと、トイレがあって、これはこういうトイレを置くときは、中央公園でやったみたいに下水道直結というのか、何かやっていましたよね。","respondent":"高梨公園課長","answer":"防火水槽の設置に伴ってスタンドパイプを置くかどうかといったところですが、まず、防火水槽は、マンホールを開けるとすぐにポンプを入れられるような形になりますので、防火水槽自体にはスタンドパイプは必要ではないというふうに考えておりますが、ただ。","voiceIndex":168,"id":"exchange-060"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"延床面積が５,０００m2ということですけれども、この右側の図でいくと、ピンクで網かけされている建設範囲（想定）となっているのですが、ここを一体的なのか、いわゆる水族館の建物自体は、これまでと同じぐらいの規模のものなのか、その辺を１点確認と、主な展示理念というところで、もう少し具体的に教えていただきたいのですが、しながわ区民公園の自然と調和し、水中感あふれる展示と。","respondent":"高梨公園課長","answer":"今申し上げたところですけれども、やはり公園の中の水族館というものが全国的にもあまり例を見ないものですので、特に都市部にありながら緑の自然、それと勝島の水辺という自然を水族館展示の中にうまく融合させて。","voiceIndex":174,"id":"exchange-061"},{"speaker":"こんの委員","kind":"確認","question":"そうすると、建物の大きさ、平屋なのか、複層階なのかによっても、これから事業者からプロポーザルをいただいて、どのようなものかということで選んでいくと思われるのですが、ゼロベースでもらったものから選ぶというよりは、品川区としてどうしていきたいか、どう公園をというところを持ち合わせていらっしゃってのことですよねという確認が１つ。","respondent":"高梨公園課長","answer":"１点目の区としての考えを持ってといったところですけれども、正しく今年度、この方向性を基に、来年度の事業提案競争に向けて、区としての考えをしっかりまとめる作業を今年度実施しようというふうに考えてあります。","voiceIndex":176,"id":"exchange-062"},{"speaker":"こんの委員","kind":"質問","question":"もう１つ、公園の中で、いわゆる集客と今度考えたときに、今もレストランが１つありますけれども、そういう営業的な収益を要するようなものが、今後、このエリア内にできるものなのか、どれぐらいつくっていこうとされているのか。その辺はどういうふうになるのでしょうか。","respondent":"高梨公園課長","answer":"区といたしましても、非常に重要な要素であるというふうに認識をしておりまして、今回の提案の中では、新しい水族館の建物の中にそういった機能を入れるのか、現在のレストラン、水辺に浮かぶような形で立地していますので、あそこをどう生かすのかといったところも含めて。","voiceIndex":178,"id":"exchange-063"},{"speaker":"芹澤委員","kind":"提案","question":"２点お伺いしますが、この建設のところとは少しずれるのですけれども、以前から会派で、船を活用したしながわ水族館の運用を要望させていただいていて、今、船着場があると思うのですけれども、今回のリニューアルに当たって、あれをあのまま使っていくのか、もしくは新しいやり方で何か船をうまく活用できるのかということを非常に楽しみにしているのですけれども、そこの船の活用に対してのアイデアは。","respondent":"高梨公園課長","answer":"まだ民間事業者のほうから、どのような内容の意向が出てくるかということは見えないところですけれども、区といたしましては、やはり天王洲やそのほかの水辺を含めて。","voiceIndex":182,"id":"exchange-064"},{"speaker":"芹澤委員","kind":"提案","question":"そういった意味で、品川らしさの１つが水辺の利活用というところだと思っていますので、事業者からの提案というところで、もう既にされていらっしゃるかもしれませんが、見落としていると水辺の船着場の活用というのが提案に入ってこないのかなと思っていますので、ぜひそこは、天王洲だったり、いろいろなところとの水辺のネットワークも使っていただいてというような、一言添えていただくと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":184,"id":"exchange-065"},{"speaker":"石田（秀）委員","kind":"質問","question":"どういう感じなのかによって業者も変わるではないですか。そういうのは、いろいろなものがあるでしょうし、あと、今、水辺の話が出たけれども、前も言っていたけれども、例えば競馬場との連携とか、そういうものもあるではないですか。そういうものも中に入れ込んでやってもらうとか、そういうことを行政側で考えていらっしゃるのかということを教えてください。","respondent":"高梨公園課長","answer":"現在の施設でも、一定、レースの際の協力であるとかをやってありますけれども、営業時間も含めた連携というところを、リニューアルに際しましては、積極的に区としても働きかけてまいりたいと思いますし。","voiceIndex":186,"id":"exchange-066"},{"speaker":"横山委員","kind":"確認","question":"すみません、何点か伺います。５ページのところですけれども、水族館の社会的役割とされる活動の中で、種の保存活動ですとか調査・研究活動というところをこれまで担ってきたかと思うのですけれども、今後どういった考え方で継続、引き継いでいくのかというところを確認させてください。こちらは資料がなければ大丈夫です。そこまでお願いいたします。","respondent":"高梨公園課長","answer":"その部分につきましては、次の新しい水族館の事業者がどこになるかというのはこれから決まっていくわけですけれども、やはり公立の水族館として、こういった種の保存活動であるとか、調査・研究活動への協力、連携といったものは積極的に行ってまいりたいと考えていますし。","voiceIndex":189,"id":"exchange-067"},{"speaker":"横山委員","kind":"提案","question":"ご説明ありがとうございました。老朽化のところに関しましては、確かに技術などもいろいろ新しいものが出ているかと思います。メンテナンスしやすいものですとか、維持管理しやすいものですとか、そういったところ、今後の長い３０年間というところなのか、その後どうしていくのかを含めまして、様々いい提案が出るような形で募集をかけていただきたいというふうに思っております。","respondent":"高梨公園課長","answer":"公立水族館にふさわしい魅力的な展示というものを、この先、検討、選んでいけたらなというふうに思ってあります。最後に、人文的博物館であるべきといったところですが、ここの部分につきましては、検討委員会での委員からの意見です。","voiceIndex":191,"id":"exchange-068"},{"speaker":"西村副委員長","kind":"質問","question":"リニューアル期間中について１点だけお伺いしますと、現施設の近くに新施設を完成させてから展示を移すというような方針でいらっしゃると思うのですけれども、リニューアル中の閉鎖期間がどれぐらい短く済みそうなのか、もし分かっていればお知らせください。","respondent":"高梨公園課長","answer":"詳細な閉鎖期間につきましては、これから事業者の提案と検討の中から決められてくるものというふうに考えてありますが、生物の移転であるとか、あと、新しい水族館でのオペレーションの確認等々を含めますと、専門家会議等で聞いたところによりますと。","voiceIndex":194,"id":"exchange-069"},{"speaker":"西村副委員長","kind":"質問・要望","question":"区に寄せられた意見とか要望のところにもありましたけれども、地域密着型というのは、本当にこのしながわ水族館には私自身も感じておりまして、これは要望ですけれども、地元の中学生の方たちが、デートで行っていますとか、あと、私自身も子どもが先日行かせていただいて、スタンプラリーをしたいからまた行きたいとか、ピークのときより４分の１に減ったとはいえ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-070"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、主な展示理念の中で、区民アイデアを取り入れた展示というところがあるのですけれども、これはどういった形でやられていくのかということと、やはり公立水族館なので、入館料をぜひ低廉な額で入れるというふうにしていただきたいと思うのですが、いかがでしょうか。","respondent":"高梨公園課長","answer":"２点目の入館料についてですけれども、やはり公立の水族館といったところで要望されるというところはあると思いますので、リニューアル後の入館料につきましては、今後そういった意見も踏まえた上で検討してまいりたいというふうに考えてあります。","voiceIndex":197,"id":"exchange-071"},{"speaker":"石田（秀）委員","kind":"質問","question":"すみません、１点だけ。契約方法も、その項目に入るという認識でいいのでしょうか。","respondent":"高梨公園課長","answer":"事業者との契約方法についても、今現在、検討中です。来年度の公募の際には、当然こういった形で契約することを考えているというものは、実施要項の中に盛り込むべきであるということで、現在、検討しています。","voiceIndex":200,"id":"exchange-072"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4356#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":57728,"voices":208}},{"id":"r04-20220725-9","meetingId":"r04-cm07","date":"2022年7月25日","dateIso":"2022-07-25","committee":"文教委員会","time":"午後 １時００分～午後 ２時２８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和５年度 新入学者の受入枠","agenda":"令和５年度 新入学者の受入枠","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"そもそものところで、この受入枠を発表する目的というのは何なのかを改めて伺いたいです。それと、受入可能枠というのはどのように決めているのか、もう少し伺いたいです。今年度の実績があって、それとの関係はどのようになっているのでしょうか。その下辺りの御殿山小学校は逆です。それぞれどのように決められるものなのか、もう少し具体的に説明いただきたいと思います。","respondent":"勝亦学務課長","answer":"ただ、こちらも、住民基本台帳上で学区にお住まいの方は全て受け入れるという形になりますので、３学級設定で９５人を超えた場合、４学級設定等に増やす必要がある場合は増やすという対応をするものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。その余裕分でしたら３０人だと思うのです。伺います。子どもの教育環境を第１に考えるべきだと思いますし、現状の区教育委員会の３５人で受入れを考えていくという対応は、現場では、安易に４０人でもいいかという、学級を無理に分けなくても加配でいいですかという感じで捉えかねない、誤ったメッセージを送ることにもなってしまうのではないかなと思うのですけれども、いかがでしょうか。","respondent":"勝亦学務課長","answer":"こちらについては、中１ギャップ対策ということで、学級規模の縮小、もしくは教員の加配が選べるという制度になってございまして、３５人で学級編制をしてくださいという趣旨のものではございませんので、そこについては４０人が適切と考えています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"基本は、やはり学級数を３５人にする。その趣旨というのは、基本的には３５人でやるべき。学級を分けないのです。それは、私は納得いかないので、認識を改めていただいて、受入枠についても、基本的には１学級３５人なので、それを加味して３０人という受入枠に、ぜひ改善していただきたいと思います。意見ですけれども、最後、何かありましたら、ぜひお考えを聞かせていただければと思います。","respondent":"勝亦学務課長","answer":"こちらは教育の実情に即して、加配を選ぶか、学級規模縮小を選ぶかという制度となっていますので、原則が３５人という認識は、こちらのほうではしていないところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"なるべく３５人に近づけて、３５人よりも少なく、子どもたちがゆとりを持って学べる環境づくりをしていっていただきたいなと思います。ここに関して何かあれば伺いたいです。質問として、現時点で、小学校、義務教育学校、中学校と、学区内だけで受入れが難しくなりそうな、他からの選択ができなくなりそうな学校があるのかということを伺いたいのですけれども、いかがでしょうか。","respondent":"勝亦学務課長","answer":"ただ、こちらの加配の部分等々につきましては、学校の教育活動の中で、空間の確保も１つの要素ですし、教育効果の考え方という部分も含めて、学校と相談しながら区が決めていくような形になりますので、そういった対応をしているものです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"今、お話があった９校を教えていただけますか。これからも、次の４月のときにもなかなか難しそうなのか、それともこの９校では受入れが可能になりそうなのか、そのようなところも伺いたいと思います。先ほどの３５人と４０人のところで、小学校では、やはり人数が多くて加配されていて、でも、コロナ対策をしなければいけないということで、子どもたちが教室に入り切らない。","respondent":"勝亦学務課長","answer":"今年度、学校選択で学区外からの入学ができない学校につきまして、具体的な学校名です。城南小学校、御殿山小学校、芳水小学校、山中小学校、浜川小学校、京陽小学校、小山小学校、源氏前小学校、第二延山小学校です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"田中委員","kind":"確認","question":"９校をうまく聞き取れていなかったのか、中学校は特になかったということでよろしかったでしょうか。確認させてください。","respondent":"勝亦学務課長","answer":"中学校に関しましては、お一人も受入れができなかった学校はございません。","voiceIndex":15,"id":"exchange-006"},{"speaker":"渡部委員","kind":"質問・要望","question":"その５人だか１０人の枠というのは、それはいいのです。だから、それに関しても、今までの流れというのはあるのだけれども、そうなった場合にどうするかということをしっかりと持っておいてもらって、いざそうなってからどうしようではなくて、こうなった場合、こうするぞというのは、当然、行政ですから、あると思うのです。その辺をしっかりやっておいていただきたいという要望です。","respondent":"勝亦学務課長","answer":"そういった部分につきましても、１つ１つ、ご理解いただけるような情報発信、ご説明をしていきたいと考えていますので、よろしくお願いします。","voiceIndex":18,"id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"よく分かっています。よく分かっていますし、それはお願いしたいのですけれども、今言った３番４番の関係は、僕が区民だとして、何でこの学校は１１５人で３クラスで、この学校は１０８人で４クラスなのと質問したら、どのような答えが的確で、分かりやすいのかということを聞いている。それを教えてほしい。","respondent":"勝亦学務課長","answer":"失礼いたしました。浜川中学校に関しましては、学区の人数の方をできるだけ受け入れていくという考え方で、キャパシティーを含めて、今、４学級最大に取っているところです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"要は、結局、各委員の質問というのは、この問題は、私たちは地域からの相談も結構あったりして、１０月に入ると選択が始まります。ですから、それも後追いで、例えば、今年の資料で去年の実績が出たときに、人口の云々はいいのだけれども、今年の４月自体が、浜川中学校は１０８人なのに４クラスで、鈴ヶ森中学校は１１５人で３クラスだよと言われたときに、僕らは何も知らないのでは、答えられないのです。","respondent":"勝亦学務課長","answer":"現状、浜川中学校につきましては、先ほど話に出ました中１ギャップ加配の中で、学級数増の少人数を選択している状況です。そのため、４学級になっております。鈴ヶ森中学校につきましては、学級数を増やさずに４０人学級で編制をして、教員を加配しているという違いです。","voiceIndex":22,"id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"それも分かっていて、それを誰が決めるのですか。学校長が決めるのですか、教育委員会が決めるのですか、相談によって、では、この学校はこうしていいですよ、この学校はこうしていいですよとなるのですか。その答えだけが知りたい。内容は分かっている。","respondent":"勝亦学務課長","answer":"大変申し訳ございません。こちらにつきましては、学校と相談の上、教育委員会で判断をして、決定しています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"若林委員","kind":"確認","question":"今の答弁のやり取りで、まだ理解ができていない。募集があって、いわゆる選択があって、そこからの一連の流れを、いま一度確認するというと文教委員会っぽくないのですけれども、その流れと、先ほど、もし私の聞き間違いだとしたら指摘をしていただいて、要するに、この設定で学校選択がしやすくなるという説明だとしたら、もう一回、そこの分かりやすい説明を聞きたいなと思います。","respondent":"勝亦学務課長","answer":"そういった中では、今まで９０人を上限にしていたものを９５人まで学校で受け入れますよということで、３学級の学校については５枠、余裕を持って希望選択を受け入れられるという状況に増えてあります。","voiceIndex":28,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"すみません。私の理解が足りないのか。５枠、５人分が選択枠として用意されたのですよというニュアンスの答弁ですか。お願いします。","respondent":"勝亦学務課長","answer":"学校に入学できる、受け入れられる人数枠が９０人から９５人に増えたことになります。","voiceIndex":30,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問","question":"それで、３５人学級なので、３学級だと１０５人ということですか。でも、最終的には１０５人。単純に数字で言うと、９５人の設定をして、転入、選択を含めて、より入学しやすい仕組み、設定にしたのだけれども、最終的には数字で言うと１０５人まで受け入れることができるのですよということなのですか。","respondent":"勝亦学務課長","answer":"おっしゃるとおりで、最終的な新学期が始まる段階では、３５人掛ける３、１０５人がマックスの数字となります。","voiceIndex":32,"id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"もう一回いいですか。すみません。例えば、３５人掛ける３学級だったら、本当は１０５人入れる。ただ、先ほど申し上げたように、４月の転勤などで転入する方がいるから、その分は空けておかなければいけないのだよというルールの中でやるということが明記されていれば、僕はそのほうが分かりやすいし、個人的には地域に説明しやすいと思うのだけれども、教育委員会は何かそのような議論はありましたか。","respondent":"勝亦学務課長","answer":"そういった中で、受入枠の分かりにくい部分につきましては、今後、より分かりやすい方法を取りたいと考えますので、別途検討させていただければと思います。","voiceIndex":34,"id":"exchange-014"},{"speaker":"渡部委員","kind":"質問","question":"今の発言は、全く思いつきというか、前からの質問や地域のクレームも考えてみると、受入枠と書いておいて、受け入れてくれないではないかと確かに言われたことがある。やはりこれだけ人口も増えてきて、どうするかということで言わせてもらったので、今後検討していただければ、今年は今年で、報告事項だから動き出されていると思うので、また来年以降、ご検討いただければと思います。すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、先に、学区外の人を受け入れることはなかなか難しいですよということを示してもらえれば、保護者的には期待をしなくて済むので、選択ができると言われてしまうと、皆様、期待をして選択を求めてしまうので、この地域はなかなか難しいとか、今回、９校と出たように、過去はこれだけ受け入れることができませんでしたとかを示してもらったほうが。","respondent":"勝亦学務課長","answer":"そういった現状や過去の実績率といったものを、より分かりやすく、学校選択の中で周知してまいりたいと考えます。","voiceIndex":37,"id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"やはり期待を生んでしまうところもあるので、分かりやすい言葉で書いていただきたいなということは要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"}]},{"id":"topic-02","title":"の報告事項を改めて聴取いたします。 (2)警視庁との「児童虐待対応の連携強化に関する協定書」等の締結","agenda":"の報告事項を改めて聴取いたします。 (2)警視庁との「児童虐待対応の連携強化に関する協定書」等の締結","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"それで、連携を強化するものにしなくてはいけないと思います。どのような流れの中で出てきたのかということを少し確認したいことが１つ。それと、児童相談所はこれからつくるということなのですけれども、児童相談所では、警察との具体的な連携についての計画というのは、現状、どのようになっていたかということを少し確認させてください。","respondent":"染谷子ども家庭支援センター長、長谷川児童相談所移管担当課長","answer":"こちらは、令和６年１０月の児童相談所の開設を見据え、それに先立ち、子ども家庭支援センターと警視庁少年育成課において、協定を締結するというものであります。その時期に関しましては、今後、警察との協議になりますが、全国の状況を見ますと、開設のおよそ１０か月前に警察との意見交換をされておりますので、そういった事例を参考にしながら、品川区としても検討していきたいと考えております。","voiceIndex":48,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"中身についてもう少しお伺いします。「協定の内容」の(3)に協議会への参加の促進とあるのですけれども、現状は、警察署の協議会への参加状況はどのようになっているかということをお伺いしたいと思います。そこら辺についての考え方を伺いたいと思います。","respondent":"染谷子ども家庭支援センター長","answer":"今後、虐待予防・虐待の早期発見に資する児童虐待注意家庭と言われる、いわゆる警察が管理する情報を、先ほど、委員がおっしゃられた(2)の活用の中で、こちらから情報の照会を行ってまいりますので、そのタイミングで、より積極的に。","voiceIndex":51,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問","question":"そもそものところで伺いたいのですけれども、情報共有はどことどこがという具体的なところを教えていただけますか。","respondent":"染谷子ども家庭支援センター長","answer":"情報共有につきましては、私ども子ども家庭支援センターと警視庁少年育成課において、情報の共有をいたします。警視庁少年育成課につきましては、各管轄の警察署の指導をする立場になりますので、警視庁の少年育成課から各警察署に情報が行くという流れになっております。","voiceIndex":55,"id":"exchange-020"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"コロナの関係で、２２日に保育園や幼稚園における濃厚接触者の特定について等の厚生労働省通達が出されて、都知事も記者会見をしたのですけれども、その通達の内容や、区としての対応はどのようなものがあるのか、子どもや保護者への通知がどのようになるのかということを伺いたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-021"},{"speaker":"安藤委員","kind":"確認","question":"最後の確認。では、濃厚接触者の特定は、保育園、幼稚園についてはしないという取扱いにするということでよろしいのかということと、実際の保護者や子どもにはどのような通知になるのかというところをもう一回お伺いします。","respondent":"立木保育課長","answer":"濃厚接触者に関しましては、保健所が５日間に短縮するということを確認していますので、そちらは同じ対応ということになります。保育所、幼稚園における濃厚接触者の特定については行わないということになりました。これは、各園に通知を出しております。","voiceIndex":65,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"園に通知したということなのですけれども、やはり何らかの形で子どもや保護者に、そのような方針になったということはお知らせすべきなのではないかと思いますけれども、いかがでしょうか。","respondent":"立木保育課長","answer":"形を整えて、掲示等でのお知らせをさせていただきたいと思います。","voiceIndex":67,"id":"exchange-023"},{"speaker":"田中委員","kind":"確認","question":"グローバルキッズの報道については、私も品川区はどうなのかなと心配していたところだったので、その他ですけれども、報告があったのはよかったです。品川区は該当しなかったということだったのですけれども、豊島区の場合は、指導検査で不正に気づいた。品川区も、グローバルキッズに限らず、指導検査がしっかりされているのかというところを少し確認したい。確認をさせてください。","respondent":"立木保育課長","answer":"指導検査ということなので、保育課からお答えいたします。指導検査は、毎年、区でも認可、認証保育所に行っているところで、実施体制ですけれども、書類の確認、それから、実際に園へ訪問しての確認というところがあります。","voiceIndex":72,"id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"検査の体制なのですけれども、たしか、前もって保育園に連絡してからの検査だったと思うのです。今回は、品川区は該当しなかったということでよかったのですけれども、もし該当してしまった場合の報告の在り方として、これまでその他で報告されていたと思うのですが、きちんと報告事項に載せていただきたいなということを併せて要望したいのですが、いかがでしょうか。","respondent":"立木保育課長、中元保育支援課長","answer":"これは、それぞれやり方がありますので、使い分けといいますか、そういった形で、きちんとやっているところです。報告のところですが、こちらは東京都の権限で、東京都で検査をしていますので、少し前に認証保育所の職員再配置の場合も同じような形で、その他のところできちんとご報告をさせていただいているところです。","voiceIndex":74,"id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"検査の在り方。ですので、書類等の確認のための検査というものと、また別途、きちんと子どものための保育がされているかということを確認する、先に保育園に連絡をしないで立ち入る検査も、ぜひ品川区として、子どもを守る立場、子どもたちの環境を整える立場の品川区として実施していただきたいと強く求めたいと思いますが、いかがでしょうか。","respondent":"立木保育課長","answer":"きちんと突き合わせといいますか、経験を積んだ職員が行って見ておりますので、取り繕いがないかどうかということもきちんと見た上で対応しておりますので、今すぐにやり方を変えるということは考えておりません。","voiceIndex":77,"id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"書類等の確認というのはもちろんなのですけれども、実際に現場にいる保育士、そこにいる保育士の方たちは、一生懸命子どもたちのために保育を実施しているのですけれども、その配置に関してなど、やはり様々課題はあるので、前向きにというか、もっと踏み込んで、きちんと検査をしていただきたいなということを強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"３点伺いたいのです。保護者の不安、不信というものはあると思うのですけれども、不安払拭や、保護者への説明として、区は何をするつもりなのかをお伺いしたいのが１点です。なぜそのようなことが起こったのかということや、今後、どのようにして再発を防止しようかという考えがあるのかというのは、どのような説明があったのでしょうかということが２点目です。そこら辺を３つ目として伺いたいと思います。","respondent":"中元保育支援課長","answer":"あちらとしましても、社内で経営陣、対応者の責任を明確化して、懲戒、役員・監査の変更、人事異動が行われており、取締役２名が辞任、１名が月額報酬６か月自主返上、また、関与した従業員１９名の懲戒処分が実施されているなど。","voiceIndex":80,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"もちろん不正を起こしたのは、保育士不足などの事情もあったようですけれども、ぜひちゃんと保護者への説明が行われるよう、区として指導といいますか、それが区内の保育園ではないとはいえ、やはり自分が通っている保育園にそのような報道があったらすごく不安になると思うので、そこら辺は、ぜひ促していただきたい。声がけというか、指導をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"今、安藤委員が伝えてくれた、保護者への説明の部分なのですけれども、これは本当に実施をしてください。私はそのときに求めたと思うのですけれども、品川区としても、このようなことが起きてしまったという報告をホームページ上などで上げていただきたいと思うのです。今後、私立保育園を受け入れる際のチェックの在り方についても、何かあれば伺いたいと思うのですが、いかがでしょうか。","respondent":"中元保育支援課長","answer":"今後につきましても、名簿と実際にいる方の確認というところで、本社名簿はなかなかいただけないので、そこは東京都と連携しながら、何か情報があったときには、迅速に対応してまいりたいと思います。","voiceIndex":84,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"都のホームページで報告があるからといったご説明だったのですけれども、その都のホームページの報告がなかなか見つけづらい、分かりづらいところにあるので、品川区内の保育園の話でもあるので、ぜひ品川区としても報告を上げていただくようにしていただきたいと強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-031"},{"speaker":"渡部委員","kind":"質問","question":"保護者が不安にならないようにやるのも、園の仕組みの中で、園にやっていただくしかないと思います。ただ、大事なのは、私たちは区議会議員ですから、品川区の中の園ではそのようなことはなかったという事実はありますので、そこを含めた上で、その事業者へ、保護者には、くれぐれも事業者の責務で報告してくださいねというのは、伝えるようにお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-032"},{"speaker":"若林委員","kind":"確認","question":"報道と今のご説明の中で、今のご説明では一般検査や特別検査などで、報道では指導検査、先ほどは、口頭で抜き打ち検査ということになっている。正式な検査はどのようになっているのか。いま一度、誰の権限でやっているのかということを含めての確認。すみません。","respondent":"立木保育課長","answer":"指導検査の権限は、東京都、それから、区に、児童福祉法や子ども・子育て支援法に基づきまして、それぞれ権限があります。その項目に沿って、それぞれで行っているものです。","voiceIndex":89,"id":"exchange-033"},{"speaker":"若林委員","kind":"質問","question":"先ほどの豊島区のくだりで抜き打ち検査とあったのは、特別指導検査を豊島区の権限で行ったという認識でよろしいのですか。","respondent":"中元保育支援課長","answer":"あくまで豊島区の権限で、豊島区の判断で行われたものと伺っております。","voiceIndex":91,"id":"exchange-034"},{"speaker":"若林委員","kind":"意見","question":"今回、１発目の報道で、いわゆる水増しという見出しで出てきて、実態は保育士不足というところで、その報道見出しと実態の印象が違うなという部分があります。そうすると、グローバルキッズがどうのこうのではなくて、区全体として、民間保育園等での未然防止の観点というのは、何かおありになるのか。それだけ聞かせてください。","respondent":"中元保育支援課長","answer":"これは、大分過去の出来事で、平成２７年から平成３１年ぐらいまでであって、その後は、国のほうでも、今、保育士の家賃補助など、いろいろな補助メニューができてきてありますので、確かに保育士採用は依然厳しいと伺っておりますが。","voiceIndex":93,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5074#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":23416,"voices":97}},{"id":"r04-20220725-5","meetingId":"r04-cm07","date":"2022年7月25日","dateIso":"2022-07-25","committee":"総務委員会","time":"午後 １時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"ＫＤＤＩ通信障害による区への影響","agenda":"ＫＤＤＩ通信障害による区への影響","exchanges":[{"speaker":"西本委員","kind":"質問","question":"この通信障害によって、例えば区の、こういう通信回線を使ってのＳＮＳとか、あとは品川区の情報提供とか、何かそういうことで支障があるようだという区民からのクレームというか、お知らせというか、そういう報告はありましたか。全く関係なく大丈夫だったのでしょうか。","respondent":"古巻総務課長","answer":"区民の方がＫＤＤＩの回線を使っていると、携帯電話からのホームページの閲覧ができないとか、そういうことはあったかと思いますけれども、それに対して何かクレームがあったとか、そういうことは報告を受けておりません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"吉田委員","kind":"確認","question":"一つだけ確認を。聞き漏らしたのかもしれないのですけれども、最初に通信障害ということについての、いつ回復したというご報告は先ほど受けたと思うのですが、こういうことが起きたときには、ＫＤＤＩから、今こういう障害が起きているので、影響があるかもしれないとか、何かそういう報告というのはあるものなのでしょうか。あったのかということを、まず伺いたいのですが、いかがでしょうか。","respondent":"古巻総務課長","answer":"まもるっちに関しては、まもるっちの業者とのやり取りはあったようですけれども、一般的な話としての通信障害に関しての個別の対応は、なかったです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"吉田委員","kind":"質問・要望","question":"今回こういう通信障害ということで、多少の影響が出てしまった。こういうことは起きるのだということをある程度前提とした、特に児童見守りシステムについて、児童の安全に関わることですので、ぜひ検討していただきたいと思います。これは漠然とした意見ですので、意見としてとどめします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"そういうことに対して、今回こういう通信障害が起きたということは、先ほどほかの委員からも話が出ましたが、そういうことに備えておくということが重要なことだと思いますが、区としても、今後こういう障害が起きたことに対して何か対策というものは、検討がもう始まっているのでしょうか。それとも、まだ先のことだと思って構えているのでしょうか。私は早急な検討というのが必要ではないかと考えています。","respondent":"古巻総務課長","answer":"これは、具体的にはこういう対策をということで決めているわけではないですけれども、今後必要な対応について、様々な所管が連携を取りまして、情報推進課であったり、まもるっちの所管であったり、総務課だったりというところで連携を取りながら。","voiceIndex":11,"id":"exchange-004"},{"speaker":"湯澤委員","kind":"質問・要望","question":"まもるっちに関しましては、私も何人かの方に、今どうなっているのかと聞かれたりしたのですけれども、たしか区では、７月４日月曜日に学校側から保護者に対して、全部の保護者なのかどうか分からないのですが、こういうことがありましたという情報が第一報で来たと思うのですけれども、その頃には保護者の方たちもある程度、報道等で知っているという方たちがかなりあったのですが、今回、区の対応で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"湯澤委員","kind":"質問・要望","question":"今、２日とおっしゃったのですけれども、２日に連絡が来たというのはあまり聞いていなくて、逆に３日とかそのぐらいに、どうなっているのかという連絡を幾つかいただいたりして、もちろん、保護者の方がＫＤＤＩを使っているとか、そういうこともあったのかもしれないし、いろいろあるのかもしれないですけれども、こういった通信障害とかが起きたときには。","respondent":"宮澤情報推進課長","answer":"土曜日、日曜日を含めまして、障害発生時の今後の対応につきましては、聞いたところではＫＤＤＩを使っている職員も、職員間で連絡がつかなかったところもありますけれども、代替手段等も考えながら、引き続き、迅速な対応ができるような形で体制を構築しているというところで。","voiceIndex":16,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうことになった場合、どのようにして機能を代替していくかとか、それをどう区民に知らせるかとか、今回約３,９００万回線ということですから、かなりの国民に影響を与えたことだったのですけれども、そういうところとしては、今回のような事件・事故が起こったときには、どう対応するのかというところでの対策というのは、考えられている部分があるのか。","respondent":"宮澤情報推進課長","answer":"例えば住民情報システム等になりますと、一般の携帯電話のような通信回線ではなく、ビジネス向けの有線回線でつないでおりまして、さらに、 １線に障害が起きても通信ができるように、複数回線で冗長化しているという対応は既にしております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう複数化などという対応を様々つくられているということなのですけれども、今回のＫＤＤＩのこれだけの事故を起こしたということを受けて、さらに区として、どういう対応を検討することが必要なのかということで、見えた課題に対してどう検討するのかということがありましたら、その点についても伺えたらと思います。","respondent":"宮澤情報推進課長","answer":"今回のような通信障害が起きて、いわゆるＩＣＴ機器、通信を必要とするＩＣＴ機器というのは、洗い出しというのを行っております。その中で、どういった冗長化ができるのかというのは検討になりますがなかなか、通信の復旧を待つしかないというところもあるというのが実情です。","voiceIndex":20,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今回は、まさかこういう事故が起こるというのは想定もしていなかったところで、どれだけ大変な状況になるのかというのを経験したという状況だったのですけれども、実際に起こったわけなので、そういうことは起こり得るということで、改めて課題を洗い出しながら、対応できるところはぜひ対応していただくということで、区としてもご検討いただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-009"}]},{"id":"topic-02","title":"こみゅにてぃぷらざ八潮空調設備改修工事請負契約","agenda":"こみゅにてぃぷらざ八潮空調設備改修工事請負契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、老朽化での改修工事ということですが、老朽化というのは通常どれくらいで空調の改修がされるという基準などがあるのであれば、それを教えていただきたいのと、このこみゅにてぃぷらざ八潮では何年くらい経っているのかということも教えていただきたいと思います。","respondent":"小林施設整備課長","answer":"３つのご質問かと思います。老朽化ということで、どの程度こういった機械が使用できるかという観点ですが、空調機ですと、通常１５年から２０年ぐらいがおおよそ更新する目安の時期かなと考えています。","voiceIndex":28,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"教えてほしいのですが、入札状況調書の１番目と５番目を見ると、１,０００万円ぐらい違いがあるのです。恐らく積算の仕方はいろいろあるのですけれども、どこまで区は見ることができるのでしょうか。それが全くないわけではないと思うのですけれども、その数値があって、この金額で出てきているということと、詳細というか、内訳というか、そういうことは分かるのですか。","respondent":"東野経理課長","answer":"入札の際の金額につきましては、内訳まで求めているものではございませんので、内訳まで全社把握するということはしてございません。契約した事業者につきましては、契約書に添付する必要がありますので、内訳書等をつけていただいてあります。","voiceIndex":31,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"内訳書というのは、決まってからですか。１番から５番のところの内訳は出ているのですか。それとも、落札したところだけになるのか。","respondent":"東野経理課長","answer":"内訳を頂いているのは、落札した事業者のみとなります。","voiceIndex":33,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"この差がどこで出てきているのかなというのが単純に不思議なのです。多分、こちらが提示するときは、ある程度の積算を定めているのではないか。それはないのですか。何を言いたいかというと、１,０００万円が大きいか小さいかということになるのですが、ただ、内訳の中で、資材だったら、入手するときは大体似たような形ではないですか。その辺はどのように認識されるのか。","respondent":"東野経理課長","answer":"こちらの工事の入札に当たりましては、所管課からの起工額を基に、予定価格を事前公表しています。今回でいきますと、３ページの右上のところに書いた金額となりますので、そちらの金額につきましては、あくまでも起工、つまり区側で算出した額です。","voiceIndex":35,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"すみません、しつこいのですけれども、内訳はどうなのかということなのです。それで落札したところが内訳をきちんと添付するということだと思うのです。先ほどのはそういうお話だったと思うのです。そうすると、積算値はある程度、区のほうが分かっていて、それを照合して、大体似通っていればいいと思うのです。だけれども、積算の内訳を提示していないわけです。仕組み的に教えてほしいのですが。","respondent":"東野経理課長","answer":"内訳というものにつきましては、必要なものにつきましては出していただいております。というのは、落札した業者から入手しているものでございまして、あくまでも事業者全社から取っているものではないということでご理解いただきたいと思います。","voiceIndex":37,"id":"exchange-014"}]},{"id":"topic-03","title":"冒頭に申し上げましたとおり、取り上げる順番を変更し、(4)伊藤学園教室等照明ＬＥＤ化工事請負契約","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更し、(4)伊藤学園教室等照明ＬＥＤ化工事請負契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回は伊藤学園のＬＥＤ化ということなのですけれども、学校のＬＥＤ化というのはどのように進めていくという計画みたいなものができているのでしょうか。そしてまた、どれぐらいの学校でＬＥＤ化が進んでいるのかを伺いたいのと、それから、ＬＥＤ化することによって省エネ効果がかなりあると思うのですけれども、これはどの程度になるのか、その点についても伺いたいと思います。","respondent":"小林施設整備課長","answer":"それと、省エネ効果ですが、もちろん、建物の規模とか用途とかでも随分変わってくるところがありますが、学校ぐらいの大きな施設になりますと、通常の蛍光灯とかの施設に比べますと、おおよそ４０％の削減効果が見込まれていると認識しています。","voiceIndex":43,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"（１０ページの入札状況調書に）「未満」と書いてあるのですけれども、この説明をお願いしていいですか。","respondent":"東野経理課長","answer":"１０ページの入札金額欄の、「未満」というところのご説明ということで、説明します。こちらにつきましては、番号３の三英電業株式会社が最低制限価格未満で応札をしまして、落札することができませんでしたので、「未満」という形での表記をしています。","voiceIndex":46,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"基本的なことだと思うのですが、最低制限価格ということ、それも提示されているということですか。提示されないでということですか。なぜこういうことが起きるのかなというのがとても不思議なのですけれども、考えられる要因は何でしょうか。","respondent":"東野経理課長","answer":"区では、工事請負契約におきます最低制限価格設定基準というのを設けておりまして、１件ごとに決めてあります。こちらの最低制限価格に満たなかったということで、３番目の業者につきましては、落札ができなかったという状況です。","voiceIndex":48,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"（最低制限価格は）公表されているわけですよね。そうしたら、公表されていて、積算して、その数値が出てきたときに、これはどういうことですか。なぜそこに上がってくるのかなというのが、すごく不思議なのですけれども、最低ラインを示しているのであれば、事業者のほうで、それに引っかかってしまったら出しても駄目だということになるわけでしょう。なぜこれを出してくるのですか。","respondent":"東野経理課長","answer":"入札の公告の際に、最低制限価格を設けるとしておりますが、金額については提示してございません。最低制限価格につきましては、先ほどの設定基準でいきますと、予定価格の１０分の７.５から１０分の９.２までの範囲で定めております。","voiceIndex":50,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"とても不思議なのですけれども、制限を、計算値をある程度示すわけではないですか。最低ラインを設けますよと。例えば人件費を削っているのか、材料費を削っているのか。この辺の会社というのは、長くお付き合いしている会社でもあるので、その辺の信頼性を含め、どうなのでしょうか。そういうことに非常に疑問を持つのですが、いかがでしょうか。","respondent":"東野経理課長","answer":"今回の入札に関しましては、落札した業者が、予定価格からいきますと８１％、それから、「未満」の表示がある会社につきましては、８０.４％というところで、最低制限価格の設定ラインを僅かに下回っているですので。","voiceIndex":52,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"僅かな差なので、たまたまこうなったということかもしれません。ただ、事業所の特徴なども、そういうもので見られることもあるのではないかと思っているので、できることならば、内訳を含めた形での落札金額というのを提示していただいたほうがいいのではないかと私は思いますけれども、これは可能かどうか分からないので、意見としては容れておいていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-020"},{"speaker":"須貝委員","kind":"意見","question":"考え方なのでしょうけれども、今回ダンピング防止ということで、西本委員からもありましたが、これを見ると、入札の競争化がうまくいっているように見えるかなと思うのですが、未満というのはなかなか珍しいことで、でも、この会社はもちろん施工工事のプロだし、見積金額の算出もプロです。急にできた会社ではないので。企業の努力というのも、私はあると思います。意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-021"}]},{"id":"topic-04","title":"（仮称）旗の台六丁目公園整備工事請負契約","agenda":"（仮称）旗の台六丁目公園整備工事請負契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回のは公園整備の工事の契約ということなのですけれども、これまで公園のなかった丁目に公園が新たにできるというのは本当に歓迎すべきことで、ぜひこういうことをどんどん広げていっていただきたいとかねがね思っていましたので、こういうものができることは本当に大歓迎です。それは多分、全額区の財源ということになるのかなと思うのですけれども、そこの前提のところを教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"違ったら違うと言っていただきたいのですけれども、こういう形で区に売却した場合のメリットなどはどんなものがあるのか、また税金の減免などの制度がどうなっているのか、分かる範囲で教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"それだけ言っておきます。防火水槽はありますけれども、防災倉庫もここにありますが、備蓄性とかを考えたら、もっと大きな建屋にして、その地域はその地域できちんと守ってくださいというような、将来その地域の人にメリットになるようなことを考えた改修計画を立てるべきだと思うのですが、その辺について、そういうことは課題として、話合いとして出たのでしょうか。教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"一つだけ。今回、旗の台六丁目が公園整備できるということで、私は非常にいいことだと考えています。ただ、お隣の小山洗足町会などは、まだ一つもそういう場所がありません。そういうことも企画部としても、将来その地域に１か所ぐらいは公園整備、そして防災整備ができるようなところを、何とか土地区画を購入して、用意してあげていただきたいと私は思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"今回の公園整備工事で、８ページを見ると、主な工種ということで、これだけのものが代表的に挙げられているのですけれども、工事の範囲というのが、下の図を見ると、例えば防災井戸とか、さっき防災倉庫のこともありましたけれども、幼児用すべり台もすべり台だけなのか、下の部分もなのか、植栽も全部なのか。すみません、基本的なことですが、教えてください。","respondent":"東野経理課長","answer":"これも分かる範囲でお答えしたいと思います。今この改修計画図の案に出ている植栽等も含めた公園の計画整備につきまして、全部こちらの金額で行うものです。","voiceIndex":72,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"そうしますと、ダスト舗装というのがどういうものなのか。すべり台は幼児用のすべり台なので、その辺とか、健康遊具の下なども同じダスト舗装というものなのか。これだけの金額で、この辺のことが全部行われるのか、工事の内容について教えていただきたいのですが、ダスト舗装というのはどういう舗装なのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"この経緯をもう少し教えていただきたいのです。地域の区民の方から「あそこは空き地があるみたい」という話があって、区に要望があって、所管課がいいねということで所管課が決めて、今、契約案件ということで来ているという認識でよろしいのでしょうか。そこの流れをもう一度教えてもらえますか。どこがスタートなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"それはすごく要望が強いわけです。公園も防災上も含めて。もしもそこが空いていなくても、将来的に欲しいという話は当然ながらできるわけであって、そういうことが計画的にやれるものだったらやって、防災上も計画的に取得して、そういう土地も取得して防災公園とかを造るというのも、一つの柱になるのではないかと思うのですが、そういう形になっているのですか、なっていないのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"なかなか質問しづらいので、意見です。要望はたくさんいただいております。空き地がない、公園がないという要望が来ておりますので、でも、そうはいっても空き地がないと、それは買えないわけです。ですので、そこのアンテナの張り方というのをしっかりやっていただきたいなというのを、要望だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-030"},{"speaker":"湯澤委員","kind":"質問","question":"少し細かいことかもしれないのですが、近隣の方たちは、そういうところもかなり気にされると思うので、契約内容にそういったことも、車の停め方一つも入っているのか、入っていないとしても、近隣への配慮というのはかなり必要かと思うのですけれども、その辺はどうなっているのかだけ教えていただければと思います。","respondent":"東野経理課長","answer":"細かい工事の施工、運用につきましては、全部を捉えているものではございませんが、こういった近隣への配慮につきましては、工事の契約の中に十分考えられていると思いますので、委員からお話があったことにつきましても、私からも所管課にお伝えさせていただければと思います。","voiceIndex":90,"id":"exchange-031"}]},{"id":"topic-05","title":"令和４年７月１０日執行 参議院議員選挙の結果","agenda":"令和４年７月１０日執行 参議院議員選挙の結果","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"地域の方から、コロナに感染した方が投票できないことについてご相談をいただいたのですけれども、選挙管理委員会事務局に聞いたら、コロナ特例ということで、たしか６日までに申請をすれば、郵送で投票できる仕組みがあるということで伺ったのですけれども、私が相談を受けたのが６日の夜で、その方は５日に感染が判明したのですけれども、６日の夜に私のところに相談があって。","respondent":"鈴木選挙管理委員会事務局長","answer":"１点目の、コロナの感染者の方関係の対応ですが、一つは、濃厚接触者のお話をされていましたが、濃厚接触者と患者は取扱いが異なります。制度としての特例郵便等投票が利用できるのは、患者の方ご本人になります。","voiceIndex":96,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この方は５日に感染が分かったので、すぐに対応すれば６日に投票できたにもかかわらず、このように分からないままで、コロナというのはそれにかかったことそのものが大変なので、その対応に追われるということもあると思うので、コロナの方には必ず区が関わるということになっていくわけですから、そこのところでお知らせをするという、それで投票する・しないは本人ですけれども。","respondent":"鈴木選挙管理委員会事務局長","answer":"区でも、どの選挙でも、そういう病院の担当者の方に集まっていただいて、不在者投票の手続きについてご説明をして、できるだけ多くの方に投票していただくような調整はしているところです。","voiceIndex":98,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"病院としても５日ぐらいで締め切ってしまって、その後入院してきた人には「もう締め切ってしまったのでできません」と言われたのです。それから、特別養護老人ホームや有料老人ホームや介護老人保健施設などでは、障害者の認証施設も含めて、全ての施設でそういう取組はされているのか、全てでなければ何％ぐらいまでいっているのか、何か所中何か所ということが分かったら、それも教えてください。","respondent":"鈴木選挙管理委員会事務局長","answer":"入院中の不在者投票ですが、ご質問、ご要望にもありましたように、対象となる指定施設については、必ず選挙の前に説明会にお集まりいただきまして、その中で、病院の効率的な事務の執行上、特定の日を設定して投票していただくのは結構ですが。","voiceIndex":100,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"一斉の投票の日にちを過ぎても対応してくださいということでのご説明をしていただいているということを伺って、すごくよかったなと思います。そういうことで、今度は病院にも、ぜひ選挙管理委員会としても、そういうことだということを踏まえた上でお願いすることができると思いました。しかもその経費を選挙管理委員会で持つということであれば、そういうことができるということでよかったなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-035"},{"speaker":"吉田委員","kind":"提案","question":"どのような説明をされたのか、伺いたいと思います。あの人、何をやっているのだろう」みたいな感じで見られて、それに対する説明もできないわけですから、その辺の配慮について、説明会の中ではどのようにされているのか、伺いたいと思います。ここにも書いてあるとおり、筆談用の紙とペンがそこにあったら、ボードがなくても、こんなトラブルにはならなかったかと思うのですが、その辺はいかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"それと、申し訳ありません、職員もそういう支援が必要な方の対応に慣れている者ばかりではないので、何か合図といいますか、そういうサポートが必要だということが分かるようなところは、少し気をつけるようにということで、障害者支援課長からもヒントをいただいて。","voiceIndex":103,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"一つ、ご本人からの要望なのですけれども、手話言語条例が成立して、大変喜んで評価してくださっているのですが、例えばこういう選挙に行くときに、普通私たちも、「ご苦労さまです」とか「お疲れさまです」とか、投票立会人の方とかが簡単にご挨拶してくださるのですけれども、そのときに、「お疲れさまでした」とか「ありがとうございました」というすごく簡単な手話からでいいから。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご指摘のとおり、支援の必要な方への対応というのは、選挙だとか所管に関係なく必要なものですので、障害者支援課だとか関係課と調整しながら、できる限りしっかりとした対応で、投票所でもしっかりと対応ができるように調整したいと思います。","voiceIndex":105,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"高齢の方で、ご自分で行けない方は、家族とか知人とかが車で投票所まで連れていくということがあると思うのですけれども、そういう場合に、駐車場のある期日前投票所というのが何か所ぐらいあるのか。そういうことも、どこに何台ぐらいの駐車場がありますよという案内があると、ありがたいかなと思ったのですけれども、駐車場のある期日前投票所が何か所ぐらいあるのか、教えていただきたい。","respondent":"鈴木選挙管理委員会事務局長","answer":"それ以外は、地域センターですので、基本的には地域の方が訪れる区の施設ということで、一般的な駐車場はない施設ですので、期日前投票で使うときも駐車場はないので、公共交通機関のご利用をお願いするという表示をしています。","voiceIndex":108,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"地域センターによっては、２台ぐらいは停められるような駐車場があるところもあるので、そういうところを使いながら、皆さんが行かれたりしているのですけれども、基本的に車で連れていく場合は本庁舎に来るようにというのが、選挙管理委員会としては原則という考え方ということでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご指摘のとおり、地域センターにも庁有車用の駐車をするスペースは、一、二台分はありますけれども、地域センターで「車で来られます」と案内してしまうと、絶対にパンクするのは目に見えているので、基本的には、お車で来る必要がある方は、申し訳ありませんが。","voiceIndex":110,"id":"exchange-039"}]},{"id":"topic-06","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今、これだけ感染爆発という状況で、（新規感染者が）３万人を超えるような、これがさらに４万人、５万人となることが懸念されている中で、８月の３０日、３１日というところでは、まだコロナが収まっていないというのが懸念されると思うのです。そんな中で、今回は私は中止にせざるを得ないのではないかという思いがしているのですが、その辺りのことはいかがでしょうか。","respondent":"鈴木（真）委員長","answer":"まだ決めていません。この後お話をしようと思ったのですが、コロナの状況によっては、実施の中止もあり得ますということは考えております。ただ、まだ今の段階では、議長とも打合せをしておりません。","voiceIndex":114,"id":"exchange-040"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"いいですか。すみません。今、迷いながら、質問をどうしようかと思って、これは８月３０日または３１日、いずれか１日で、両方回るというのではなくて、どちらか一つに絞ってということですか。","respondent":"鈴木（真）委員長","answer":"名古屋市のほうはどちらでも大丈夫だということです。多分、３０日の日に、品川駅を出て先に静岡市へ行って、静岡市役所で午前中視察して、午後から名古屋市に向かうということで、話を進めています。","voiceIndex":120,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2240#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":32649,"voices":123}},{"id":"r04-20220726-14","meetingId":"r04-cm07","date":"2022年7月26日","dateIso":"2022-07-26","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時５６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これまでも、私たち共産党は、区の重要な施策や方針について、素案の段階、パブリックコメントをするにあたって説明会を行うようにずっと求め続けてきたのですけれども、ほとんど品川区は説明会をやらないということで来たと思うのですが、今回、こういう形で説明会をやっていただくことになって本当によかったと思っているのですけれども、今回説明会を行うことになった経過と理由について、まず。","respondent":"山下新庁舎整備課長","answer":"今回、新庁舎整備課として新たに課として設置され、今回、基本計画の策定という流れの中で、説明会の実施ということで準備を進めてまいりまして、ここまで感染が広がるというところを想定しておったわけではその時点ではなかったのですけれども、今の現状としては。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私たちも、ほかの会派の皆さんもそうだと思うのですが、障害者団体の方々とこの間、懇談を行ってきまして、障害者の皆さんが、それぞれの団体の方々がそれぞれに庁舎に対しての思い、本当に庁舎ができるのであれば、こういう要望をぜひとも受け入れていただきたいという思いが様々あるのだということを私たちも伺ってきましたので、そういうところでは、ぜひこの間も申し上げてきたところですけれども。","respondent":"山下新庁舎整備課長","answer":"障害者団体含めまして、今回、パブリックコメントということで実施をしてまいりますので、いただいたご意見の反映というところは、もちろんその全てを受け止め切れるかどうかというのは、いろいろなご意見の内容等々にもよるところがあろうかと思いますけれども。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者の団体の皆さんにも、できれば説明会のご案内をしていただきたいと。障害者団体の皆さんだけではないかもしれないですけれども、そういうところで庁舎の建設に当たって、様々、区民の皆さんのご意見をどうやったら聞けるかという形で説明会の周知をしていただきたいと思っていますが、その点についての周知の方法についてどう考えられているのか伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"今回、かなり回数を細かく実施していく予定ですので、都度都度、この地区のこの場所でというところは、ＳＮＳ等を活用して随時の発信に努めてまいりたいと考えております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前回の行革委員会で私が質問したときに、ワンフロアの面積はどれぐらいになるのかと伺ったときに、２,５００m2ということでご回答があったと思うのですけれども、８,３００m2の敷地にワンフロアが２,５００m2にしかならないのかと思ったのですが、そういうことでいいのかの確認と、８,３００m2の敷地になぜワンフロアが２,５００m2ぐらいになってしまうのか。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"各町会等に配布予定のチラシにつきましては、いわゆる回覧板で回したときに、見たというサインといいますか、チェックができるような用意を考えておりまして、一応、回覧をしていただけると、こちらとしては考えてあります。こちらの建蔽率等々につきましては、こちら、都市計画決定を今後かけていきますので、その都市計画によって変わってくるものになりますので、現時点で建蔽率、容積率は幾つですという形でお答えすることは難しいところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ありがとうございました。そこには新たに保健センターの一部機能を新庁舎に集約ということで書かれているのですけれども、前にもどこかでご答弁があったかもしれないですが、これは大井保健センターを新庁舎に入れるということで確認させていただいていいかどうか、伺いたいのが１点です。そこら辺の全体的な機能の移転というのですか、そこら辺がよく分からないので、教えていただけたらと思います。","respondent":"大友新庁舎建設担当課長","answer":"新庁舎に新たに入る機能があるのかというところにつきましては、その次の質問の第二庁舎のところにもつながってくるのですけれども、第二庁舎、本庁舎、あと、第三庁舎、議会棟全て含めて考えて、再編をしていくということで、第二庁舎は残すので。","voiceIndex":16,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、６万m2になるというのは、第二庁舎は除いての６万m2ですよね。もちろん今度新庁舎だけで６万m2になると思うのですけれども、それプラス、第二庁舎は第二庁舎で、それ以外のところで行政機能として活用するということになるのでしょうか。そこら辺のところはいかがでしょうか。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"第二庁舎は第二庁舎であって、それ以外で６万m2という考え方になります。新たに入る機能というところにつきましては、現状、保健センターという形になると考えております。庁外に所在する施設の受入れ等々も含めまして、第二庁舎の活用については、今後、多角的に検討を進めてまいります。","voiceIndex":18,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"それで、それも踏まえて４万６,０００m2だったのが、今度は新庁舎で６万m2になるということで、それに加えて第二庁舎の１万２,０００m2が加わると、７万２,０００m2のボリュームになるということで考えていいのでしょうか。その確認だけさせていただいて、一旦終わります。","respondent":"大友新庁舎建設担当課長","answer":"おおよその考えは今の考え方で大丈夫かと思うのですけれども、第二庁舎につきましては、第二庁舎と、今現在の本庁舎の間に都市計画上の道路が走ることになります。","voiceIndex":22,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こうやって数えていくと、１０階建てぐらいなのかなみたいな感じの階高の図にしかなかなか見えないのですが、でも、６万m2という計算ができているわけですから、多分、何階建てというのはおおよそ決まったのではないかと思うのですが、そこのところは、これまでは１８階から２０階建てぐらいになるかということでのご答弁だったと思うのですが、これが何階建てになるのかということと。","respondent":"大友新庁舎建設担当課長","answer":"新庁舎におきましては、まだ現段階で何階建てというのは明確に決まっているところではありません。こちら、コア配置などの必要面積などが算定されてから実際の階高とかが決定する形になりますので、現状、１５階から２０階という形の想定は変わっておりません。","voiceIndex":27,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、何階建てというものが決まるのはいつぐらいになるのでしょうかということをお聞かせいただけたらと思います。前回のご答弁では、低層階というのはたしか六、七階ぐらいだったと思うのですけれども、なかなかイメージを持てないので、最終的には都市計画決定されたところでここのところも決まると考えていいのでしょうか。その点についても伺いたいと思います。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"先ほど委員から、議会につきましてツーフロアというご発言があったかと思うのですけれども、特に議会にツーフロアというところも、そこは決め切れているところではございませんで、イメージとしてこのような形でお示しをしていますが。およそ階高が決まるスケジュールにつきましては、素案の要約版１０ページに、事業スケジュール、下段に載っているかと思いますが、基本設計段階になる予定です。","voiceIndex":29,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"まだまだ具体的なところは、イメージできるところまで決まっていないということです。最後にもう１点伺いたいのは、この庁舎の検討は、検討経過というのもここの中にも随分書かれて、素案の中にも書かれているのですけれども、これは議会に対しての報告というあたりから書かれていますけれども、その前に、品川区としてはＪＲとともに様々検討されてきた経緯があると思います。","respondent":"榎本新庁舎整備担当部長","answer":"大分前の話になりますけれども、平成２９年度に区議会の行財政改革特別委員会が設置されまして、まず、現庁舎の今の老朽具合というか、今後どれぐらいの改修とかが見込まれるのかというところから始まりまして、平成２９年度だと思いますけれども、今ある区有地。","voiceIndex":32,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"とにかく何ページから何ページまでは非公開、何ページから何ページまでは非公開、ほとんどの部分が非公開で、１ページとか２ページとかは公開されているのですけれども、公開されているところもほとんど黒塗りという状況での情報公開の実態だったのです。これ、庁舎の問題なので、公開というのはぜひしていただきたいと思うのですけれども、その点についても伺いたいと思います。","respondent":"榎本新庁舎整備担当部長","answer":"ただし、いろいろな再開発計画の中で、多角的に多分検討を行っていまして、架空の部分というか、いろいろな幅で検討した中で、それが外に出ることで後々支障が出るものについては出せないというのは、いろいろな開発計画の中であり得ることなので。","voiceIndex":34,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これそのものも税金が使われて、業務委託をされて検討されてきた中身ですし、これそのものが基本計画案の検討業務の委託という中身になっておりますので、私はぜひこれは当然公開をしていただきたいということで、改めて強く求めておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これから当然、基本設計をやった後に発注をかけていくのですけれども、あのときどんな業者がこれをやるのですかという質問をさせていただいたかと思うのですが、もう一度確認をさせていただきたいということが１点です。","respondent":"大友新庁舎建設担当課長","answer":"我々が求めているところといたしましては、我々として、設計の段階での検討であったり、工事発注の方式の検討であったり、工程管理、また、コスト管理など、各種のマネジメント的な部分を担っていただきたいということで、そのマネジメントを担うにあたって。","voiceIndex":38,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問・要望","question":"前に質問したこととご答弁は変わらないですが、しようがないとは思うのですけれども、１点目のコンストラクション・マネジメントですが、不勉強のところもあって、その後いろいろなところと業者とかともお話ししたのですが、一番心配なのは、やはり一つ、発注者である区役所と、いわゆるゼネコン、その下請であるジョイントベンチャーの会社。","respondent":"大友新庁舎建設担当課長","answer":"実際に業者を選定する、うまくいかなかったときのデメリットなども把握はしていますけれども、業者選びの段階で、我々の目的を達することができるような業者選定をしていきたいと考えております。","voiceIndex":40,"id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6134#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":17681,"voices":44}},{"id":"r04-20220727-19","meetingId":"r04-cm07","date":"2022年7月27日","dateIso":"2022-07-27","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今もご説明がありました防災ラジオのあっせん販売受付が６月１日から始まっているということですけれども、売行きといいますか、普及状況がどうなっているのかをお伺いしたいと思います。確かにそのように伺ってみれば、そういうものだと思うのですけれども、そういう想定をなさっているのか。その点をお伺いしておかなければいけないかと思ったのですが、いかがでしょうか。","respondent":"平原防災課長","answer":"それにつきましても、資料でご説明させていただきました様々な媒体以外にも、例えば、これは旧来の手法になりますが、開設した避難所での掲示板を活用した手法であるとか、そういったところも様々活用してまいりたいと思ってあります。そういったことを想定しています。","voiceIndex":6,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"ですから、そういう身近な生活情報を伝えていくということは本当に求められているし、必要だし、かつ、そういう心理的な結果も導いているということで、一般的に頭の中で考えている以上に必要だということで、本当にしっかり想定しなければいけないし、そのための準備を今から整えておかなければいけないということで、ぜひとも想定し、準備し、また。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"そうであったら、防災ラジオが必要ということとかも伝えなければいけないのかと思うのですけれども、実際、防災行政無線が聞ける状況にあるかどうかの確認をさせてください。そして、関係機関による災害広報活動の中で、デマ等の打ち消し情報というところがあるのですけれども、とても必要なことだと思うのですが、現状の体制がどのようになっているのかというところを確認させてください。","respondent":"吉岡防災体制整備担当課長、平原防災課長","answer":"粉ミルクについてなのですけれども、こちら、従来からアレルギー対応を含むものでずっと備蓄をしてきたところなのですけれども、液体ミルクにつきましては、やはり断水時。区外の方につきましても同様となっておりますが、例えば、区外にいらっしゃる方に品川区の情報とか、そういったものについては、品川区からの発信はなかなか難しいところなのですが、どこにいらっしゃっても。","voiceIndex":10,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"それぞれありがとうございました。防災行政無線のところで、現時点で超高層建築物に住む方たちには、この防災行政無線は聞こえているのかどうかという部分について確認をしたかったので、すみません、私の質問の仕方が悪くて。もし分かればお知らせください。粉ミルクのところについては、これから別紙のところに液体ミルクも加わるということでよろしいでしょうか。","respondent":"平原防災課長、吉岡防災体制整備担当課長","answer":"それともう１点、観光客等々の帰宅困難者に対してですが、先ほど私、事例といたしまして、避難する場所の話をさせていただきましたが、当然、その中には、物資の場所であるとか。地域防災計画には、いろいろな物資のところ、まだ書き切れていない部分もありますし、近年、非常に備蓄物資の質の拡充に努めてまいったところですので、書き方については全体的に検討させていただきまして。","voiceIndex":13,"id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。保存期間が短いということで、リサイクルの利活用のところが課題であったところが、解決ができて保存できるようになったと伺っておりますが、品川区で保管をしてから、この活用が始まっているのかどうかというところを一つ確認をさせていただきたいと思います。災害が起きているのか。強化をしていただきたいということをお願いをしますし、また、見解を伺いたいと思います。","respondent":"吉岡防災体制整備担当課長、平原防災課長","answer":"在宅避難の方へのこういった備蓄物資の重要性、そういったものにつきましては、今までも防災ハンドブックでの周知ですとか、あとはローリングストックの重要性、そういったものをご説明させていただいたところですが、今。それと、障害者への情報発信ですけれども、こちらにつきましては、障害種別に応じた形での情報、様々なものがあるかと思いますので、まずは区の現状をしっかりとお伝えして、どういう情報が取れるのか取れないのか。","voiceIndex":19,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"ご説明ありがとうございました。別紙１の資料６－６に物資の支援のことが載っていまして、発災後３日までは、区と都が対応し、４日目以降は、国と自治体から被災者に提供と。そのような準備や体制は整っているのか、その点をまず伺いたいと思います。なぜならば、現状では様々ご努力が進められていると思います。この点、伺いたいと思います。現状をそれぞれお伺いしたいと思います。","respondent":"吉岡防災体制整備担当課長","answer":"地域防災計画の内容もそうなのですけれども、こういったコロナ禍を踏まえて、また地域防災計画の記載内容ですとか取組方法については、今後検討していきたいと思います。","voiceIndex":23,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"今の答弁も、例えば、１日目、二、三日目、４日目以上のスケジュールで可能なのかと伺ったのですけれども、備蓄品は想定で見ると１２万プラスアルファあるという話でしたが、それが実際、このスケジュールで進むと思っているのかと伺ったので、その点伺いたいと思います。それができる体制であるのかないのか。そこはやはり示していかないと、計画が進まないと思うのですけれども、改めていかがでしょうか。","respondent":"吉岡防災体制整備担当課長","answer":"スケジュールのところを申し上げましても、当然、何か想定外の事態が起きるというところはあるかもしれませんが、このスケジュールのところで提供できると考えているところです。","voiceIndex":25,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"区の認識も伺いたいと思いますけれども、これではやはり最低限必要な水や食糧やトイレの確保や、夏の冷房、冬の暖房、プライベートの確保、生命維持に必要な環境すら確保ができないと私は思います。これは意見です。現状ではまだ計画ができていないということでよいのか、伺いたいと思います。やはり直ちに計画を立てて、訓練を通じて実践的に動けるような取組が必要だと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"避難所の体制というお話でございましたので、私からお答えします。","voiceIndex":27,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"毎年水害の際にも、昨年も豪雨災害の際に、品川区でもいろいろ対応しましたけれども、やはり学校が避難所というイメージがすごく強いですから、直接帰宅されている方とかが学校に行って、ここは中に入れないとかという問合せが学校にあって、今開いているのはこことここですみたいな、そういう対応が昨年の夏もありましたけれども、そういう意味では、やはり避難所運営の開設、受入れ。","respondent":"吉岡防災体制整備担当課長","answer":"そういったところでしっかりと物資を届けて、取りに来ていただくというところなのですけれども、具体的な計画というところになりますと、例えば、配慮が必要な方、こういった方たちには、こういった避難所に来てくださいというところも言えない部分もあるかと思いますので。","voiceIndex":29,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろ進めるための計画があるのは知っているのですけれども、やはり必要に応じた規模とテンポを強く求めたいと思います。団体とも関係をつくっていくというご答弁がありましたけれども、ぜひ具体的にまずは障害者の団体の方には現状をしっかりと説明をしていただきたいというので１点伺いたいと思うのと、障害の方は大勢いらっしゃいますので、全体で、障害区別に分けても構いません。","respondent":"平原防災課長","answer":"そのような中で、障害者の方につきましては、どういう方々とのお話合いというのは、私どもでもまだきちんと勉強できているわけではございませんけれども、そういった様々なところで私どもも逆に意見をお聞きするというところを進めていきたいと考えていますので。","voiceIndex":31,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"東日本大震災から１１年たって、まだ特に障害がある方がない方に比べて２倍以上の死亡、命を落とす、そういう実態が繰り返し報道されているわけですから、ぜひ障害者団体、障害がある方へのまずは現状の説明をしていただいて、また、課題やご意見も伺って、具体的に進めるよう強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"6)のところの防災ラジオは、恐らく以前のというか、旧防災ラジオの説明だと思うのですけれども、防災行政無線からの情報が自動起動してとなっていますが、新しい防災ラジオの場合には、防災行政無線となかなか連動はされていないのかと思うのですが、これは物理的にそういうものというか、致し方ないということの理解でよろしいのでしょうか。","respondent":"平原防災課長","answer":"新しい防災ラジオをお持ちの方は、恐らく今お持ちの防災ラジオと何ら変わることのない形で、これまでの防災ラジオはラジオをつけていなくても、突如、防災行政無線の放送が入ってくる形になるのですけれども、新しい防災ラジオは、一瞬ＦＭしながわの放送が入って。","voiceIndex":35,"id":"exchange-012"},{"speaker":"たけうち委員","kind":"意見","question":"分かりました。恐らくそれは緊急時のときだと思うのです。私、今、両方持っていて、まだ新しいのに変えていないのです。古いのにしているのですけれども、いろいろ聞いていると、今、緊急時ではないのですけれども、午後５時になると、「夕焼け小焼け」が流れます。","respondent":"平原防災課長","answer":"防災行政無線には、区民に避難を求める緊急情報と、訓練の実施などのような一般的な放送という２つの種類のものをお流しさせていただいているのですけれども、委員ご指摘のとおり、以前の防災ラジオにつきましては、電波を直接受信しておりましたので。","voiceIndex":37,"id":"exchange-013"},{"speaker":"たけうち委員","kind":"確認","question":"そうなると、緊急情報ではないのかもしれないけれども、例えば防災に関連したような、光化学スモッグだとか、水害の場合はどうするかというのはありますけれども、あとは、これから防災訓練なんかが各地域でありますというお知らせは流したほうがいいのではないかと私は思うのですけれども、その辺はどうなのでしょうか。","respondent":"平原防災課長","answer":"それ以外の一般放送につきましても、所管との確認もありますが、必要なものについては緊急扱いに変える、こういったところで、先ほど裁量でというお話がございましたが、変えることは可能ですので、どういったものをお届けするべきか。","voiceIndex":39,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"先ほど備蓄物資の輸送等のお話をいただきました。場合によっては、道路も人がなかなか動けない。そのような状態になったと思います。そして、区の職員に至っても、鉄道をはじめ道路等が塞がれていたら、なかなか区の避難場所に来るというのは難しいのではないのですかというのを教えてください。物流が止まるだけではなくて、倒壊や崩壊の危険性がかなり高いのだと思うのですが、実際どうなのでしょうか。","respondent":"吉岡防災体制整備担当課長、中村都市環境部長","answer":"それから約１０年たったところで、東京都では、東京都と品川区、これが連携してというところになりますけれども、まずは一斉帰宅の抑制に力を入れてまいります。こういった優先順位を定める中では、まずは一番危険度が高い、滞在時間の長い住宅系から始めて、その次、東京都の動向も注視しながら、今ご指摘の中高層の建築物、こういったところにも今後また検討が及ぶのではないかと考えております。","voiceIndex":42,"id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"そうすると、実際これはいざ物資を運ぶとき、人をどこかに、病院でも運ぶときに、恐らく使えなくなるということを考えておかないと、例えば、本当に道路が広くて、建物が１つや２つ倒れても、全然道路としては使えるスペースがあればいいけれども、実際は違うではないですか。では、多摩川に行ってどうなのですか。林試の森公園に行って逃げればどうなのですか。八潮に逃げたらどうなのですか。","respondent":"吉岡防災体制整備担当課長","answer":"やはり町会単位で備蓄物資というところになりますと、我々もそうですが、管理が非常に難しいという部分もありますし、それがきちんとあるかどうかというところの点検を誰がするのかという問題が発生してきてしまう部分もありますので、我々といたしましては、在宅避難の重要性。","voiceIndex":45,"id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"だから、そういうときだったら、私は管理も楽だと思いますし、そういう平時のときに、交換でも運用でもできるような仕組みづくりを私はつくっていかないと、品川区、狭いところに４０万人超えた人口、多くの方が住まわれているのですから、考え方を変えて、いざどうしようもないときには避難所にも今までどおり届けるというのは、これは基本ですけれども、やはり地元は地元で。","respondent":"吉岡防災体制整備担当課長","answer":"共助といたしましては、町会単位で倉庫があるという部分もありますけれども、そういった訓練をやっていただいたりですとか、避難所連絡会議、運営会議、そういったところで対応していただいている部分もあります。","voiceIndex":47,"id":"exchange-017"},{"speaker":"小芝委員","kind":"質問・要望","question":"災害時は、地域センターと防災課をＩＣＴでつなぐというような説明はされているのですけれども、区民のほうから、防災課というか、災害対策本部に上がってくるような情報とか、そういったものは、コールセンターだけでなくて、ＩＣＴをぜひ活用していくべきではないかと思いますけれども、その辺りの考えを教えていただきたいと思います。","respondent":"平原防災課長","answer":"まだ区として統一的に、その方々が避難所に行くということもありますので、できるところとできないところで地域が分かれてくるというような、そういう局面もありますので、統一的な運用というよりは、まだそういう考え方のレベルですけれども、様々なそういうＩＣＴを活用して。","voiceIndex":50,"id":"exchange-018"},{"speaker":"小芝委員","kind":"意見","question":"防災タブレット、防災区民組織だとか、町会・自治会長に既に配付されているというのは私も承知しておりますけれども、町会長、自治会長によっては不慣れな方もいるので、その辺りまた、既に恐らく地域センターごとに講習といいますか、そういったことでいろいろと教えられているかと思うのですけれども、その辺り、もう少し進めていくべきではないかと思いますので、意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-019","title":"町会・自治会支援"},{"speaker":"田中委員","kind":"確認","question":"３点、お知らせください。先ほど炊き出しの話がありました。９月にある合同訓練の際に、この訓練の参加を促し、それでそのときにこの情報の在り方というのも当事者の方たちに聞いていただければいいのかと思ったのですけれども、そこのところの見解を伺いたいと思います。３つ目です。先ほど施設の耐震の話がありました。区有施設でも、１つ、耐震に課題のある施設があったと思います。","respondent":"平原防災課長、鈴木都市計画課長","answer":"続きまして、都区合同防災訓練における障害者に対する現状というお話ですが、障害者の方に対しての現状説明、重要だと考えていますが、都区合同防災訓練につきましては、プログラムがしっかりした中で行うものですので。区有施設で、その施設名は記憶として定かではないのですが、都有施設と併設の、建物全体が区が単独の所有ではなくて、区の施設と都の施設が併設する形でなっている施設が少数まだあって、その関係で。","voiceIndex":54,"id":"exchange-020"},{"speaker":"田中委員","kind":"意見","question":"区有施設のところについてです。ただ、これから改善に向けてどうされていくのか、もし何かあればお知らせください。","respondent":"鈴木都市計画課長","answer":"確認をして、当委員会の中で後ほどご報告します。","voiceIndex":57,"id":"exchange-021"},{"speaker":"田中委員","kind":"確認","question":"炊き出しのところです。学校での炊き出しなのですけれども、校庭での炊き出しが想定されていますかというところを確認させてください。","respondent":"平原防災課長","answer":"炊き出しですけれども、訓練のときには、校庭といいましょうか、グラウンドにテントを張って、その中でやっておりますけれども、グラウンドには砂がありますので、原則的には、いわゆる家庭科室のようなところでの炊き出しを基本と考えているところです。","voiceIndex":59,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"分かりました。火事になってしまったりとか、いろいろ考えて不安だったので、でも、そうではないということだったので、訓練のときとかでも、区教委ともそういう協議をきちんとしてもらって、そういう炊き出しのスペースの確保ということも大事なのかと思うので、そこのところを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-023","title":"町会・自治会支援"},{"speaker":"のだて副委員長","kind":"質問","question":"そこの訓練なども行っていましたら、伺いたいと思います。先ほどのご答弁だと、被害想定が少なくなったので少し余裕があるというお話だったのですけれども、在宅避難者含め、避難所以外の避難者の人の備蓄というのは、区としては今の備蓄で十分足りていると考えているのか、そのところも伺いたいと思います。","respondent":"吉岡防災体制整備担当課長","answer":"輸送に関して、訓練がというところもございましたけれども、こういった訓練につきましては、やはり非常に重要ですので、東京都のトラック協会ですとか、あとは協定を結んでいるようなところとしっかりと訓練を今後検討していきたいと考えているところです。備蓄数についてです。","voiceIndex":63,"id":"exchange-024"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"仕分をして運ぶに当たって、必要な物資について各避難所に何をどう運ぶか、どうというのは車なのかもしれませんが、どうやって把握するのかというところと、その訓練などを実施していただきたいと思うのですけれども、そこのところを改めて伺いたいと思います。仕分のところは輸送業者が行うということで、その辺りも訓練をされて実施をしていくということなのかどうか、そこを確認させてください。","respondent":"吉岡防災体制整備担当課長","answer":"輸送のところ、こちらにつきましても、きちんと仕分のところも実際に平時のところから行っているところですけれども、こういった訓練というところでもしっかりと仕分作業を行って避難所へ運ぶ。そういった想定のところで訓練を検討しています。","voiceIndex":65,"id":"exchange-025"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"いろいろ計画されているということですので、しっかり物資が届くように、仕分も含めて、あと、必要な物資を把握するというところも含めて、計画を持って、それで訓練も実際しっかり行っていただいて、やっていっていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-026"},{"speaker":"田中委員","kind":"確認","question":"荏原第一地域センターについて、今新しい、駅前のほうに移動したから大丈夫というお話だったのですけれども、男女共同参画センターはその元荏原第一地域センターのところにあるので、男女共同参画センターについてはまだ危ない状況にあるということなのですが、ただ、そこも上というか、共同住宅があったり、下がスーパーだったりとかで、そこの耐震に対しての確認は取れていないということでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-027"}]},{"id":"topic-02","title":"「震災時火災における避難場所等の指定（第９回）」の公表","agenda":"「震災時火災における避難場所等の指定（第９回）」の公表","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"これについて、正しい知識、残留地区なのだと。決して区や都が何もしないというところではなくて、非常に不燃化が進んでいて安全な地域で、避難地域に行く必要が基本的にはない、そういう地区なのだというご理解を進めていただかなければいけないところだと思うのですけれども、そのためにどのようなことが必要だとお考えになっていらっしゃるかという点をお伺いしたいと思うのですが、いかがでしょうか。","respondent":"吉岡防災体制整備担当課長","answer":"あらゆる機会を通して、区民の皆様にしっかりとご理解いただけるように、周知徹底してまいります。","voiceIndex":77,"id":"exchange-028"},{"speaker":"おくの委員","kind":"提案","question":"この１枚目の今のご説明資料にも、周知すると。例えば、３枚目のこれは都の資料ですか。これ、防災訓練とか、そういうことのたびに、こういうことなのだということをお知らせし、何らかの形で訓練の中に取り込んでいただきたいと思います。その場で周知するし、訓練の中で取り組んでいくということをお考えいただきたいと思います。意見、提案ということで、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-029"},{"speaker":"たけうち委員","kind":"質問","question":"東京都の第９回ということで見直しです。見直しが時々あるわけですけれども、それに当たって都から区に、何かこういうことの見直しを今考えているのだけれどもとか、もしくは見直しをするに当たって区の意見を聞きたいとか、そういう連携はあるのでしょうか。","respondent":"吉岡防災体制整備担当課長","answer":"そういったところで地域の要望ですとか、この地域に関してはこの広域避難場所の避難ができないかとか、そういった部分の事前の調整をさせていただいているところです。","voiceIndex":81,"id":"exchange-030"},{"speaker":"たけうち委員","kind":"確認","question":"分かりました。今までは大井ふ頭だったのか。ここの方たち、町会の方たちも、現実的にこんなに行けないという声が随分出ていて、この地図を見ると、一番近いところでいうと、区役所とか戸越公園とかに行きたいわけなのでしょうけれども、ただ、１人当たりの平米でいくと限られてしまうということなのでしょうが、そういう声があるということはお聞きになっているかどうか、一応確認しておきたいと思います。","respondent":"吉岡防災体制整備担当課長","answer":"引き続き不燃化の進展が進めば、こういった部分がまた解消されるかというところもありますので、引き続き東京都の調整、そして、区民の皆様からしっかりとお話を聞く、こういったものはしっかりとやっていきたいと考えています。","voiceIndex":83,"id":"exchange-031"},{"speaker":"たけうち委員","kind":"質問","question":"これ、分かればで結構ですけれども、今度庁舎が新しくできて、またここのところがどうなるかというのは分かりませんけれども、この辺一帯が少し変化してくる中で、全体的にそういうスペースが増えるのか減るのか分からないのですけれども、そういう流れの中で、少しまた見直しみたいなものがあるのかないのかというのは、そういうのは区のほうから、こうなったのでこうしてくれみたいなことは。","respondent":"吉岡防災体制整備担当課長","answer":"今、広町のというところでお話がございましたけれども、やはり今、広域避難場所に指定されている部分で、大きな計画がある部分につきましては、しっかりと東京都と調整、共有をしていますので、見直しの時期というところは、東京全体で行うところですので。","voiceIndex":85,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"資料にあるとおり、火災の危険があり、一時集合場所にいては危ないとき、つまりは学校や公園にいるけれども、市街地大火によって、ここにいては火災の危険で命が危ないとなったときに広域避難場所に移動するという計画だと、私はそう理解しているのですけれども、それでいいのかということがまず１点聞きたいのと、こうした理解を広げていく必要があると思うのですけれども、いかがでしょうか。","respondent":"吉岡防災体制整備担当課長、平原防災課長","answer":"ご質問いただきました広域避難場所ですけれども、委員ご説明いただきましたとおり、広域避難場所は、大規模な延焼火災が鎮火するまで一時的に待機する場所ということで、やはり周知のところについては、分かりやすくご説明を、また。こちらの火事ですが、大規模火災ということで、災害救助法適用の災害ということで恐らく避難した方がいらっしゃるかと思います。それより前になりまして大きなものとなると、２７年前の阪神・淡路大震災といったところです。","voiceIndex":88,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"少し教えていただきたいのですけれども、今、新潟のケースの説明がありましたが、大規模な火災という言葉と、市街地大火という言葉と、今日の資料だと、震災時火災とあるのですけれども、防災対策、昔は市街地大火とよく言っていたものなのですが、最近は市街地大火という言葉は使われなくなったのですか。市街地大火とは位置づけられていなかったのかと思うので、そこの辺りを整理してご説明いただけますか。","respondent":"平原防災課長","answer":"そういったところで、ある程度の火災のときに逃げ込む場所であるというところを、あらかじめご理解いただくことが重要かと考えています。","voiceIndex":91,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"その点、伺いたいと思います。ここは繰り返し求めてきたことではあるのですけれども、本気でそういう取組をすれば、大規模火災のリスクを下げられる、防ぐことができる、そういう意味では区内全域に拡大することが必要だと思います。いかがでしょうかということです。そういう意味でも、木造住宅の建て替え支援というのは全域に広げていただきたいと思うのですけれども、いかがでしょうか。","respondent":"中村都市環境部長、平原防災課長","answer":"先ほどの繰り返しになりますが、そのような形で今考えております。今、支援が行き届かない建物については、今後の検討課題というところで、また、他の自治体や東京都の動向も踏まえて慎重に判断をしていきたいと考えております。それ以外にも、独自の判断で、大きな火が見えたときにご自身の判断で逃げ込む、そういったことも十分考えられるかと考えています。","voiceIndex":93,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"建て替えを進めていけば、そうした大規模火災の発生を抑えることができる。それで、避難指示、これ、区長だということは分かるのですけれども、あと、自分の判断で行動するという、それはもっともだと思うのですけれども、区から区民に伝えることはないのですか。防災行政無線とかを流すのか、それこそ防災ラジオとかを使うのか、そのように思っていたのですけれども、そこだけ最後ご説明いただきたい。","respondent":"平原防災課長","answer":"大変失礼いたしました。発令の方法ですけれども、火災のときの避難発令につきましても、例えば、台風、それ以外のときと同じように、防災行政無線、それ以外、様々な方法を使って、区民に発令の事実を伝えてまいります。","voiceIndex":96,"id":"exchange-036"},{"speaker":"新妻委員","kind":"確認","question":"１点だけ確認します。頂きました資料の２枚目の東京都の資料の中の３番の公表内容のお知らせ方法ということで、（２）に、概要を記載したパンフレットは、都民情報ルームや各区窓口で無償配布しますとなっておりますが、これは品川区の窓口で配布されるのか。防災課ということで配布をしていただけるのか、教えてください。","respondent":"吉岡防災体制整備担当課長","answer":"こちら、東京都が交付したパンフレットの取扱いですけれども、品川区に先日届いたばかりです。こちらは防災課の窓口で配布をさせていただいて、残数等を確認しながら、どういったところで配布できるかというところは検討してまいりたいと思います。","voiceIndex":99,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"１点、気になったのが、西品川二丁目と豊町一丁目の一部のところで、先ほどご説明の中で、より近いところに避難ができるようになったというご説明でした。それには納得をするのですけれども、震災が起きてから火災が発生した場合ということで、西品川と豊町の一部の方たちが新しく避難先に指定されたところ、戸越公園ではないところは、線路を越えていかなければいけないではないですか。","respondent":"吉岡防災体制整備担当課長","answer":"個別のところでは、特に確かに品川区、路線が多いところもありますので、今後また地域の声も様々聞きながら、東京都と調整を図っていきたいと考えております。","voiceIndex":102,"id":"exchange-038"},{"speaker":"田中委員","kind":"確認","question":"ですので、確認をしました。地域の方々への説明等を行っていくというお話だったのですけれども、やはりそのリスクもあることと、そのときの判断も必要だと。近いところが大事というのは本当にそのとおりだとは思うのですけれども、ただ、そういったリスクもあるということの認識は必要なのかと思うので、そういった周知も併せてお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-039"},{"speaker":"のだて副委員長","kind":"質問","question":"先ほど個人の判断もあるという話もありましたけれども、そうした逃げなければいけない大規模火災のときに、見えたら既に手後れというような気もするのですが、そこのところを伺いたいと思います。","respondent":"平原防災課長","answer":"一時集合場所での考え方ですけれども、まず、大きな地震が発生したときには、地域の方々には火災の有無に関わりなく、一時集合場所に一時集まっていただいて、様子を見て、必要に応じて自宅に待機もしくは避難所に行きますと。そのような形で地域にお知らせしています。","voiceIndex":106,"id":"exchange-040"},{"speaker":"のだて副委員長","kind":"質問","question":"現場での判断という感じだったのですけれども、なかなかその判断というのは難しいのかと思うのですが、そういうのは大体消防団の人とか、そういった方が判断できるものなのか。あるいは、仕組みをつくって、訓練とかをやっていかなければいけないのかという気もするのですが、その辺りはいかがでしょうか。","respondent":"平原防災課長","answer":"危険が迫ってきましたら、区から避難指示というものをいろいろな手段で強くお流しするというのは、もちろんやらせていただきたいと考えています。","voiceIndex":108,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6620#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":45274,"voices":112}},{"id":"r04-20220728-10","meetingId":"r04-cm07","date":"2022年7月28日","dateIso":"2022-07-28","committee":"議会運営委員会","time":"午後 １時００分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"ＩＣＴ推進会議からの報告事項","agenda":"ＩＣＴ推進会議からの報告事項","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"ＩＣＴ推進会議で議論もした上での結論であるので、更新に反対するものではないのですけれども、今後もまた更新期にｉＰａｄを全議員に貸与し続けるかが、今後の検討課題になるのではないかと思います。だから、更新のたびに、今回はペンとフィルムを合わせると約５７３万円ということで、これだけの議会費をかけてｉＰａｄを支給することに区民の理解が得られるのかは、検討が今後必要だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"に戻りまして、令和５年度予算（議会費）","agenda":"に戻りまして、令和５年度予算（議会費）","exchanges":[{"speaker":"湯澤委員","kind":"質問・要望","question":"ご説明します。例年要望しているものが２点と、それから、新規の要望１点の計３点の要望をします。それから、３つ目は新たな要望になりまして、議会政策立案費についてで、現在は会派や個人ごとに政務活動費の範囲で行っているかと思いますが、政策立案を今後、議会全体や、また、各会議体、例えばＩＣＴ推進会議などの、そういった取組に対する経費を求めるものであります。要望は以上となります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-002"},{"speaker":"たけうち委員","kind":"意見","question":"控室に入ったところにある目隠し用のアコーディオンになっている衝立と、それ以外にうちの場合は２つあるのですけれども、アコーディオンのほうは備品だということが分かったのですが、パーテーションは古過ぎて分からないのですけれども、もし議会で買ったものだったら、買い換えてもらいたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"７番目が、予算・決算特別委員会の民生費のところが、一般会計と国保や介護、後期高齢者医療の特別会計、この４つの会計を１日で審議しているわけですけれども、これの十分な審議をしていくために、２日に分けていただきたいと。１０番目が、それと関連するのですけれども、ケーブルテレビ品川の放送のときにも、区議会の質問のときに字幕を付与するようにしていただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"１点質問をさせていただきたいのですが、自民党の議会政策立案費というのが今回新しく出されたと思うのですけれども、今までも広報会議とか議会報告会とかで他自治体に視察に行っていたと思うのですが、それはどのように旅費などが処理されていくのかという、それは事務局に聞くことかもしれませんが、そこの確認と、今回幾つか、コンサル費や旅費、講師費用ということで想定されていますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"提案","question":"そのときに、コンサル費や旅費、また、講師費用、こういうのを設定していったとき、それが幾らかかるのか分からないけれども、それが例えば５００万円なのか、それぐらいの予算をつけておいて、そういうのをまず前へ進めて、一歩そういう議会全体で議員提案みたいなものができるようなことにしていくには、こういう予算をつけておいたほうが、意識も変わってくると思っているので。","respondent":"工藤区議会事務局長","answer":"前段のご質問の件です。これまでというところでのお答えになりますが、これまでもいろいろと議会改革等の内部の会議体を動かすに当たりまして、いろいろと視察等もあったかと把握しております。","voiceIndex":19,"id":"exchange-006"},{"speaker":"のだて委員","kind":"意見","question":"今のところ政務活動費で対応されているということで、特に問題になっていないのかという認識をしています。コンサル費が例えば５００万円ということで、結構大きいと思っていたのですが、コンサル費、議員が自ら調査・研究して政策立案するというのが議員の仕事なのではないかと思います。今ご説明いただいたのですが、今の時点では、この必要があるとは思えないという意見を述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"先ほど政策立案費の話が出ましたけれども、やはり今までどおり政務活動費でやるところまでやって、それで、それがだんだん費用がこのようにかかってきたと。そういう実績をつくって、やはり足りないから予算づけしようというのが、根本的な予算のつけ方だと思うので、最初からぼーんとコンサル費、旅費だ何だと費用を……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"だから、おかしいのではないのですかということと、それから、政務調査費も第三者機関設置とありますが、これも今、かなり品川区、議長の下に厳しく……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-009"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"行政視察についてなのですけれども、コロナの感染がものすごい勢いで急拡大している状況ですが、これから８月にピーク、５万人とかとも言われたりしていて、その後、感染者の減少に向かうけれども、緩やかだから、９月ではまだ２万人、３万人の感染者がいると言われている下で、各委員会でも、委員長からは中止の可能性もあるということは言われたのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"ただ、我々も分かりにくい病気なので、お医者さんのそういう議会に出ていいという許可は、そのように半ば頃に出ていいというお話なのですが、実情、どうなるか分かりませんが、今、おかげさまで回復を順調にしているということだけをこの場で申し上げたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5474#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":7503,"voices":40}},{"id":"r04-20220822-6","meetingId":"r04-cm08","date":"2022年8月22日","dateIso":"2022-08-22","committee":"区民委員会","time":"午後 １時００分～午後 ２時０７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"マイナンバーカード交付会場の拡大","agenda":"マイナンバーカード交付会場の拡大","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"交付会場の拡大ということですけれども、その目的はマイナンバーカードの普及を進めていくということとされています。政府自身も、国自身も今年度末までにほぼ全国民に行き渡ることを目指すとしています。それを勘案してのことだと思います。あるいは明らかに失敗したということを表している数字ではないかと私は思うのですけれども、区としてはいかがでしょうか。この点、伺っておきます。","respondent":"吉野戸籍住民課長","answer":"今後ですけれども、区民の方の利便性、公的な身分証明書だけでなく、電子証明書とか公的な手続の簡略化とか、そういったところもありますので、今後はどんどん普及していくと考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"確認","question":"それでもう１点、その点に関わってお伺いしておきたいのは、健康保険証としての利用を推進ということが国によって言われているわけで、これが目の前にというか始まっているわけですよね。マイナンバーカードの健康保険証としての利用を促進させるために、来年度から医療機関などにオンライン資格確認の導入を原則として義務づけることにすると。これを伺っておきたいと思います。","respondent":"吉野戸籍住民課長","answer":"マイナンバーカードを持たなかったからといって不利益になるかというと、今現在の制度ではそうなっておりません。それから、健康保険の部分ですね。紙のほうにつきましては、所管ではないので何とも言えませんが、しばらくは併用して使えるものと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"将来において、マイナンバーカードを持っていないからといって不利益が生じることが、要するに健康保険証を持っていないことになるようなことがあってはならないと私は思うのですけれども、その点についてはどうお考えでしょうか。","respondent":"吉野戸籍住民課長","answer":"委員のおっしゃるとおりでして、サービスに差があってはならないと考えておりますので、しばらくの間はやはり紙の保険証を使えるものと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"その点、本当に差が生じることのないようにしていただきたいと思います。政府が国民一人ひとりに生涯変わらない番号をつけて、多くの分野の個人情報をひもづけして利用できるようにするというのがマイナンバー制度ですけれども、個人情報の漏洩なんかのプライバシー権の侵害の危険性がどうしてもついて回る。そういう意見を述べさせていただいて、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"塚本委員","kind":"質問","question":"マイナアシストによる申請サポート、１,６９２件という報告をいただきましたけれども、マイナアシストというのはどういう場所で、戸籍住民課にあることは承知しておりますが、地域センター等にも用意されているのかどうかというところで教えていただければと思います。","respondent":"吉野戸籍住民課長","answer":"地域センターなのですけれども、どうしても場所的なものがありまして、端末の増設であったり、そういったところが実はあります。ですので、これからその部分につきましては、交付会場を増やすかというところは検討課題になっております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"塚本委員","kind":"質問・要望","question":"電子証明書の拡大を地域センターで今検討しているというのは、すみません、イメージがよく分からなかったのですけれども、電子証明書というのはマイナンバーカードの申請とはまた別物なのですか。受け取りの話とか、そういう話ですか。詳しく教えていただきたいと思います。","respondent":"吉野戸籍住民課長","answer":"実はマイナンバーカードの交付期限が１０年なのですけれども、電子証明書が５年なのです。そうしますと、カードは持っているのですけれども、電子証明書の更新をしなければなりません。","voiceIndex":15,"id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"代理人による受け取りが可能ということで、今、オンライン申請ができるＩＤ付きの申請書が未交付の方に７月から９月にかけて送付されて、それはオンライン等で申請をやって、代理人による受け取りができるということで、代理人受け取りというのが案内されているかと思うのですけれども、これについては、委任状等を持っていけばそれで受け取れるのかというと。","respondent":"吉野戸籍住民課長","answer":"その方たちがこちらに、本来であれば本人確認が必ず必要なのですけれども、本人確認が難しい方ですね、そういった方に対してこういった代理申請というものがあります。","voiceIndex":17,"id":"exchange-007"}]},{"id":"topic-02","title":"品川区民芸術祭２０２２の開催","agenda":"品川区民芸術祭２０２２の開催","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"スクエア荏原や荏原文化センター、それから五反田文化センター、いろいろな場所で音楽や美術、それから共催・関連事業を含めれば朗読劇なども出てきて、多彩な文化芸術活動に区民が触れ親しむ事業で、すばらしい事業だと思います。本当に毎年進めていただきたいなと思います。大丈夫なのか、この点を伺っておきたいと思います。いかがでしょうか。","respondent":"篠田文化観光課長","answer":"参加団体につきましては、主催あるいは実施に当たっては、例えば参加者の中で実行委員をつくってやったりするものもあれば、区等のほうで実際行っていくといった様々な形態があるのですけれども、いずれにしましても、参加の際の申込みに当たっては。","voiceIndex":23,"id":"exchange-008"},{"speaker":"おくの委員","kind":"質問・要望","question":"いろいろ難しい点があろうかと思いますけれども、そういうことも気にしておかなければいけないことなのだということを踏まえて、見ていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"今回、きゅりあんが工事中ということで、会場として使用されていないとは思うのですけれども、きゅりあんが使えないことによって、スムーズに会場は……、スクエア荏原、荏原文化センターとかがあるわけですけれども、きゅりあんがないことによってちょっと手間取ったとか、そういうことがあったら、教えていただければ幸いです。","respondent":"篠田文化観光課長","answer":"そうしますと、例えばそれまでの手順ですとかがかなり変わったりしてきますので、そうしたものに関しましては、実行委員会等できちんとした手順の見直し等について確認をして周知をしていくというような手順を踏んでいますので、正直なところ。","voiceIndex":27,"id":"exchange-010"}]},{"id":"topic-03","title":"しながわホッケーファンゾーンの開催","agenda":"しながわホッケーファンゾーンの開催","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"前の６月２８日の区民委員会のときに、そのときは仮称でまちづくり懇談会と言っていたのですけれども、正式名称は八潮みらい懇談会にしたと報告されましたが、そのときに、羽田新駅のことを伺ったのですけれども、この賑わいづくりというのは、羽田新駅なんかと関係があるのでしょうか。そこら辺をお伺いしたいと思います。","respondent":"辻スポーツ推進課長","answer":"まちの賑わいづくりですが、東京２０２０大会で開設した大井ホッケー競技場、こちらは公共施設ということで、ずっと残る施設です。","voiceIndex":33,"id":"exchange-011"},{"speaker":"おくの委員","kind":"質問","question":"別に新駅とかそういうこととは関係がないということでしょうか。はい、いいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-012"}]},{"id":"topic-04","title":"障害者スポーツチャレンジデーの開催","agenda":"障害者スポーツチャレンジデーの開催","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"２つほどお伺いしたいのですが、理解と関心を高めるためにも、できれば種目を増やしていく、特に子どもも楽しめる種目を増やしていくことも考えていいのではないかと思いますけれども、その点、いかがでしょうかというのが１つです。それへの支援をすべきではないかと思うのですけれども、その点、どうお考えになっているのか、お伺いしたいと思います。これが２点目です。いかがでしょうか。","respondent":"辻スポーツ推進課長","answer":"は入り口段階といいますか、とにかくまずは触れてもらおうというところから始まっていますので、道具等の費用の援助とか、そういった話になると、もうちょっと大きな話になりますので、今後の課題かなと考えています。","voiceIndex":40,"id":"exchange-013"},{"speaker":"おくの委員","kind":"質問・要望","question":"入り口段階かなというお話でしたけれども、入り口から入って、その先があるはずですから、その先にはやはり支援が、本当にたくさんの費用がかかることになると思いますので、そのこともやはり念頭に置いて考えて、課題とおっしゃいましたけれども、本当に課題なのだということで考えておいていただきたいと思います。そういうお願いというか意見を述べさせていただいて、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-014"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"どれも商店街活性化に向けた興味深い取組で、時間があればどれもこれも、いろいろ具体的に聞いてみたいと思いました。この収集や分析がその商店街のどのような取組につながっているのか、伺えれば伺いたいと思うのですが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"つながりというもので補足しますと、右のほうの（２）ＡＩ・ＩｏＴイノベーション創出支援事業ですが、こちら、区内ＩＴ企業の支援という形でやらせていただいたもので、商店街支援ではなかったというところがあるのですけれども、商店街振興でというところでのつながり。","voiceIndex":47,"id":"exchange-015"},{"speaker":"おくの委員","kind":"質問","question":"そういうデータを集めて、分析したわけですよね。どういう客が来てというようなことだと思うのですけれども、それが今、何かの取組に結びついていっているのでしょうか。あるいはまだそこまではいっていないということなのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"マーケティングの中身については、商店街の貴重なデータというか、自分たちで持っているデータになりますので、公開していただくというのはなかなか難しいかなと思うのですけれども、ただ、戸越銀座商店街で補助金はつくにしてもこれをやっていこうということになりますので。","voiceIndex":49,"id":"exchange-016"},{"speaker":"おくの委員","kind":"質問・要望","question":"それは置いておいて、今度は１番のエリアサポーター事業についてお伺いいたします。支援して解散予定だったのが存続ということですから本当にすばらしいことだと思うのですが、どのような状態の商店街にどのような支援をして、それでなぜ解散予定だったものが存続となったのか、もう少し具体的にお教え願えれば、お教えていただきたいのですけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"個別の事情はご説明が難しいところがあるのですけれども、概して、活動がなかなかできていかないというところで、活動しないので会費が集まってこないと。","voiceIndex":51,"id":"exchange-017"},{"speaker":"おくの委員","kind":"質問・要望","question":"ですから、まさにこういうことをやっていっていただきたいなと思いましたもので、お伺いいたしました。さらに、エリアサポーター事業について区商連からもお話をお伺いしたりしていると、もっとこのエリアサポーター事業については支援を強めていただきたいと区商連はおっしゃっているのです。そこら辺のことをお伺いしておきたいと思います。いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"今後、エリアサポーターというのが多分中心になって商店街支援になるのかなと考えているところですので、委員おっしゃったように、場合によってはもちろん拡大ということも考えているところです。","voiceIndex":53,"id":"exchange-018"},{"speaker":"おくの委員","kind":"質問・要望","question":"先ほど私も申し上げましたし、課長もおっしゃいましたけれども、とにかく区商連からも求められているし、個々の商店街からも多分求められているのだろうと思います。実際に解散事例でも実証されたのだと思います。本当にエリアサポーター事業というのは貴重な事業ですし、支援を一層強めていただきたいと思います。そういう私の意見というかお願いをして、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-019"},{"speaker":"松本委員","kind":"質問","question":"かなり高齢化が進んでいるような商店会と連携して、例えば今回で言ったら、イベントもそうですし、ポイントとかというのも、例えば大きな商店会だけでやっていると、周辺の小さな商店会はどうしようもなくなってしまうというか、そこの枠組みから外れてしまうというふうなことがあると思うのですけれども、どうにか。","respondent":"遠藤商業・ものづくり課長","answer":"商店街同士の連携というところでは、イベントなんかですと幾つかの商店街がまとまってというケースはかなりありますけれども、それを一歩進んでという部分なのかと考えています。","voiceIndex":57,"id":"exchange-020"},{"speaker":"小芝副委員長","kind":"確認","question":"エリアサポーターのことで確認したいところがありまして、６名のサポーターが区内の５つのエリアにまたがってサポートされているということで、こちらなのですけれども、商店街連合会の中にある商店街という認識でよろしいでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"商店街連合会に補助金をお渡ししているのですけれども、実際に活動するのは、地区に分けておりまして、特に商店街連合会に加盟とか非加盟というのは一応外しているという形になっています。","voiceIndex":61,"id":"exchange-021"},{"speaker":"小芝副委員長","kind":"確認","question":"そうしますと、商店街の規模も、商店街振興組合というのが一番大きいのかなと思いますが、小さいところは商店会というのがあると思いますけれども、そういうのも分け隔てなくサポートを行っているということでよろしいでしょうか。確認です。","respondent":"遠藤商業・ものづくり課長","answer":"実際問題は、人数が限られているところもあって、強弱は当然出てきますけれども、一応全部を回るという形でやらせていただいているところです。","voiceIndex":63,"id":"exchange-022"}]},{"id":"topic-06","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"松本委員","kind":"質問","question":"私も地元が地方の山口県なので、地元から話を聞くと、またコロナが出始めた頃と同じで、東京からは人が来てほしくないと。その中で、ここまでやっていただいていて本当に申し訳ないのですけれども、例えば方法のところになって申し訳ないのですが、オンラインでやるとか、そういったことは考えられなかったのかというところをお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-023"},{"speaker":"松本委員","kind":"質問","question":"オンラインで、実際に現地に行かなければいけないのかというところでいったら、例えばＺｏｏｍを使うとか、役所では、なかなか区議会とか市議会ではやっていないかもしれないけれども、ほかの視察ということでは、オンライン視察とかということもやっていると伺うので、そこは果たしてこの状況の中で現地に行くのがいいのかというところはどのようにお考えかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2938#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":24239,"voices":77}},{"id":"r04-20220822-7","meetingId":"r04-cm08","date":"2022年8月22日","dateIso":"2022-08-22","committee":"厚生委員会","time":"午後 １時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和４年度高齢者福祉行事","agenda":"令和４年度高齢者福祉行事","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"それぞれ行事がある中で、やるものと、開催中止となっているものとあると思うのですけれども、これはどのように所管で判断されて、その判断の基準があるのかどうなのか。こう見る感じ、たくさんしゃべったり、ちょっと距離が近くなったりするようなものは中止なのかなとイメージはできるのですけれども、そのような明確なものはあるのでしょうか。","respondent":"寺嶋福祉計画課長","answer":"明確と言われると、どこまでということにもなるのですけれども、今委員がおっしゃったとおり、例えば飲食を伴うもの、それが１つの楽しみになっていて、それをなくしてはちょっと会として成立しないとか、ご希望にお答えできないといったような類いのものは。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"品川区障害者計画および障害福祉計画・障害児福祉計画策定のための基礎調査","agenda":"品川区障害者計画および障害福祉計画・障害児福祉計画策定のための基礎調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今の説明で、裏面の（２）アンケート調査対象者で障害児のところは、これは障害児でサービス利用者ということの約１,１００名なのか、手帳保持者なのか、そこの障害児の人数の部分を教えていただきたいということと、あとこの2)無作為抽出調査の約３,２００名というものは、サービスは利用していない、そして施設にも入所していないけれども、手帳を持たれている方ということでいいのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"それから３点目の事業所数に関しては、約１３０事業所です。それからスケジュールの期間なのですけれども、大体発送日として９月下旬、９月２０日頃を予定しています。１０月１４日を回収日と設定しておりまして、大体３週間ぐらいの予定になります。","voiceIndex":11,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、今回この調査、基礎調査ですけれども、発達障害の方と高次脳機能障害の方、前回対象に入っていたと思うのですが、今回入っていないのはなぜなのかを伺いたいということと、前回が９年前です。ですから、もし今回もこの数に大きく変わりがないのであれば、前回同様、この２つとも実態把握が難しい障害になるので、調査すべきではないかなと思うのですけれども、いかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"そういった意味では、幅広く回答を得て情報をつかめるように、今回属性の中に設けてアンケートを実施し、そうすることで満遍なく情報を得たいと考えております。","voiceIndex":13,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区のほうでも今そのような、何というのですか、発達障害というところではこうだというところがないということではあると思うのですけれども、やはり今、支援策等も注目されているといいますか、さらに充実させてほしいという声も大分大きく寄せられているところですので、そこはぜひ対象に入れていただきたいと思うことと、高次脳機能障害のところは、特に進んでいないというか。","respondent":"川崎障害者施策推進課長","answer":"調査票の構成のところ、委員からご指摘いただきまして、まだ時間がありますので、再調整して検討します。","voiceIndex":15,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"提案","question":"分かりました。障害児の家庭で困っている内容を尋ねる項目を設けるべきではないかなと。ですから、それはそうだろうなと。ですから、二度目でこれだけ違う中身にしてしまうと、比較がしづらくなるのではないかなと思うのですけれども、これ前回のままの内容でいかないのか、その理由もあれば教えていただきたいと思います。","respondent":"川崎障害者施策推進課長","answer":"障害児のところは、家庭の困り事というお話でしたけれども、今回相談のところ、相談体制、情報の入手という項目で、ご家庭の相談時の困り事や相談に必要な支援、こういった項目は設けておりますので、そこで、その他の項目などもありますので。","voiceIndex":17,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。事業所の項目は、前回の項目からこんなに減らしてしまうのかという思いがしたもので、前回の調査があって出てきた計画なわけですから、そこからさらにいいものにしていくというところでは、前回と比較できたほうがいいのではないかと思ったので、もし検討できたらお願いしたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-006"},{"speaker":"せお委員","kind":"質問","question":"今のところに関連して、１点だけ。施策とはどのようなことかなというような感じであると思うのですけれども。ですから、その辺の表現など改められないかなとは思ったのですけれども、そこだけちょっとご意見をお聞かせください。","respondent":"川崎障害者施策推進課長","answer":"ご質問は言い方というか、設問の……。","voiceIndex":21,"id":"exchange-007"},{"speaker":"せお委員","kind":"意見","question":"そうですね。そこで何か聞けたらというか、いいかなと思っているのですけれども、その辺どうお考えかなと思いました。すみません。","respondent":"川崎障害者施策推進課長","answer":"新庁舎整備も含めてということですね。","voiceIndex":23,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"アンケートを６,０００名に出されるということですけれども、前回のアンケートについて、どれだけ戻ってきたかという、回答があった数字と、今回どれぐらいの回答を見込んでいるのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"もう１点、株式会社アイアールエスの件ですかね。こちら、他自治体での実績がございまして、大田区、港区、新宿区等、計画作成の実績があります。今後策定についてはまだ決まっていませんけれども、プロポーザルで事業者の選定ということで予定しております。","voiceIndex":29,"id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"質問","question":"恐らく前回もそういった議論があったのかもしれませんが、４５.３％という回答率に関してどのようなお考えでいらっしゃるかということを、もう１回すみません。コンサルのところ、福祉に限らず、そういったいろいろなコンサルをする会社なのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"前回の数字４５.３％は妥当と考えております。アイアールエスに関しては、詳しい情報を今持ち合わせておらず申し訳ありませんが、こういった自治体の計画策定としての実績があるということで伺っております。","voiceIndex":31,"id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問","question":"前回のときのお話を私は知らなくて申し訳ないのですけれども、４５.３％というのは適切かというと、どうなのでしょうか。いろいろな事情で出せない方がいらっしゃるということは分かるのですが、できるだけ多くの方にご意見をいただいて、それが計画に反映されることによって、施策としてよいものとなると思いますので、その点だけお願いします。","respondent":"川崎障害者施策推進課長","answer":"確かにできるだけ多くの方にご意見いただく、そのほうが私たちにとっても、幅広い計画として今後の施策にもつながっていくと思いますので、皆さんが回答しやすいように、私どもももう一度調査票のほうは検討しながら、多くの方にできるだけご意見いただけるように。","voiceIndex":33,"id":"exchange-011"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"住居確保給付金と自立支援金ということで、９月末まで特例の延長ということなのですが、この自立支援金は、緊急小口資金、あと総合支援資金の終わった人ということですけれども、ちょっと関連して、緊急小口資金と総合支援資金の件数と額、この間もまだまだ長引いているコロナなので、どれぐらいまでいっているのかということが分かれば教えていただきたいということと。","respondent":"櫻木生活福祉課長","answer":"免除につきましては、こちらも伺ったところによると、８月末まで免除申請を受け付けている、まさに最中ということでして、かつ品川区社会福祉協議会のほうでは免除申請を扱っていない、直接東京都のほうに申請するような形ということですので。","voiceIndex":39,"id":"exchange-012"}]},{"id":"topic-04","title":"を改めて聴取いたします。 (3)品川区における新型コロナウイルス感染症対策","agenda":"を改めて聴取いたします。 (3)品川区における新型コロナウイルス感染症対策","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"感染が大変拡大してきて、今は少し落ち着いたとはいえ、２万人を超えている状況です。やはりこの間、本当に保健所の職員の皆さんの、月ですけれども、昨年だと８１時間が平均残業時間で、最大の方で２０１時間という、１か月ですね。このような状況があったわけですけれども、今現在はこれと同じ状況になっているのか、その辺を伺いたいのですが。","respondent":"坂野保健予防課長","answer":"超勤なのですけれども、８月の分はまだ全然締めていない状況なのですが、７月あたりで見ますと、若干多い者は何人かいるのですけれども、まだ集計ができていませんので、ちょっと具体的に何人だということはご容赦いただきたいと思います。","voiceIndex":47,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、この間本当に感染が広がって、でも当初よりは重症化がしづらかったりとか、ワクチンも打たれているとか、様々な状況で、感染された方がそこまでパニックにはなってはいないのかなとは思うのですけれども、病院は本当に大変な状況だったと思うのですが、やはり急拡大に伴って、検査や受診の集中を緩和するために、東京都が検査キットを濃厚接触者や有症状者に対して配布。","respondent":"坂野保健予防課長","answer":"現在、区で抗原検査キットは、若干量は確保はしているという状況です。もう１点、何でしたか。","voiceIndex":49,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"問合せでどこにもつながらないという不安を募らせるのではなくて、そのようなときにホームページを見たら、とりあえずそこに行ってみよう、そして無症状なら検査も受けられるようだという、そのようなものが分かるように、区としてはするべきではないかと思うのですけれども、どうなのでしょうか。","respondent":"坂野保健予防課長","answer":"それで、やはり区の独自のコンテンツを持つというよりは、都のほうを見てもらったほうがどちらかというといいのかなというのが今の考え方です。","voiceIndex":53,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"このようなときだからこそホームページはすごく重要だなと思うのです。ですから、そこは分かりやすく、電話等々つながらないという混乱を招かないような、対応としてはやはりホームページはすごくいいと思うので、ぜひそこは引き続き検討していただきたいなと思います。ですから、そこはぜひ対応を区として要望していくということをしていただきたいと思いますけれども、いかがでしょうか。","respondent":"坂野保健予防課長","answer":"診療報酬体系については、国が全国一律で、国民皆保険の制度の下でやっていることですが、コロナに関する特例的な診療報酬ですけれども、一部の自宅療養者等へのオンライン診療等の診療報酬の特例に関しては、この９月の末まで一応延長というように聞いてはおります。","voiceIndex":55,"id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。そうはいっても、このコロナ対応で、しかも従事者が感染してしまうというところでは、現場が人手不足というところもすごくできてしまっていると。そのような中での対応ですので、本当にさらなる支援、医師会等から求められている声には、ぜひ応えていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ワクチンのところで伺いたいのですけれども、基本的なところで教えていただきたいのですが、５回目接種なのですけれども、１０月半ば以降に、初回接種、１回目、２回目が終わった全ての区民を対象、３２万２,０００人程度に接種券を送られるということなのですが、この４回目は対象が高齢者であったということにもかかわらず、５回目はオミクロン株対応だからということで。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"括弧で５回目というように書きましたのは、最大で５回目の方がいらっしゃるという意味でこちらのほうには記入いたしましたので、国の説明は、オミクロン株対応ワクチンという説明をされているということをご説明申し上げます。","voiceIndex":59,"id":"exchange-018"},{"speaker":"あくつ副委員長","kind":"質問","question":"３回目打った方は４回目を早く、高齢者の方は打ったほうがいいですよということなのか、それともそれはお好みで、お好みという言い方はちょっとあれかもしれませんけれども、５回目を待ったほうがいいですよということを国としては、そこについては発信をしているのかしていないのかというところで、４回目を受けたほうがいいのか、それとも５回目を待ったほうがいいのでしょうかと我々が聞かれた場合。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただ国は、繰り返しになりますが、今打てる方は速やかにお打ちくださいというような説明をされております。","voiceIndex":61,"id":"exchange-019"},{"speaker":"あくつ副委員長","kind":"質問","question":"今のご答弁の中で間隔の話が出たのですけれども、今４回目を打った高齢者の方は、まだちょっと間隔については出ていないというお話でしたが、やはり５か月待たなければいけないという話になると、オミクロン株対応を逆に打てなくなってしまうからという、そのようなことでよろしいですか。はい、分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3638#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":20223,"voices":66}},{"id":"r04-20220822-8","meetingId":"r04-cm08","date":"2022年8月22日","dateIso":"2022-08-22","committee":"建設委員会","time":"午後 １時００分～午後 ３時２３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"会議の運営上、予定表の順番を入れ替えまして、(5)令和４年９月区民住宅（空き室）入居予定者登録募集","agenda":"会議の運営上、予定表の順番を入れ替えまして、(5)令和４年９月区民住宅（空き室）入居予定者登録募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"１点だけ、この間の募集倍率などの募集状況、応募状況を伺いたいです。","respondent":"竹田住宅課長","answer":"空き室の応募件数ですが、過去３年分ご紹介します。令和元年度が７６件、令和２年度が１２３件、令和３年度が８７件です。入居された方は、令和元年度が９件、令和２年度が３０件、令和３年度が６０件です。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"区民住宅ファミーユ西五反田東館の火災","agenda":"区民住宅ファミーユ西五反田東館の火災","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"区民住宅で火災が発生したということで、この原因というのは分かったのでしょうか。それに伴って再発防止をしていくことが必要かと思うのですが、その対策を伺いたいと思います。それで、今回の火災では、内部は燃えなかったということでよいのか確認させていただきたいと思います。今回、保険を適用して、共済を適用するということですけれども、この見込額は幾らぐらいなのか伺います。","respondent":"竹田住宅課長","answer":"原因ですが、東京都の情報公開条例に基づきまして公文書の開示請求を行ったところ、この情報は個人に関する情報で、特定の個人を識別することができるものであるため、条例第７条２号により非開示との回答を受けておりまして、原因の部分は黒塗りになっておりましたので。","voiceIndex":11,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"火災の原因は非開示ということで、なかなか再発防止が難しいのかなというところがあるのですが、一応、お知らせはしたということですけれども、引き続き同じことが起きないように気をつけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"すみません。保険の部分で１点確認させていただきたいのですけれども、特別区有物件火災共済に損害額の一部を請求した後に、変わってくるもの、契約の変更であったりですとか、そういったことは何か発生するのでしょうか。例えば、残存共済責任についてですけれども、給付後に金額によって契約が終了する場合があるかと思うのですが、現状どうなっているのかというところを確認させてください。","respondent":"竹田住宅課長","answer":"手続き終了後、共済保険の請求をするところですが、お尋ねの保険内容に対する影響というところですが、経理課で保険業務の請求等を行っておりますので、保険契約の詳細については承知していないところです。","voiceIndex":15,"id":"exchange-004"},{"speaker":"横山委員","kind":"確認","question":"これからということで、今後どうなっていくのか。万が一ほかの物件で同じようなことがあった際に、どういったことを想定していかなければならないのかというところを確認していただければと思いますので、ほかの課とも連携、調整をしていただいて、確認だけよろしくお願いしたいと思っているのですけれども、ご見解をお聞かせください。","respondent":"竹田住宅課長","answer":"火災というのは、どの施設でも起こり得ることです。私どもの施設でもまた起こり得る可能性のあるものですので、関係部署と十分連携しまして、まずはそういうことが再発しないように、起こった場合には速やかに対応できるように十分連携していきたいと考えております。","voiceIndex":17,"id":"exchange-005"},{"speaker":"芹澤委員","kind":"確認","question":"１点確認をしたいのですが、被災内容の確定というのをどのようにされたのか改めてお伺いしたいのですが、これ、住んでいる方から以前もお話をお伺いして、火災から１か月程度たっても、まだ被害状況、ご自宅に被害はありませんかというような聞き込みがなかったというお話をいただいていたのですが、何日頃、そういうのを皆さんから居住者の方に確認されて。","respondent":"竹田住宅課長","answer":"今回の火災についての事後の調査は、消防署あるいは警察が中心になってやっておりますので、私どもが直接お尋ねしたというところはないのですけれども、ただ、指定管理者から必要に応じて調査はさせていただいたと聞いております。","voiceIndex":20,"id":"exchange-006"},{"speaker":"芹澤委員","kind":"確認","question":"そうすると、調査をされる確認の流れの中では、区としては特段関与されていなくて、警察なり消防が指定管理者と直接やり取りをして、指定管理者から区民の方にご連絡をされたという認識でよろしいでしょうか。","respondent":"竹田住宅課長","answer":"消防から聞いておりますのは、出火直後、消火直後に関係のお部屋は一軒一軒回ったと聞いております。","voiceIndex":22,"id":"exchange-007"},{"speaker":"芹澤委員","kind":"確認","question":"私が確認したいのは、多分、消防の方がされたのは、火が今ついていませんかというような確認であると思うのですが、事後、火を完全に消火し終わった後に、建物の中、居住されている方々の物品であったり、ベランダに焼け焦げとか、そういったところも含めて被害はありませんかというような確認を多分されるのだと思うのですけれども、それを消防、警察がやられるということであれば、区は関与せずに。","respondent":"竹田住宅課長","answer":"消火直後に消防が被害状況の確認をし、さらに指定管理者から必要に応じてお聞きしたと聞いております。区の職員が直接お部屋を回ってということは、今回はしておりません。","voiceIndex":24,"id":"exchange-008"},{"speaker":"芹澤委員","kind":"質問・要望","question":"最後にもう一度だけ、すみません、確認ですが、指定管理者が確認をされるというところの確認作業の依頼だったり集計だったりというのは、区は直接関与していなくて、消防や警察からの依頼を受けて、区が全く関与しない形で最終的な確認をされたのかというところで、もし関与しているのであれば、何日にしたのかというのが分かればお聞かせいただきたいと思います。","respondent":"竹田住宅課長","answer":"指定管理者に区から指示しまして、具体的な日にちは今手元に記録がないのですけれども、あまり時間が経過していない時点で調査したと聞いております。","voiceIndex":26,"id":"exchange-009"},{"speaker":"こんの委員","kind":"確認","question":"芹澤委員に関連してお伺いしたいのですけれども、今までの議論を聞いていて、原因は都条例に基づいて公開はなし、そして、今の記載内容の確認、聞いていると、すみません、区の住宅でありながら、区民の方が住んでいるところでありながら、区が真っ先にそのことを把握して手を打つ、あるいは再発防止の動きをするというところが、どうも今の議論を聞いていると。","respondent":"竹田住宅課長、中村都市環境部長","answer":"今回は１３階の１号室というところが出火元でございまして、当日は結構風も吹いておりましたので、火の粉が真下の１２階１号室、１０階の１号室に飛んで、一部ベランダに置いてあったものが延焼したという状況です。ただ、後日の対応として、居住者の方には火気に十分注意していただくように、区としても建物の所有者としてしっかりとお伝えをさせていただいたです。","voiceIndex":29,"id":"exchange-010"}]},{"id":"topic-03","title":"東京港大井ふ頭（都有地内）において確認された「ヒアリ」","agenda":"東京港大井ふ頭（都有地内）において確認された「ヒアリ」","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"ヒアリは毎年夏に発見されていると思うのですけれども、年に２回発見されたこともありましたが、そうなってくると、生息している可能性も出てくるのかと危惧してしまうところですが、そこのところと、やはりそうでないとすると、水際対策をしっかりしていかなければいけないと思うのですけれども、水際対策の強化を国に求めるべきではないかと思うのですが、いかがでしょうか。","respondent":"河内環境課長","answer":"追加調査といたしまして、先行いたしますが、私どもで年３回あるいは４回やったものですが、追加調査として、その後追い、その場の確認と、その後のアフターフォローとしてやると、そのような回数になるものです。","voiceIndex":37,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"調査回数のところで、アフターフォローでこの回数になっているということでしたけれども、その辺がよく分からなかったので、もう少し詳しくご説明いただけたらと思うのと、あとは、水際対策というところで、出入りの箇所を設定するようになったということですが、これはどういったことをやられているのか。それの目的ですとか、それによってどういう効果があるのかというところを伺いたいと思います。","respondent":"河内環境課長","answer":"国の回数と区の回数の相関です。港湾調査につきましては、年２回あります。その場でまず発見されたかどうかにもよるのですが、発見された場合には、必ずその場とその後の調査を行います。","voiceIndex":39,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"一応定着していないということですので、そこはそれが引き続き定着しないようにしていただきたいと思いますし、水際対策も、やはりこの間毎年出ていますので、強化を国にもぜひ求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-013"}]},{"id":"topic-04","title":"しなバス試行運行の実施状況","agenda":"しなバス試行運行の実施状況","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"それで今回、利用状況を見ますと、１日あたりの利用者は、合計のところを見ると、平均４７４人、１便あたりの利用者数は８.４８人ということで、それで、収支率５０％との関係を見ると、１日あたり５３５人、１便あたりだと６.３７人ということになっていますが、一つは、１日あたりと１便あたりで基準を上回ったり下回ったりしているのですけれども、そこの理由を一つ伺いたいのと、あと、今回。","respondent":"鈴木都市計画課長","answer":"１点目の、資料、別紙、実際の利用者数をお示ししています４月５月６月の１日あたりの利用者数、１便あたりの利用者数、これは実際の数字を記載させていただいているところですが、それで、先ほどその後にご紹介いただいた運行のダイヤ改正の後。","voiceIndex":46,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"便数とか運行の仕方は柔軟に試行運行の中で変えていくということでしたので、ぜひそうしていただきたいと思いますけれども、先ほどの数字のところ、目安と実績で違うというお話だったのですが、平均したときの１日あたりのところと１便あたりのところで考えると、基準、片方が上回ったり、片方が下回ったりしているのですけれども、平均するとあまりそういうことはないのかなという気がしたので。","respondent":"鈴木都市計画課長","answer":"ほかのルートは、循環ルートとともに大崎ルート、荏原ルートのご質問だと思うのですが、そちらについては、検討過程の中で、候補ルート案の３本のうち１つの試行運行を開始したわけですが、残りの２本については、試行運行の状況を踏まえて判断していくですので。","voiceIndex":48,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"私が乗ったときにも、高齢のご夫婦が乗られていまして、降りるときに手すりを持って降りられていたので、やはりそうしたお年寄りの方も移動しやすい、外出しやすいようなバスになっていると思いますので、そうしたところで、この地域だけでなくて、ほかのところでもぜひやっていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-016"},{"speaker":"横山委員","kind":"確認","question":"ご説明ありがとうございました。別紙２の２ページのところからお伺いしてまいります。こちら、お問合せ内容のところで少し気になったのですけれども、ベビーカーの乗り降りについて、現在、どのような対応をされているのか確認させてください。現在つかめている状況が５０％以上ぐらいに達しているのかどうかというところ、分かりましたら、状況を教えてください。","respondent":"鈴木都市計画課長","answer":"私も４月中は何度かバスに乗ったり、利用者の方の状況を見ましたけれども、小さいお子さんというか、小学校、中学校のお子さんが写真を撮りながら乗っていたり、ご高齢の方がバスで話している内容を聞いたこともありましたけれども、会話をされながら、ここで降りられるねとか。","voiceIndex":52,"id":"exchange-017"},{"speaker":"横山委員","kind":"確認","question":"区民の方々のやはり期待がある事業ですので、４月の利用者数に表れているのかと思っていたのですけれども、そういった形で期待に応えてスタートしていただいて、なかなか車両の部分とか、難しかったところがあったかと思うのですけれども、フレキシブルに区としても対応していただきながら進めていただいているのだということが確認できて、うれしく思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"３点お伺いしたいと思います。１点目は、数字の確認です。５６掛ける３台掛ける３０ではなく、１台、そうすると８から９便の運行という理解でいいのかという、１点目はその確認です。今、試行運行なので、まだあれですけれども、本格導入といったところでは、設置可能なところでは、屋根の設置というのが要望でまた上がってくるかと。そうしたところをお考えかどうかというところが２点目です。","respondent":"鈴木都市計画課長","answer":"失礼いたしました。バス停の屋根があったほうがいいですが、基本的に、道路内にバス停の建築物を設置する場合の建築基準法上の基準もございまして、ルート的に、例えば、滝王子通りなどは設置できないかと。","voiceIndex":56,"id":"exchange-019"},{"speaker":"こんの委員","kind":"質問・要望","question":"ありがとうございました。利用者数の数字の確認は理解できました。それから、バス停の屋根、確かに設置できる場所とできない場所、それも理解できます。できれば、それを前提にという言い方もここでしていいかどうか分かりませんが、そうした声も踏まえながら、きちんとこの４年間で検証なり調査研究なりをしておいていただければと思いますので、何かお答えがあればですけれども、お願いします。","respondent":"鈴木都市計画課長","answer":"バス停の上屋、それから運賃含めて、検証していく試行期間が今まさにこれからスタートして行っていくことになりますので、しっかり所管としても、検証、検討、事前の準備含めて行っていきたいです。","voiceIndex":58,"id":"exchange-020"}]},{"id":"topic-05","title":"風営法等の改正に伴う地区計画の一括変更に係る説明会の開催","agenda":"風営法等の改正に伴う地区計画の一括変更に係る説明会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"規制をしない地区というのはあるのでしょうか。規制をしないのがあるのかどうかということと、今回この１５地区については、引き続き明るいナイトクラブ、ダンスホールを規制するということですけれども、その理由は何か伺います。それで、平成２８年６月に施行されたということですけれども、このタイミングになった理由を伺いたいと思います。そこも伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今、手持ちに即答できる数字を把握してございませんが、今ご説明した１５地区以上の数は、区の地区計画としてあるという理解です。木密のほうでも大分地区計画がありますし、数的には１５以上の地区計画が都決定分、区決定分、あるということになっています。","voiceIndex":64,"id":"exchange-021"},{"speaker":"のだて委員","kind":"提案","question":"そうすると、原案のところでは、これまでどおりの規制内容で提案する考え方ということですね。分かりました。そのほうが関係する住民の方が参加しやすいかと思うのですが、いかがかというところと、２か所にした理由を伺いたいと思います。それで、関係者への戸別配布を行って周知をしていくということですが、地区計画内の住民の皆さんには全員配布をするのかどうかというところを確認させてください。","respondent":"鈴木都市計画課長","answer":"説明会の開催数ですが、基本的には、従前のそれまでの規制を、風営法が改正されて、風営法の関係の条文を引っ張っている関係上、整合が取れていないというところでの今回都市計画的な変更ですので、内容も踏まえながら、あと、地区計画の数も踏まえながら、それから。","voiceIndex":66,"id":"exchange-022"}]},{"id":"topic-06","title":"品川区まちづくりマスタープラン改定に係るオープンハウス型説明会の開催","agenda":"品川区まちづくりマスタープラン改定に係るオープンハウス型説明会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"なぜ実施しないのか伺います。それと、オープンハウス型の説明会、先ほど少し説明がありましたけれども、足を止めてもらえるようにということで設定をされたということですが、今まで地域センターとかで結構説明会をやられていますので、そうしたところも身近なのではないかと思うのですが、地域センターでの実施についても伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"１点目の、現計画は当時、ご紹介いただいたように、一度、講演会という形のものを実施させていただきましたが、今回、先ほども冒頭にご説明させていただきましたが、これまでの取組み、検討状況をまずお示しして、ご意見をいただく方法として。","voiceIndex":73,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういった形でやっていくということが必要なのではないかと思うのですが、いかがでしょうか。その段階でまたパブリックコメントがあるわけですから、そこでも説明会を行っていくということが必要ではないかと思いますが、いかがでしょうか。今回のオープンハウス型の説明会で出された意見というのは、計画に反映されるのか、どう反映されるのかを含めて伺います。","respondent":"鈴木都市計画課長","answer":"最後にパブリックコメントを実施したわけですが、今回、こうした検討の段階でもオープンハウス型の説明会を行わせていただいて取りまとめて、基本的には広くパブリックコメントでご意見をいただきたいというところで。","voiceIndex":75,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、教室型はやらないということですけれども、やはりいろいろな方の意見を聞くということも、自分の視点だけではなく、話を聞けるというのも重要だと思うのです。オープンハウス型ですと、一対一のやり取りのみということですから、地域の人がどう思っているのかも含めて知る機会にもなりますので、やはり教室型説明会を適宜実施していただきたいと強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-025"}]},{"id":"topic-07","title":"羽田空港の機能強化","agenda":"羽田空港の機能強化","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"このやり方は大型機に限定しているのですけれども、大型機限定としている理由も伺います。それと、資料４のところで、３、４ページのところですけれども、定期訓練の緩和をしていくと、方向性が記載されていますけれども、そうすると安全性が低下することはないのかということを考えてしまうのですが、区としてはどのようにお考えなのか、見解を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"資料４の３ページ、４ページのところの効率的な訓練というところで、これは国が、ここの資料の記載もそうですが、全体的にやはり固定化回避のルートを検討していく場合に、まずは安全性、これは当然、何物にも代えて優先順位を高くしていかなければいけないというのは。","voiceIndex":82,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと併せて、今回の検討会、５回目になりますけれども、この検討を行っているのは、品川区の上を飛んできているＡ滑走路、Ｃ滑走路を使うという前提の下での検討なのかというところを確認させていただきたいのと、あと、今、２方式に絞って検討されておりますけれども、この２方式は品川区の上を飛ぶことはないのかどうか、そこを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"安全をないがしろにして検討を進めていただきたいということは当然ございませんので、当然ながら安全は、それは誰もが統一の考えとして今進めていただいていることだと思いますので、そこは言うまでもなくしっかり行っていただきたいです。","voiceIndex":84,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"そうした中で、区としては少しでも軽減していきたいというところがあるのかもしれませんが、やはり区民への被害は残ることになってしまいますので、羽田新ルート、都心の上を飛ぶルートというのを中止するのが一番安全であり、被害もなくなると思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"やはり区民への説明、あるいは落下物、騒音関係の軽減に向けた取組みを、これ、運行開始前からですが、引き続き国には強く求めていきたいというところの中の一つとして、同様に、このルートが決まって運用を開始したので、これをずっと続けますということではなくて。","voiceIndex":86,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、基準の素案が出てくるまでも一定の間隔があるということになりますので、その間、住民への被害が続いてしまうということになりますから、やはり私は、固定化回避というのは住民へのごまかしであって、新ルートを中止していくということが住民の願いだと思いますので、区としてもその立場にぜひ立っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-029"}]},{"id":"topic-08","title":"無電柱化推進事業（文庫の森～補助２６号線）における事業説明会","agenda":"無電柱化推進事業（文庫の森～補助２６号線）における事業説明会","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"住民への影響というのがあるかと思うのですが、そこのところを伺いたいのと、工事中の通行というのはどうなるのか伺いたいと思います。そういったことを含めて、お知らせはビラの回覧と沿道へのポスティングを行うということですが、対象範囲がどの辺りになるのか伺います。それと最後に、ほかの路線の無電柱化事業の進捗状況を伺いたいと思います。","respondent":"森道路課長","answer":"現在のほかの無電柱化事業についてですが、前々回の建設委員会でも少しご説明をさせていただきましたけれども、競馬場通りの無電柱化について進めているところです。","voiceIndex":94,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"工事のところで、低騒音重機を使うということですけれども、なかなかそれでも近接しているお宅ではやはりうるさいということがありますので、そこは様々工夫をしていただいて、影響がないようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-031"}]},{"id":"topic-09","title":"天王洲公園野球場ＡＢ面ナイター照明ＬＥＤ化その他工事","agenda":"天王洲公園野球場ＡＢ面ナイター照明ＬＥＤ化その他工事","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"交換にあたってどういった判断をされているのか伺いたいと思います。それと、今回、休業期間が来年１月４日から２月２８日であるということで、この間の利用者への対応というのはどうされるのか伺います。一応、仮設電源で対応するということですが、工事期間中、野球場のＣ面は使えるということだと思うのですが、もう少し詳しく、どういった対応になるのか伺いたいと思います。","respondent":"森道路課長","answer":"実際の停電期間は２日間で、１日予備を考えておりまして、平日の中で、管理事務所の必要な機器であったりとか、トイレであったりとか、それから公園の明かりであったりとか、そういった安全に関わるところは仮設電源で対応しようと考えていますけれども、今。","voiceIndex":102,"id":"exchange-032"},{"speaker":"横山委員","kind":"確認","question":"ご説明ありがとうございました。幾つか伺ってまいります。現在は水銀灯ということで、耐用年数というのは国から示されているのが平均１５年ということでよろしいのでしょうか。多分、今後も１月から２月のメンテナンス工事というのを毎年やられるかと思うのですけれども、その中で特に変更なくメンテナンスは行われていくのかというところを確認させてください。","respondent":"森道路課長、高梨公園課長","answer":"ＬＥＤにつきましては１０年程度と聞いておりますけれども、その間のメンテナンスについては、蛍光灯やそういったもののように、球切れということがないので、比較的メンテナンスについては楽になる方向かと考えております。毎年１月から２月の施設の休業期間は、照明だけではなくて、例えば、野球場の土の部分の整備であるとか、人工芝の点検であるとか、そういったものを総合的に行っているものでございまして、こちらについては、例年。","voiceIndex":105,"id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"公園のほうを含めて総合的にお願いできればと考えています。そして、停電の期間が２月の中頃２日間で、１日は夜間ということになっているかと思うのですけれども、何もないとは思うのですが、こういう時期ですので、万が一のときのことですけれども、万が一の例えば災害等、何か緊急のことが起きたときに、仮電源というのはしっかり緊急時にも使用していけるのか、その辺りのところだけ確認させてください。","respondent":"森道路課長","answer":"仮設の電源ですけれども、工事については２日間の予定で予備が１日ということで、全体的には３日と考えているところです。","voiceIndex":108,"id":"exchange-034"}]},{"id":"topic-10","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"添加剤の量を適切に調整できなかったのが原因ということで、マシン前面に土砂が付着して、そのためにマシンが損傷したということで、こうした状況のために、工事再開も来年度前半を目標にということで、明確に示せない状況にもなっていますので、分かる範囲でということになってしまうと思うのですが、区はＪＲ東海からこれについての説明を受けているのかどうかということと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-035"}]},{"id":"topic-11","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私も調べますけれども、ぜひお聞きしたいのは、私が聞いたのは、近隣に地下鉄がありまして、それの、今、請願駅ではないけれども、駅を造ろうとしたと。だけど、そこにはやはり傾斜があったり、何らかの形があって断念をしたというのがあると伺って、どういう理由で断念したのかもう一度お聞きしたい。場所とかそういうのをもう一回よく調べます。調べますが、それがもし分かれば教えていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4358#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":38672,"voices":121}}]);
